def _gcs_client():
    if not _GCS_OK:
        raise RuntimeError(f"google-cloud-storage import failed: {_GCS_IMPORT_ERR}")
    return storage.Client()

def _gcs_put_bytes(bucket: str, path: str, data: bytes, content_type: str):
    if not bucket:
        raise RuntimeError("CENTRAL_BLOB_BUCKET is not set")
    c = _gcs_client()
    b = c.bucket(bucket)
    blob = b.blob(path)
    blob.upload_from_string(data, content_type=content_type)

def _gcs_get_bytes(bucket: str, path: str) -> bytes:
    if not bucket:
        raise RuntimeError("CENTRAL_BLOB_BUCKET is not set")
    c = _gcs_client()
    b = c.bucket(bucket)
    blob = b.blob(path)
    return blob.download_as_bytes()

