def load_tenant_theme(tenant_id: str) -> dict:
    """Firestoreからテーマ設定を読み込む。失敗時はデフォルト値を返す。"""
    try:
        _doc = db.collection("system_settings").document(f"theme_config_{tenant_id}").get()
        if _doc.exists:
            return {**_THEME_DEF_GLOBAL, **(_doc.to_dict() or {})}
    except Exception:
        pass
    return _THEME_DEF_GLOBAL.copy()

