def load_latest_investment_signals() -> dict:
    """
    Firestore: investment_signals サブコレクションから全件取得。
    戻り値: {"asof_date": str, "goal_bottom": [...], "watch_big_sell": [...], "all_stocks": [...], ...}
    """
    try:
        docs = (
            db.collection("investment_signals")
            .order_by("asof_date", direction=firestore.Query.DESCENDING)
            .limit(1)
            .stream()
        )
        for doc in docs:
            data = doc.to_dict()
            doc_ref = db.collection("investment_signals").document(doc.id)

            data["goal_bottom"]    = [d.to_dict() for d in doc_ref.collection("goal_bottom").stream()]
            data["watch_big_sell"] = [d.to_dict() for d in doc_ref.collection("watch_big_sell").stream()]
            data["all_stocks"]     = [d.to_dict() for d in doc_ref.collection("all_stocks").stream()]

            return data
    except Exception as e:
        st.warning(f"投資シグナル読み込み失敗: {e}")
    return {}

# ============================================================
# 投資シグナル → RAG (sources / knowledge_chunks) 書き込み
# ============================================================
def push_signals_to_rag(signal_list: list, asof_date: str, signal_type: str, tenant_id: str) -> int:
    """
    GOAL_BOTTOM / WATCH_BIG_SELL の各銘柄を
    source_chunks（embedding付き）+ tenant_source_links に書き込む。
    rag_retrieve_chunks() が正しく拾えるように upsert_doc_chunks() を経由する。
    """
    if not signal_list:
        return 0

    source_id = f"investment_signal:{asof_date}:{signal_type}"

    # ① 全銘柄のテキストを結合して1ソースとして upsert_doc_chunks に渡す
    #    （1銘柄1チャンクにしたい場合は後述の個別書き込みに切り替え）
    lines = []
    for item in signal_list:
        code         = str(item.get("code", ""))
        company_name = item.get("company_name", code)
        sector       = item.get("sector", "不明")
        close        = item.get("close", "")
        sell_score   = item.get("sell_score", "")
        bottom_score = item.get("bottom_score", "")
        rank_score   = item.get("rank_score", "")
        capit_date   = item.get("capit_date", "")
        rebound      = item.get("rebound_1_2d", "")
        sell_days    = item.get("sell_days", "")

        if signal_type == "goal_bottom":
            lines.append(
                f"【反発根拠】銘柄コード: {code}（{company_name}）セクター: {sector}\n"
                f"基準日: {asof_date}　終値: {close}\n"
                f"キャピチュレーション日: {capit_date}　翌日反発: {rebound}\n"
                f"sell_score: {sell_score}　bottom_score: {bottom_score}　rank_score: {rank_score}\n"
                f"判定: 大口売り込み後のキャピチュレーション＋反発確認済み。反発底打ち候補。"
            )
        else:
            lines.append(
                f"【売り込み監視】銘柄コード: {code}（{company_name}）セクター: {sector}\n"
                f"基準日: {asof_date}　終値: {close}\n"
                f"売り込み継続日数: {sell_days}\n"
                f"sell_score: {sell_score}　bottom_score: {bottom_score}　rank_score: {rank_score}\n"
                f"判定: 大口の継続的な売り込みを検知。底打ち前の監視段階。"
            )

    content_text = "\n\n---\n\n".join(lines)
    title = f"投資シグナル {signal_type} {asof_date}"

    # ② sources コレクションにメタ情報を登録
    sources_col().document(source_id).set({
        "source_id":   source_id,
        "title":       title,
        "type":        "investment_signal",
        "signal_type": signal_type,
        "asof_date":   asof_date,
        "created_at":  datetime.datetime.now().isoformat(),
        "chunk_count": len(signal_list),
    }, merge=True)

    # ③ embedding付きチャンクを source_chunks に書き込む（既存の正規ルート）
    wrote = upsert_doc_chunks(
        tenant_id=tenant_id,
        doc_id=source_id,
        title=title,
        category="investment",
        source_type="investment_signal",
        content_text=content_text,
        chunk_chars=1200,
        overlap=200,
    )

    # ④ tenant_source_links に登録（これがないと rag_retrieve_chunks がスキップする）
    from datetime import datetime as _dt
    link_id = tenant_source_link_doc_id(tenant_id, source_id)
    tenant_source_links_col().document(link_id).set({
        "tenant_id":    tenant_id,
        "source_id":    source_id,
        "category":     "investment",
        "source_type":  "investment_signal",
        "enabled":      True,
        "force_include": False,
        "priority":     0,
        "updated_at":   firestore.SERVER_TIMESTAMP,
    }, merge=True)

    return wrote


def record_signal_feedback(
    code: str, asof_date: str, signal_type: str, label: int, tenant_id: str
):
    """
    ユーザーの銘柄評価を lgbm_training_logs に記録する。
    label: 1=有効(反発した)  0=無効(反発しなかった)
    """
    log_id = f"{asof_date}:{signal_type}:{code}"
    (
        db.collection("tenants").document(tenant_id)
          .collection("lgbm_training_logs").document(log_id)
    ).set({
        "log_id":      log_id,
        "code":        code,
        "asof_date":   asof_date,
        "signal_type": signal_type,
        "label":       label,
        "tenant_id":   tenant_id,
        "recorded_at": datetime.datetime.now().isoformat(),
    }, merge=True)



def train_lgbm_purpose_mode(tenant_id: str) -> dict:
    """
    usage_logs の prompt × purpose_mode × level_score から
    purpose_mode 自動判別モデルを学習し
    tenants/{tenant_id}/lgbm_models/purpose_mode に pickle(base64) で保存する。
    高ランク（level_score >= 80）ユーザーの選択を正解ラベルとして採用。
    戻り値: {"trained": bool, "n_samples": int, "accuracy": float, "message": str}
    """
    import pickle
    from sklearn.model_selection import train_test_split
    from sklearn.metrics import accuracy_score

    try:
        import lightgbm as lgb
        def _build_model():
            return lgb.LGBMClassifier(
                n_estimators=100, learning_rate=0.05,
                num_leaves=15, random_state=42,
                n_jobs=1, verbose=-1,
            )
        _model_label = "LightGBM"
    except Exception:
        from sklearn.ensemble import GradientBoostingClassifier
        def _build_model():
            return GradientBoostingClassifier(
                n_estimators=100, learning_rate=0.05,
                max_depth=4, random_state=42,
            )
        _model_label = "GradientBoosting(fallback)"

    MODE_LIST = ["auto", "numeric", "growth", "control", "creative", "marketing"]
    MODE_KWS = {
        "numeric":   ["数字","売上","KPI","指標","数値","利益","コスト","単価","件数","率","円","万"],
        "growth":    ["成長","訓練","スキル","改善","能力","育成","レベル","強化","習慣"],
        "control":   ["構造","支配","管理","制御","組織","ルール","仕組み","体制","権限"],
        "creative":  ["アイデア","発想","創造","クリエイティブ","デザイン","企画","コンセプト"],
        "marketing": ["集客","マーケ","SNS","広告","認知","ブランド","流入","コンテンツ"],
    }

    def _extract_features(text: str) -> list:
        t = (text or "").lower()
        return [
            len(t),
            sum(1 for w in MODE_KWS["numeric"]   if w in t),
            sum(1 for w in MODE_KWS["growth"]    if w in t),
            sum(1 for w in MODE_KWS["control"]   if w in t),
            sum(1 for w in MODE_KWS["creative"]  if w in t),
            sum(1 for w in MODE_KWS["marketing"] if w in t),
        ]

    # ① usage_logs から学習データ収集
    _logs = _fs_stream_list(db.collection("usage_logs"), limit=3000)
    _rows = []
    for _d in _logs:
        _data = _d.to_dict() if hasattr(_d, "to_dict") else _d
        if not _data:
            continue
        _mode = (_data.get("purpose_mode") or "").strip().lower()
        if _mode not in MODE_LIST or _mode == "auto":
            continue
        _prompt = (_data.get("prompt") or "").strip()
        if not _prompt:
            continue
        # level_score が高いユーザーのデータを優先採用
        _uid = _data.get("user_id") or _data.get("uid") or ""
        _score = 0
        try:
            _u = users_col().document(_uid).get()
            _score = int((_u.to_dict() or {}).get("level_score", 0)) if _u.exists else 0
        except Exception:
            pass
        _weight = 2.0 if _score >= 200 else (1.5 if _score >= 80 else 1.0)
        _rows.append({
            "features": _extract_features(_prompt),
            "label":    MODE_LIST.index(_mode),
            "weight":   _weight,
        })

    if len(_rows) < 20:
        return {"trained": False, "n_samples": len(_rows), "accuracy": 0.0,
                "message": f"学習データ不足（{len(_rows)}件 / 最低20件必要）"}

    import numpy as _np_lgbm
    _X = _np_lgbm.array([r["features"] for r in _rows])
    _y = _np_lgbm.array([r["label"]    for r in _rows])
    _w = _np_lgbm.array([r["weight"]   for r in _rows])

    _X_tr, _X_val, _y_tr, _y_val, _w_tr, _ = train_test_split(
        _X, _y, _w, test_size=0.2, random_state=42, stratify=_y
    )
    _model = _build_model()
    try:
        _model.fit(_X_tr, _y_tr, sample_weight=_w_tr)
    except TypeError:
        _model.fit(_X_tr, _y_tr)
    _acc = float(accuracy_score(_y_val, _model.predict(_X_val))) if len(_X_val) > 0 else 0.0

    # ② Firestore に保存
    _model_b64 = base64.b64encode(pickle.dumps(_model)).decode("utf-8")
    (
        db.collection("tenants").document(tenant_id)
          .collection("lgbm_models").document("purpose_mode")
    ).set({
        "model_b64":     _model_b64,
        "feature_names": ["text_len","numeric_kw","growth_kw","control_kw","creative_kw","marketing_kw"],
        "mode_list":     MODE_LIST,
        "n_samples":     len(_rows),
        "accuracy":      _acc,
        "trained_at":    datetime.datetime.now().isoformat(),
        "tenant_id":     tenant_id,
        "model_type":    _model_label,
    })

    return {"trained": True, "n_samples": len(_rows), "accuracy": _acc,
            "message": f"{_model_label} purpose_mode モデル学習完了 (n={len(_rows)}, acc={_acc:.3f})"}

def train_lgbm_from_signal_logs(tenant_id: str) -> dict:
    """
    lgbm_training_logs のラベル × knowledge_chunks のスコアで
    LightGBM 2値分類（反発有効=1/無効=0）を学習し
    lgbm_models/investment_signal に pickle(base64) で保存する。
    戻り値: {"trained": bool, "n_samples": int, "accuracy": float, "message": str}
    """
    import pickle
    from sklearn.model_selection import train_test_split
    from sklearn.metrics import accuracy_score

    # LightGBM は libgomp 依存のため環境によって失敗する。
    # 失敗時は sklearn GradientBoosting で代替（精度は同等以上、依存なし）
    try:
        import lightgbm as lgb
        def _build_model():
            return lgb.LGBMClassifier(
                n_estimators=100, learning_rate=0.05,
                num_leaves=15, random_state=42,
                n_jobs=1,          # OpenMP スレッド数を明示的に制限
                verbose=-1,
            )
        _model_label = "LightGBM"
    except Exception:
        from sklearn.ensemble import GradientBoostingClassifier
        def _build_model():
            return GradientBoostingClassifier(
                n_estimators=100, learning_rate=0.05,
                max_depth=4, random_state=42,
            )
        _model_label = "GradientBoosting(fallback)"

    # ① ログ取得（投資シグナル分のみ）
    _logs = [
        d.to_dict()
        for d in (
            db.collection("tenants").document(tenant_id)
              .collection("lgbm_training_logs").stream()
        )
        if d.to_dict().get("signal_type") in ("goal_bottom", "watch_big_sell")
    ]

    if len(_logs) < 10:
        return {"trained": False, "n_samples": len(_logs), "accuracy": 0.0,
                "message": f"学習データ不足（{len(_logs)}件 / 最低10件必要）"}

    # ② スコアを knowledge_chunks から取得して特徴量を構築
    _rows = []
    _chunks_ref = (
        db.collection("tenants").document(tenant_id)
          .collection("knowledge_chunks")
    )
    for _log in _logs:
        _label = _log.get("label", -1)
        if _label < 0:
            continue
        _chunk_id = (
            f"investment_signal:{_log['asof_date']}"
            f":{_log['signal_type']}:{_log['code']}"
        )
        _snap = _chunks_ref.document(_chunk_id).get()
        if not _snap.exists:
            continue
        _d = _snap.to_dict()
        _rows.append({
            "label":        _label,
            "rank_score":   float(_d.get("rank_score") or 0),
            "sell_score":   float(_d.get("sell_score") or 0),
            "bottom_score": float(_d.get("bottom_score") or 0),
            "signal_type":  1 if _log.get("signal_type") == "goal_bottom" else 0,
        })

    if len(_rows) < 10:
        return {"trained": False, "n_samples": len(_rows), "accuracy": 0.0,
                "message": f"スコア付きデータ不足（{len(_rows)}件）"}

    import pandas as _pd_lgbm
    _df_t = _pd_lgbm.DataFrame(_rows)
    _X = _df_t[["rank_score", "sell_score", "bottom_score", "signal_type"]].values
    _y = _df_t["label"].values

    _X_tr, _X_val, _y_tr, _y_val = train_test_split(_X, _y, test_size=0.2, random_state=42)
    _model = _build_model()
    _model.fit(_X_tr, _y_tr)
    _acc = float(accuracy_score(_y_val, _model.predict(_X_val))) if len(_X_val) > 0 else 0.0

    # ③ モデルを Firestore に保存（pickle → base64）
    _model_b64 = base64.b64encode(pickle.dumps(_model)).decode("utf-8")
    (
        db.collection("tenants").document(tenant_id)
          .collection("lgbm_models").document("investment_signal")
    ).set({
        "model_b64":     _model_b64,
        "feature_names": ["rank_score", "sell_score", "bottom_score", "signal_type"],
        "n_samples":     len(_rows),
        "accuracy":      _acc,
        "trained_at":    datetime.datetime.now().isoformat(),
        "tenant_id":     tenant_id,
    })

    return {"trained": True, "n_samples": len(_rows), "accuracy": _acc,
            "message": f"学習完了 [{_model_label}] (n={len(_rows)}, acc={_acc:.2f})"}


