def generate_user_guide(tenant_id: str = None, enabled_modes: list = None) -> str:
    """
    有効モード一覧からガイド文を自動生成する。
    enabled_modes が未渡しの場合は load_purpose_mode_config から取得。
    """
    if enabled_modes is None:
        try:
            enabled_modes = load_purpose_mode_config(tenant_id or DEFAULT_TENANT)
        except Exception:
            enabled_modes = list(_DEFAULT_ENABLED_MODES)

    lines = []
    for mk in enabled_modes:
        reg = MODE_REGISTRY.get(mk)
        if not reg or mk == "auto":
            continue
        label = reg["label"]
        desc  = reg.get("guide_desc", "")
        risk  = reg.get("risk_profile", "general")
        risk_note = " ⚠️法的助言ではありません" if risk == "high_stakes" else \
                    " ⚠️参考情報・専門家確認推奨" if risk == "advisory" else ""
        lines.append(f"{label}：\n- {desc}{risk_note}")

    mode_section = "\n\n".join(lines) if lines else "（業種設定後に表示されます）"
    return DEFAULT_USER_GUIDE.replace("{mode_guide_section}", mode_section)

# ============================================================
# Smart Content Renderer（表・グラフ自動検出レンダリング）
# ============================================================
def render_smart_content(text: str, msg_key: str = "") -> None:
    """
    AI回答をスマートレンダリング。
    - Markdown表（|列|列| 形式）を検出 → st.dataframe + CSVダウンロード + 数値列があればグラフ
    - それ以外 → st.markdown（通常表示）
    """
    import re

    # Markdownテーブルパターン（ヘッダー行 + セパレーター行 + データ行1行以上）
    TABLE_PATTERN = re.compile(
        r'(^\|[^\n]+\|\n)(^\|[\s|:\-]+\|\n)((?:^\|[^\n]+\|\n?)+)',
        re.MULTILINE,
    )

    segments: list = []
    last_end = 0

    for match in TABLE_PATTERN.finditer(text):
        if match.start() > last_end:
            segments.append(("text", text[last_end:match.start()]))
        segments.append(("table", match.group(0)))
        last_end = match.end()
    if last_end < len(text):
        segments.append(("text", text[last_end:]))

    # テーブルが1つも無ければ通常markdownで返す
    if not any(s[0] == "table" for s in segments):
        st.markdown(text)
        return

    table_idx = 0
    for seg_type, seg_content in segments:
        if seg_type == "text":
            if seg_content.strip():
                st.markdown(seg_content)
        else:
            try:
                lines = [l.strip() for l in seg_content.strip().splitlines() if l.strip()]
                if len(lines) < 3:
                    st.markdown(seg_content)
                    continue

                # ヘッダー解析（lines[0]）
                headers = [h.strip() for h in lines[0].strip("|").split("|")]
                headers = [h for h in headers if h]  # 空文字除去

                # データ行解析（lines[2:] ※lines[1]はセパレーター）
                rows = []
                for row_line in lines[2:]:
                    cells = [c.strip() for c in row_line.strip("|").split("|")]
                    while len(cells) < len(headers):
                        cells.append("")
                    rows.append(cells[:len(headers)])

                df = pd.DataFrame(rows, columns=headers)

                # 数値変換（カンマ・円記号・%を除去して試みる）
                for col in df.columns:
                    cleaned = (
                        df[col].astype(str)
                        .str.replace(",", "", regex=False)
                        .str.replace("¥", "", regex=False)
                        .str.replace("￥", "", regex=False)
                        .str.replace("円", "", regex=False)
                        .str.replace("%", "", regex=False)
                        .str.strip()
                    )
                    converted = pd.to_numeric(cleaned, errors="coerce")
                    # 半数以上が数値に変換できる列のみ数値型にする
                    if converted.notna().sum() >= max(1, len(df) * 0.5):
                        df[col] = converted

                # ─── テーブル表示 ───
                st.dataframe(df, use_container_width=True, hide_index=True)

                # ─── CSVダウンロード ───
                _dl_key = f"_smart_tbl_dl_{msg_key}_{table_idx}"
                csv_bytes = df.to_csv(index=False, encoding="utf-8-sig").encode("utf-8-sig")
                st.download_button(
                    label="📥 CSV保存",
                    data=csv_bytes,
                    file_name=f"table_{table_idx + 1}.csv",
                    mime="text/csv",
                    key=_dl_key,
                )

                # ─── 数値列があればグラフ ───
                # Unnamed列はグラフ対象から除外
                numeric_cols = [
                    c for c in df.select_dtypes(include="number").columns
                    if not str(c).startswith("Unnamed")
                ]
                if numeric_cols and len(df) >= 2:
                    with st.expander("📊 グラフ表示", expanded=False):
                        text_cols = [
                            c for c in df.columns
                            if c not in numeric_cols and not str(c).startswith("Unnamed")
                        ]
                        # X軸選択
                        _x_key = f"_smart_tbl_x_{msg_key}_{table_idx}"
                        x_col = st.selectbox(
                            "X軸（横軸）",
                            text_cols if text_cols else ["（行番号）"],
                            key=_x_key,
                        )
                        # Y軸選択（複数可）
                        _y_key = f"_smart_tbl_y_{msg_key}_{table_idx}"
                        selected_y = st.multiselect(
                            "Y軸（縦軸・複数選択可）",
                            numeric_cols,
                            default=numeric_cols[:1],
                            key=_y_key,
                        )
                        if not selected_y:
                            st.caption("Y軸の列を1つ以上選択してください。")
                        else:
                            chart_df = df[selected_y].copy()
                            if text_cols and x_col != "（行番号）":
                                chart_df.index = df[x_col].astype(str).values
                            _ct_key = f"_smart_tbl_ct_{msg_key}_{table_idx}"
                            chart_type = st.radio(
                                "グラフ種別",
                                ["棒グラフ", "折れ線グラフ"],
                                horizontal=True,
                                key=_ct_key,
                            )
                            if chart_type == "棒グラフ":
                                st.bar_chart(chart_df)
                            else:
                                st.line_chart(chart_df)

                table_idx += 1

            except Exception:
                # パース失敗は安全にmarkdownフォールバック
                st.markdown(seg_content)

