# --- ASCEND ロゴの共通定義（SVG） ---
ASCEND_LOGO_SVG_CODE = """
<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" style="width:{width}px; height:{width}px;">
    <path d="M50 8 L92 88 H8 Z" stroke="#1E3A8A" stroke-width="3" fill="none"/>
    <path d="M50 20 L78 78 H65 L50 45 L35 78 H22 Z" fill="#1E3A8A"/>
    <rect x="38" y="55" width="24" height="5" fill="#1E3A8A"/>
</svg>
"""

def render_svg_logo(width=90, show_text=True, tenant_id: str = None):
    """SVGロゴをbase64 imgタグでレンダリングする。Firestoreにlogo_urlがあれば優先使用。"""
    import base64
    # Firestoreからテナントのlogo_urlを取得
    _logo_url = ""
    try:
        _tid = tenant_id or DEFAULT_TENANT
        _doc = db.collection("system_settings").document(f"theme_config_{_tid}").get()
        if _doc.exists:
            _logo_url = (_doc.to_dict() or {}).get("logo_url", "")
    except Exception:
        pass

    if _logo_url:
        logo_html = f'<div style="text-align:center; padding:5px 0;">'
        logo_html += f'<img src="{_logo_url}" width="{width}" style="display:block;margin:auto;max-height:{width*2}px;object-fit:contain;" />'
        logo_html += '</div>'
        return logo_html

    # デフォルトSVGロゴ
    svg_content = ASCEND_LOGO_SVG_CODE.format(width=width)
    b64 = base64.b64encode(svg_content.encode("utf-8")).decode("utf-8")
    img_tag = f'<img src="data:image/svg+xml;base64,{b64}" width="{width}" height="{width}" style="display:block;margin:auto;" />'
    logo_html = f'<div style="text-align:center; padding:5px 0;">{img_tag}'
    if show_text:
        logo_html += f'<div style="font-family: system-ui, -apple-system, sans-serif; color: #1E3A8A; font-size: {max(0.6, width/100)}rem; letter-spacing: 0.25em; margin-top: 6px; font-weight: 600;">ASCEND</div>'
    logo_html += '</div>'
    return logo_html

