SESSION_TIMEOUT_MINUTES = 15  # デフォルト値（管理側で上書き可能）

def get_session_timeout_minutes() -> int:
    """Firestoreからの取得値に対し、型変換と境界値チェックを厳格に行う"""
    try:
        doc = db.collection("system_settings").document("global_config").get()
        if doc.exists:
            v = (doc.to_dict() or {}).get("session_timeout_minutes")
            if v is None:
                return SESSION_TIMEOUT_MINUTES
            try:
                val = int(v)
            except (ValueError, TypeError):
                return SESSION_TIMEOUT_MINUTES
            if val > 0:
                return val
    except Exception:
        pass
    return SESSION_TIMEOUT_MINUTES

