def _qp_get_first(key: str, default: str = "") -> str:
    """
    Streamlitの query_params(新) / experimental_get_query_params(旧) 両対応。
    値が list の場合は先頭要素を採用して文字列化。
    """
    v = None
    try:
        v = st.query_params.get(key)
    except Exception:
        v = None

    if v is None:
        try:
            v = st.experimental_get_query_params().get(key)
        except Exception:
            v = None

    if isinstance(v, (list, tuple)):
        v = v[0] if v else default

    if v is None:
        v = default

    return str(v).strip()


def _qp_remove(key: str):
    """URLから指定query paramを除去（可能なAPIで）。失敗しても無視。"""
    try:
        st.query_params.pop(key, None)
        return
    except Exception:
        pass

    try:
        qp = st.experimental_get_query_params()
        qp.pop(key, None)
        st.experimental_set_query_params(**qp)
    except Exception:
        pass

