# -----------------------------
# Helpers & Definitions (Moved UP to avoid NameError)
# -----------------------------

def _now_utc() -> datetime.datetime:
    """常に naive UTC datetime を返す（Python 3.12+ 互換）"""
    return datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)

def _iso(dt: datetime.datetime) -> str:
    return dt.replace(microsecond=0).isoformat()


def _parse_iso(s: str) -> datetime.datetime:
    """
    あらゆるISO形式（Z, +00:00, タイムゾーンなし）を naive UTC に正規化して復元する。
    """
    if not s:
        raise ValueError("Empty ISO string")
    
    # 'Z' サフィックスを Python の fromisoformat が解釈可能な形式に置換
    s = s.replace('Z', '+00:00')
    dt = datetime.datetime.fromisoformat(s)
    
    # タイムゾーン情報がある場合は UTC に変換してから naive 化
    if dt.tzinfo is not None:
        dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    
    return dt

def _safe_float(v, default: float = 0.0) -> float:
    """
    None / 空文字 / 非数 を踏んでも落ちない安全変換。
    """
    try:
        if v is None:
            return default
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip()
        if not s:
            return default
        return float(s)
    except Exception:
        return default
    
# save引数を追加（連続呼び出し時のDuplicateKeyエラー回避用）
def set_shared_mode(raw_token: str, save: bool = True):
    st.session_state[SS_SHARED] = True
    cookies[CK_SHARED] = "1"
    cookies[CK_SHARE_TOKEN] = raw_token
    if save:
        cookies.save()

def clear_auth():
    st.session_state.pop(SS_AUTH, None)
    st.session_state.pop(SS_LAST_ACT, None)
    st.session_state.pop(SS_SHARED, None)
    # share関連cookie・通常auth cookie を全て明示的にクリア
    cookies[CK_ROLE] = ""
    cookies[CK_UID] = ""
    cookies[CK_EXP] = ""
    cookies[CK_SHARED] = ""
    cookies[CK_SHARE_TOKEN] = ""
    cookies[CK_LAST_ACT] = ""
    
    # save()は呼ばず、次のレンダリング冒頭で1回だけ保存
    st.session_state["_pending_cookie_save"] = True
    # ★ ログアウト時は管理判定の sticky フラグも必ずクリアする
    #    （クリアしないと、ログアウト後の rerun でも _is_admin_page=True が残る）
    st.session_state.pop("_ascend_admin_active", None)

def set_auth(role: str, uid: str, days: int, save: bool = True):
    now = _now_utc()
    st.session_state[SS_AUTH] = {"role": role, "uid": uid}
    st.session_state[SS_LAST_ACT] = now
    cookies[CK_ROLE] = role
    cookies[CK_UID] = uid
    cookies[CK_EXP] = _iso(now + datetime.timedelta(days=days))
    cookies[CK_LAST_ACT] = str(now.timestamp())
    if save:
        cookies.save()

def _touch_last_activity_cookie(now: Optional[datetime.datetime] = None, min_interval_sec: int = 30) -> None:
    """
    通常ログインの最終操作時刻を cookie にも同期する。
    ブラウザ再起動後も timeout 判定を貫通させるための補助。
    """
    try:
        now = now or _now_utc()
        prev_raw = cookies.get(CK_LAST_ACT)
        prev_ts = float(prev_raw) if prev_raw not in (None, "") else 0.0
        now_ts = float(now.timestamp())

        if abs(now_ts - prev_ts) >= float(min_interval_sec):
            cookies[CK_LAST_ACT] = str(now_ts)
            cookies.save()
    except Exception:
        pass


def _read_cookie_last_activity() -> Optional[datetime.datetime]:
    try:
        raw = cookies.get(CK_LAST_ACT)
        if raw in (None, ""):
            return None
        ts = float(raw)
        return datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).replace(tzinfo=None)
    except Exception as e:
        print(f"[SECURITY_AUDIT][read_cookie_last_activity] failed: {e}", flush=True)
        return None


def check_timeout_and_logout():
    if SS_AUTH in st.session_state:
        last = st.session_state.get(SS_LAST_ACT)
        now = _now_utc()
        _timeout_min = get_session_timeout_minutes()

        if last:
            diff = (now - last).total_seconds()
            if diff > (_timeout_min * 60):
                if st.session_state.get(SS_SHARED):
                    st.session_state[SS_SHARE_ENDED] = True
                    clear_share_session(save=True)
                else:
                    clear_auth()
                st.session_state["just_logged_out"] = True
                st.session_state["_logout_msg"] = f"{_timeout_min}分間操作がなかったため、自動ログアウトしました。"
                st.rerun()

        # タイムアウトしていない場合のみ最終操作時刻を更新
        st.session_state[SS_LAST_ACT] = now

        # 通常ログインのみ cookie にも同期し、再起動後の timeout を有効化
        if not st.session_state.get(SS_SHARED):
            _touch_last_activity_cookie(now=now, min_interval_sec=30)


def _reset_auto_train_guards() -> None:
    """Streamlit rerun ごとに自己更新ループの多重実行ガードをリセットする。"""
    for _k in list(st.session_state.keys()):
        if str(_k).startswith(_RETRAIN_GUARD_PREFIX):
            st.session_state.pop(_k, None)


def restore_auth_from_cookie() -> bool:
    role = cookies.get(CK_ROLE)
    uid = cookies.get(CK_UID)
    exp_str = cookies.get(CK_EXP)
    if not role or not uid or not exp_str:
        return False

    now = _now_utc()
    try:
        exp_dt = _parse_iso(exp_str)
        if now > exp_dt:
            clear_auth()
            return False
    except Exception:
        return False

    # 管理側の session_timeout_minutes をブラウザ再起動後にも効かせる
    _timeout_min = get_session_timeout_minutes()
    last_cookie_dt = _read_cookie_last_activity()
    if last_cookie_dt is not None:
        diff = (now - last_cookie_dt).total_seconds()
        if diff > (_timeout_min * 60):
            clear_auth()
            return False

    st.session_state[SS_AUTH] = {"role": role, "uid": uid}
    st.session_state[SS_LAST_ACT] = last_cookie_dt or now

    # 復元成功時に最新時刻を同期
    _touch_last_activity_cookie(now=now, min_interval_sec=0)
    return True

if st.session_state.get("just_logged_out"):
    st.session_state.pop("just_logged_out", None)
    _lo_msg = st.session_state.pop("_logout_msg", None)
    if _lo_msg:
        st.sidebar.warning(_lo_msg)
else:
    # ★ 共有URLアクセス時は、通常ログインcookieの復元/更新をスキップ（干渉防止）
    try:
        _has_share_param = bool((st.query_params.get("share") or "").strip())
    except Exception:
        _has_share_param = False

    if SS_AUTH not in st.session_state:
        if not _has_share_param:
            restored = restore_auth_from_cookie()
            # 管理ページで「ユーザー」が復元されたら強制クリア（権限の混線防止）
            if restored and _is_admin_page and st.session_state.get(SS_AUTH, {}).get("role") != ROLE_ADMIN:
                clear_auth()
    else:
        if not _has_share_param:
            check_timeout_and_logout()
            # ★ admin page では 60秒に1回だけ guard をリセット（頻繁な rerun で教師生成状態が消えるのを防ぐ）
            if _is_admin_page:
                _admin_guard_reset_ts = float(st.session_state.get("_admin_guard_reset_ts", 0))
                if (_now_utc().timestamp() - _admin_guard_reset_ts) >= 60:
                    _reset_auto_train_guards()
                    st.session_state["_admin_guard_reset_ts"] = _now_utc().timestamp()
            else:
                _reset_auto_train_guards()   # ★ rerun ごとに多重実行ガードをリセット

def is_authed() -> bool:
    return SS_AUTH in st.session_state and st.session_state[SS_AUTH].get("role") in (ROLE_USER, ROLE_ADMIN)

def authed_role() -> Optional[str]:
    return st.session_state[SS_AUTH]["role"] if is_authed() else None

def authed_uid() -> Optional[str]:
    return st.session_state[SS_AUTH]["uid"] if is_authed() else None

def _heuristic_rank_label(prompt: str) -> str:
    text = prompt or ""
    # 特徴量（簡易）
    exclaim = text.count("！") + text.count("!")
    blame_words = len(re.findall(r"(あいつ|社会が|会社が|上司が|客が|悪い|クソ|無能)", text))
    numbers = len(re.findall(r"\d+", text))
    conditionals = len(re.findall(r"(もし|なら|場合|条件|前提)", text))
    abstract = len(re.findall(r"(構造|資本|市場|制度|最適|期待値|確率)", text))

    score = 0
    score += exclaim * 2 + blame_words * 3
    score -= numbers * 1 + conditionals * 2 + abstract * 2

    # しきい値（保守的）
    if score >= 4:
        return "beginner"
    if score <= -2:
        return "expert"
    return "mixed"

def _llm_rank_label_if_needed(prompt: str, base_label: str) -> str:
    if base_label != "mixed" or not client:
        return base_label
    judge_sys = "あなたは短い診断器。beginner / expert / mixed のいずれか1語のみ出力。"
    judge_prompt = f"問い:\n{prompt}\n\nラベル1語のみ:"
    try:
        # ── 教師採用の最終判定 → Pro（ここの判定精度がLGBM学習品質を直接決める）
        lab = call_llm_pro(judge_prompt, history=[], sys=judge_sys).strip().lower()
        if lab in ("beginner", "expert", "mixed"):
            return lab
    except:
        pass
    return base_label

def _ratio_from_label(label: str):
    if label == "beginner":
        return {"architect": 0.1, "executor": 0.2, "mentor": 0.7}
    if label == "expert":
        return {"architect": 0.7, "executor": 0.3, "mentor": 0.0}
    return {"architect": 0.34, "executor": 0.33, "mentor": 0.33}

