def fs_guard():
    # db は初期化時に firestore.Client() が失敗すると st.stop() 済みのため
    # 実行がここに到達した時点で db は必ず有効なクライアントである。
    # ただし将来の変更への防御として型チェックを残す。
    if not isinstance(db, firestore.Client):
        st.error("【致命的なシステムエラー】Firestore クライアントが無効です。システムを停止します。")
        st.stop()

def _fs_stream_list(q, limit: int = 0):
    fs_guard()
    qq = q
    try:
        if limit and hasattr(qq, "limit"):
            qq = qq.limit(int(limit))
    except Exception:
        pass
    # 修正: _UnaryStreamMultiCallable の物理エラー（環境依存）を回避するため、Retry を完全に排除
    return list(qq.stream())

