# Tenants (Moved up for UI dependency)
# -----------------------------
def tenants_col():
    fs_guard()
    return db.collection("tenants")

def ensure_default_tenant():
    fs_guard()
    doc = tenants_col().document(DEFAULT_TENANT).get()
    if not doc.exists:
        tenants_col().document(DEFAULT_TENANT).set(
            {
                "tenant_id": DEFAULT_TENANT,
                "name": "Default",
                "enabled": True,
                "created_at": firestore.SERVER_TIMESTAMP,
                "updated_at": firestore.SERVER_TIMESTAMP,
            },
            merge=True,
        )

def list_tenants(include_disabled: bool = True) -> List[dict]:
    fs_guard()
    ensure_default_tenant()
    docs = _fs_stream_list(tenants_col())
    out = []
    for d in docs:
        x = d.to_dict() or {}
        if not include_disabled and not bool(x.get("enabled", True)):
            continue
        out.append(
            {
                "tenant_id": x.get("tenant_id", d.id),
                "name": x.get("name", d.id),
                "enabled": bool(x.get("enabled", True)),
            }
        )
    out.sort(key=lambda z: (z["tenant_id"] != DEFAULT_TENANT, z["tenant_id"]))
    return out

def upsert_tenant(tenant_id: str, name: str, enabled: bool = True):
    fs_guard()
    doc_ref = tenants_col().document(tenant_id)
    data = {
        "tenant_id": tenant_id,
        "name": name,
        "enabled": bool(enabled),
        "updated_at": firestore.SERVER_TIMESTAMP,
    }
    # 新規作成時のみ created_at を付与（更新時は上書きしない）
    if not doc_ref.get().exists:
        data["created_at"] = firestore.SERVER_TIMESTAMP
    doc_ref.set(data, merge=True)

def delete_tenant(tenant_id: str) -> Tuple[bool, str]:
    fs_guard()
    if tenant_id == DEFAULT_TENANT:
        return False, "default は削除できません。"
    u = _fs_stream_list(db.collection("users").where("tenant_id", "==", tenant_id), limit=1)
    if u:
        return False, "この業種に紐づくユーザーが残っています（先にユーザーを削除/移管）。"
    # 【修正】新方式のリンクテーブル(tenant_source_links)を確認
    k = _fs_stream_list(db.collection("tenant_source_links").where("tenant_id", "==", tenant_id), limit=1)
    if k:
        return False, "この業種に紐づくナレッジ紐づけ（リンク）が残っています（先にリンクを解除/削除してください）。"
    tenants_col().document(tenant_id).delete()
    return True, "削除しました。"

# -----------------------------
# Share Logic
# -----------------------------
def shares_col():
    fs_guard()
    return db.collection("share_links")

def _hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

def create_share_token(target_uid: str, target_tenant: str, expires_minutes: int = 60 * 24 * 7) -> str:
    fs_guard()
    raw = secrets.token_urlsafe(32)
    token_hash = _hash_token(raw)

    minutes = int(expires_minutes)
    data = {
        "token_hash": token_hash,
        "tenant_id": target_tenant or DEFAULT_TENANT,
        "uid": target_uid,
        "created_at": firestore.SERVER_TIMESTAMP,
        "revoked": False,
    }

    if minutes > 0:
        exp = _now_utc() + datetime.timedelta(minutes=minutes)
        data["expires_at"] = _iso(exp)

    shares_col().document(token_hash).set(data, merge=True)
    return raw

def validate_share_token(raw_token: str) -> Optional[dict]:
    if not raw_token:
        return None
    fs_guard()
    token_hash = _hash_token(raw_token)
    doc = shares_col().document(token_hash).get()
    if not doc.exists:
        return None
    d = doc.to_dict() or {}
    if bool(d.get("revoked", False)):
        return None

    expires_at = d.get("expires_at")
    if expires_at:
        try:
            # expires_at は _iso() で文字列保存 が原則。
            # Firestore SDK が DatetimeWithNanoseconds を返す場合も統一処理。
            if isinstance(expires_at, datetime.datetime):
                # tz-aware → naive UTC に正規化
                exp_dt = expires_at.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            else:
                # 文字列（通常ケース）
                exp_dt = _parse_iso(str(expires_at))

            if _now_utc() > exp_dt:
                return None
        except Exception:
            return None

    return d

def list_share_links(limit: int = 50) -> pd.DataFrame:
    fs_guard()
    try:
        q = shares_col().order_by("created_at", direction=firestore.Query.DESCENDING)
        docs = _fs_stream_list(q, limit=limit)
    except Exception:
        docs = _fs_stream_list(shares_col(), limit=limit)

    rows = []
    for d in docs:
        x = d.to_dict() or {}
        # expires_at を人間可読な文字列に正規化
        raw_exp = x.get("expires_at")
        try:
            if raw_exp:
                exp_str = raw_exp if isinstance(raw_exp, str) else str(raw_exp)[:19]
            else:
                exp_str = "無期限"
        except Exception:
            exp_str = str(raw_exp)
        rows.append({
            "doc_id": d.id,
            "uid": x.get("uid"),
            "tenant_id": x.get("tenant_id"),
            "expires_at": exp_str,
            "revoked": bool(x.get("revoked", False)),
            "share_url": x.get("share_url", ""),
        })
    return pd.DataFrame(rows)

def delete_share_link(doc_id: str):
    fs_guard()
    shares_col().document(doc_id).delete()


# -----------------------------
# Password hashing (PBKDF2)
# -----------------------------
def _b64e(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

def _b64d(s: str) -> bytes:
    pad = "=" * ((4 - len(s) % 4) % 4)
    return base64.urlsafe_b64decode((s + pad).encode("utf-8"))

def make_pw_hash(password: str, salt: Optional[bytes] = None, iters: int = 150_000) -> Tuple[str, str, int]:
    if salt is None:
        salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iters, dklen=32)
    return _b64e(salt), _b64e(dk), iters

def verify_pw(password: str, salt_b64: str, hash_b64: str, iters: int) -> bool:
    salt = _b64d(salt_b64)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iters, dklen=32)
    return _b64e(dk) == hash_b64


