def users_col():
    fs_guard()
    return db.collection("users")

def get_user_doc(uid: str):
    fs_guard()
    return users_col().document(uid).get()

def upsert_user(uid: str, password: str, tenant_id: str, is_active: bool = True):
    fs_guard()
    salt_b64, hash_b64, iters = make_pw_hash(password)
    # 新規作成時のみ初期有効期限7日間を設定（既存ユーザー更新時は上書きしない）
    _existing = users_col().document(uid).get()
    _is_new = not _existing.exists
    _init_expires = ""
    if _is_new:
        import datetime as _dt_upsert
        _init_expires = str(_dt_upsert.date.today() + _dt_upsert.timedelta(days=7))
    _upsert_data = {
        "uid": uid,
        "tenant_id": tenant_id or DEFAULT_TENANT,
        "pw_salt": salt_b64,
        "pw_hash": hash_b64,
        "pw_iters": iters,
        "plain_password": password,
        "is_active": bool(is_active),
        "created_at": firestore.SERVER_TIMESTAMP,
        "last_login": None,
        "updated_at": firestore.SERVER_TIMESTAMP,
    }
    if _is_new:
        _upsert_data["expires_at"] = _init_expires
        _upsert_data["is_unlimited"] = False
    users_col().document(uid).set(_upsert_data, merge=True)

def set_user_active(uid: str, active: bool):
    fs_guard()
    users_col().document(uid).set({"is_active": bool(active), "updated_at": firestore.SERVER_TIMESTAMP}, merge=True)

def reset_user_password(uid: str, new_password: str):
    fs_guard()
    salt_b64, hash_b64, iters = make_pw_hash(new_password)
    users_col().document(uid).set(
        {"pw_salt": salt_b64, "pw_hash": hash_b64, "pw_iters": iters, "plain_password": new_password, "updated_at": firestore.SERVER_TIMESTAMP},
        merge=True,
    )

def set_user_tenant(uid: str, tenant_id: str):
    fs_guard()
    users_col().document(uid).set({"tenant_id": tenant_id or DEFAULT_TENANT, "updated_at": firestore.SERVER_TIMESTAMP}, merge=True)

def set_user_plan(uid: str, plan: str):
    fs_guard()
    valid_plans = ["starter", "standard", "pro", "apex", "ultra_member", "ultra_admin"]
    if plan not in valid_plans:
        plan = "starter"
