# ============================================================
# Feature Flag 共通関数
# 判定優先順位: user override → registry default
# (tenant default は将来拡張用に tenant_id を引数に保持)
# ============================================================
def load_user_feature_overrides(uid: str) -> dict:
    """
    users/{uid}.feature_overrides を返す。
    session_state で軽くキャッシュ（rerun後は自動的に再評価される）。
    取得失敗時は {} を返す（安全側）。
    """
    if not uid:
        return {}
    _cache_key = f"_feat_overrides_{uid}"
    if _cache_key in st.session_state:
        return st.session_state[_cache_key]
    try:
        snap = users_col().document(uid).get()
        d = (snap.to_dict() or {}) if snap.exists else {}
        overrides = d.get("feature_overrides") or {}
        st.session_state[_cache_key] = overrides
        return overrides
    except Exception:
        return {}


def get_effective_feature_flags(uid: str, tenant_id: str = None) -> dict:
    """
    全 feature_id について有効/無効を解決して返す dict。
    優先順位: user個別override → plan baseline → registry default。
    """
    _PLAN_FEATURE_MAP = {
        "starter":  {fid: False for fid in FEATURE_REGISTRY},
        "standard": {
            "image_generation": True, "personal_consulting": False,
            "current_issue_diagnosis": True, "decision_metrics": True,
            "fixed_concept_report": False, "ascend_ultra": False, "ascend_apex": False,
            "image_gallery": False, "diag_structure": True, "diag_issue": True,
            "diag_comparison": True, "diag_contradiction": True, "diag_execution": True,
            "diag_investment": False, "diag_graph": False, "diag_file": False, "diag_future": False, "diag_profile": False, "diag_crm": False, "agent_mode": False,
        },
        "pro": {
            "image_generation": True, "personal_consulting": True,
            "current_issue_diagnosis": True, "decision_metrics": True,
            "fixed_concept_report": True, "ascend_ultra": True, "ascend_apex": False,
            "image_gallery": True, "diag_structure": True, "diag_issue": True,
            "diag_comparison": True, "diag_contradiction": True, "diag_execution": True,
            "diag_investment": False, "diag_graph": True, "diag_file": True, "diag_future": False, "diag_profile": False, "diag_crm": False, "agent_mode": False,
        },
        "apex": {fid: True for fid in FEATURE_REGISTRY},
    }
    try:
        snap = users_col().document(uid).get()
        d = (snap.to_dict() or {}) if snap.exists else {}
        plan = d.get("plan") or "starter"
        if plan not in _PLAN_FEATURE_MAP:
            plan = "starter"
    except Exception:
        plan = "starter"
    plan_flags = _PLAN_FEATURE_MAP.get(plan, {})
    overrides = load_user_feature_overrides(uid)
    result = {}
    for fid, reg in FEATURE_REGISTRY.items():
        if fid in overrides:
            result[fid] = bool(overrides[fid])
        elif fid in plan_flags:
            result[fid] = bool(plan_flags[fid])
        else:
            result[fid] = bool(reg.get("default_enabled", True))
    return result


def is_feature_enabled(uid: str, tenant_id: str, feature_id: str) -> bool:
    """
    指定 feature_id が uid に対して有効かを返す。
    - uid が None/空 → False（安全側）
    - ROLE_ADMIN セッション → 常に True
    - feature_id が FEATURE_REGISTRY 未定義 → True（後方互換: 新機能はデフォルト許可）
    """
    if not feature_id:
        return True
    try:
        if authed_role() == ROLE_ADMIN:
            return True
    except Exception:
        pass
    if not uid:
        return False
    if feature_id not in FEATURE_REGISTRY:
        return True
    flags = get_effective_feature_flags(uid, tenant_id)
    return bool(flags.get(feature_id, True))


def set_user_feature_overrides(uid: str, overrides: dict) -> None:
    """
    users/{uid} へ feature_overrides を merge=True で書き込む。
    既存フィールド (latest_fc_report, use_count_since_report 等) を壊さない。
    書き込み後にキャッシュを無効化して次回 is_feature_enabled で再取得させる。
    """
    fs_guard()
    users_col().document(uid).set(
        {
            "feature_overrides": overrides,
            "feature_updated_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )
    st.session_state.pop(f"_feat_overrides_{uid}", None)

def load_users_df(limit: int = 500) -> pd.DataFrame:
    import datetime as _dt
    _jst = _dt.timezone(_dt.timedelta(hours=9))

    def _to_jst_str(val):
        if val is None:
            return None
        try:
            if hasattr(val, "tzinfo"):
                dt = val if val.tzinfo else val.replace(tzinfo=_dt.timezone.utc)
            else:
                dt = pd.Timestamp(val)
                dt = dt.to_pydatetime()
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=_dt.timezone.utc)
            return dt.astimezone(_jst).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return str(val)

    fs_guard()
    ensure_default_tenant()
    docs = _fs_stream_list(users_col(), limit=limit)
    if not docs:
        return pd.DataFrame(columns=["uid", "tenant_id", "is_active", "created_at", "last_login", "updated_at"])
    rows = []
    for d in docs:
        x = d.to_dict() or {}
        rows.append(
            {
                "uid": x.get("uid", d.id),
                "tenant_id": x.get("tenant_id") or DEFAULT_TENANT,
                "is_active": bool(x.get("is_active", True)),
                "created_at": _to_jst_str(x.get("created_at")),
                "last_login": _to_jst_str(x.get("last_login")),
                "updated_at": _to_jst_str(x.get("updated_at")),
                "plain_password": x.get("plain_password", ""),
            }
        )
    df = pd.DataFrame(rows)
    return df.sort_values(["is_active", "tenant_id", "uid"], ascending=[False, True, True]).reset_index(drop=True)

def get_user_tenant(uid: str) -> str:
    doc = get_user_doc(uid)
    if not doc.exists:
        return DEFAULT_TENANT
    d = doc.to_dict() or {}
    return d.get("tenant_id") or DEFAULT_TENANT

