def _ascend_header_cfg_doc_id(tenant_id: str) -> str:
    tid = (tenant_id or DEFAULT_TENANT).strip()
    return f"ascend_header_config_{tid}"

def load_ascend_header_config(tenant_id: str = None) -> dict:
    """
    tenant_id に対応する ASCEND ヘッダー設定を返す。
    未設定の場合は DEFAULT_TENANT → ハードコードデフォルトの順でフォールバック。
    ※ 管理画面の変更を全ユーザーに即時反映させるため、セッションキャッシュは使わない。
    """
    tid = (tenant_id or DEFAULT_TENANT).strip()

    def _fetch(t_id: str):
        try:
            _doc = db.collection("system_settings").document(_ascend_header_cfg_doc_id(t_id)).get()
            if _doc.exists:
                return {**_ASCEND_HEADER_DEFAULT, **(_doc.to_dict() or {})}
        except Exception:
            pass
        return None

    cfg = _fetch(tid)
    if cfg is None and tid != DEFAULT_TENANT:
        cfg = _fetch(DEFAULT_TENANT)
    if cfg is None:
        cfg = dict(_ASCEND_HEADER_DEFAULT)
    return cfg

def _ascend_header_md(cfg: dict) -> str:
    return (
        f"### {cfg['title']}\n"
        f"{cfg['subtitle']}\n\n"
        f"**・{cfg['point_1_label']}** {cfg['point_1_body']}\n\n"
        f"**・{cfg['point_2_label']}** {cfg['point_2_body']}\n\n"
        f"**・{cfg['point_3_label']}** {cfg['point_3_body']}\n"
        "---"
    )

def _score_cfg_doc_id(tenant_id: str) -> str:
    tid = (tenant_id or DEFAULT_TENANT).strip()
    return f"score_config_{tid}"

def load_score_config(tenant_id: str = None) -> dict:
    """
    tenant_id に対応する採点設定を返す。
    未設定 → DEFAULT_TENANT → ハードコードデフォルトの順でフォールバック。
    ※ 管理画面の数値変更を全ユーザーに即時反映させるため、セッションキャッシュは使わない。
    """
    tid = (tenant_id or DEFAULT_TENANT).strip()

    def _fetch(t_id: str) -> dict:
        try:
            _doc = db.collection("system_settings").document(_score_cfg_doc_id(t_id)).get()
            if _doc.exists:
                _data = _doc.to_dict() or {}
                # 数値フィールドを int に正規化
                for _k in ("struct_pt", "strategy_pt", "exec_pt", "emotion_pt"):
                    if _k in _data:
                        try:
                            _data[_k] = int(_data[_k])
                        except (ValueError, TypeError):
                            _data[_k] = _SCORE_CFG_DEFAULT[_k]
                return {**_SCORE_CFG_DEFAULT, **_data}
        except Exception:
            pass
        return None

    cfg = _fetch(tid)
    if cfg is None and tid != DEFAULT_TENANT:
        cfg = _fetch(DEFAULT_TENANT)
    if cfg is None:
        cfg = dict(_SCORE_CFG_DEFAULT)
    return cfg

def _words_from_cfg(cfg: dict, key: str) -> list:
    """設定のカンマ区切り文字列をリストに変換（空要素除去）"""
    return [w.strip() for w in str(cfg.get(key, "")).split(",") if w.strip()]

def calculate_level_score(text: str, tenant_id: str = None) -> int:
    """
    テキストから加減点を計算。
    tenant_id が渡された場合は業種別設定を使用、なければデフォルト。
    """
    t = text or ""
    cfg = load_score_config(tenant_id)

    score = 0
    for w in _words_from_cfg(cfg, "struct_words"):
        if w in t: score += int(cfg["struct_pt"])
    for w in _words_from_cfg(cfg, "strategy_words"):
        if w in t: score += int(cfg["strategy_pt"])
    for w in _words_from_cfg(cfg, "exec_words"):
        if w in t: score += int(cfg["exec_pt"])
    for w in _words_from_cfg(cfg, "emotion_words"):
        if w in t: score += int(cfg["emotion_pt"])   # emotion_pt は負数を想定

    return score


def get_user_level_data(uid: str):
    snap = users_col().document(uid).get()
    if snap.exists:
        d = snap.to_dict()
        return d.get("level_score", 0)
    return 0

