def apply_query_plan_boost(chunks: List[dict], query_plan: dict, rag_cfg: dict) -> List[dict]:
    """チャンクのリストに対して Query Plan に基づくブースト（カテゴリ・鮮度）を1箇所で適用する"""
    if not chunks or not query_plan:
        return chunks

    plan_cats = query_plan.get("retrieval", {}).get("categories", {}) or {}
    recency = query_plan.get("retrieval", {}).get("recency_bias", "low") or "low"
    if not plan_cats and recency not in ("high", "med"):
        return chunks

    import datetime
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    # 0割 / None / 非数 を踏んでも落ちない
    try:
        w_days = int(rag_cfg.get("recency_window_days", 60) or 60)
    except Exception:
        w_days = 60
    w_days = max(1, w_days)

    def _f(x, default: float) -> float:
        try:
            return float(x if x is not None else default)
        except Exception:
            return float(default)

    cat_b_max = _f(rag_cfg.get("plan_category_boost_max", 0.12), 0.12)
    high_max  = _f(rag_cfg.get("recency_boost_high_max", 0.08), 0.08)
    med_max   = _f(rag_cfg.get("recency_boost_med_max", 0.03), 0.03)

    max_w = 1.0
    if plan_cats:
        cat_weights = [v for v in plan_cats.values() if isinstance(v, (int, float))]
        if cat_weights:
            max_w = float(max(cat_weights + [1]))

    for c in chunks:
        try:
            sim = float(c.get("score") or 0.0)
        except Exception:
            sim = 0.0

        cat = c.get("category", "general")

        if recency in ("high", "med"):
            try:
                dt = _as_datetime(c.get("updated_at") or c.get("created_at"))
                if dt:
                    # naive datetime をUTCとして扱い、astimezone例外を回避
                    if getattr(dt, "tzinfo", None) is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)

                    days_old = (now_dt - dt.astimezone(datetime.timezone.utc)).days
                    if days_old < 0:
                        days_old = 0
                    max_b = high_max if recency == "high" else med_max
                    ratio = (w_days - days_old) / float(w_days)
                    if ratio > 0:
                        sim += ratio * max_b
            except Exception:
                pass

        if plan_cats:
            w = plan_cats.get(cat, 0)
            if isinstance(w, (int, float)) and w > 0:
                sim += (float(w) / max_w) * cat_b_max

        c["score"] = float(sim)

    chunks.sort(key=lambda x: float(x.get("score") or -1.0), reverse=True)
    return chunks

def detect_purpose_mode_auto(text: str, enabled_modes: list = None) -> str:
    """
    ユーザー入力から目的モードを自動判別（全モード対応）。
    enabled_modes が渡された場合、その範囲内でのみ判別する。
    """
    t = (text or "").lower()
    _enabled = set(enabled_modes) if enabled_modes else set(MODE_REGISTRY.keys())

    # スコアベース判別（複数キーワードに該当するモードを優先）
    scores: dict[str, int] = {}
    for mode_key, reg in MODE_REGISTRY.items():
        if mode_key == "auto" or mode_key not in _enabled:
            continue
        score = 0
        for kw in reg.get("detect_keywords", []):
            if kw in t:
                score += 1
        # detect_pattern があるモード（numericの数字検出など）
        pat = reg.get("detect_pattern")
        if pat and re.search(pat, t):
            score += 1
        if score > 0:
            scores[mode_key] = score

    if scores:
        # 最高スコアのモードを返す（同点は辞書順で先頭）
        return max(scores, key=lambda k: scores[k])
    return "auto"

def _sanitize_doc_id(s: str) -> str:
    s = (s or "").strip()
    s = re.sub(r"[^0-9A-Za-z_\-\.]+", "_", s)
    return s[:180] if len(s) > 180 else s

def tenant_source_link_doc_id(tenant_id: str, source_id: str) -> str:
    """
    tenant_source_links の doc_id を決定的に生成する。
    - 同じ (tenant_id, source_id) は常に同じdoc_id
    - source_id に禁止文字があっても安全（hexのみ）
    """
    t = (tenant_id or DEFAULT_TENANT).strip()
    s = (source_id or "").strip()
    raw = f"{t}::{s}".encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

def summarize_text_multi(text: str, preset_key: str = "expert", max_chars: int = 900, custom_labels: Optional[Tuple[str, str, str]] = None) -> dict:
    """3要素の要約を1回のLLM呼び出しで生成して dict で返す。失敗時は空dict。"""
    if not client:
        return {}
    preset_key = (preset_key or "expert").strip()
    if custom_labels and all((x or "").strip() for x in custom_labels):
        labels = tuple((x or "").strip() for x in custom_labels)
    else:
        preset_obj = SUMMARY_PRESETS.get(preset_key) or SUMMARY_PRESETS["expert"]
        labels = preset_obj["labels"]

    sys = "あなたは要約器。余計な前置き禁止。出力はJSONのみ。"
    prompt = (
        "次の原文を、指定の3観点で要約せよ。各値は日本語で簡潔に。\n"
        f"- {labels[0]}\n- {labels[1]}\n- {labels[2]}\n\n"
        f"制約: 各要約は最大{int(max_chars)}文字。\n\n"
        "出力JSON形式: {\n"
        f"  \"a\": \"{labels[0]}の要約\",\n"
        f"  \"b\": \"{labels[1]}の要約\",\n"
        f"  \"c\": \"{labels[2]}の要約\"\n"
        "}\n\n"
        "原文:\n"
        + (text or "")[:120_000]
    )
    try:
        out = call_llm(prompt, history=[], sys=sys).strip()
    except Exception:
        return {}

    try:
        m = re.search(r"\{.*\}", out, flags=re.DOTALL)
        j = m.group(0) if m else out
        import json
        d = json.loads(j)
        return {
            "a": (d.get("a") or "").strip(),
            "b": (d.get("b") or "").strip(),
            "c": (d.get("c") or "").strip(),
        }
    except Exception:
        return {}


def generate_suggested_cases(user_prompt: str, assistant_answer: str, tenant_id: str, max_items: int = 5) -> List[str]:
    """回答から連想される『次に想定される事案』を生成し、ボタン候補として返す。"""
    if not client:
        return []
    max_items = int(max_items or 0) or 5
    max_items = max(1, min(8, max_items))
    sys = "あなたはコンサル補助の提案器。余計な前置き禁止。出力は日本語の短文のみ。"
    prompt = (
        "以下の相談と回答から、次に続きそうな『事案（次の質問）』を提案せよ。\n"
        "- 目的: ユーザーが次にクリックして送信できる具体的な問い\n"
        "- 制約: 1行=1事案、各行は60文字以内、最大{n}件、番号や記号は付けない\n"
        "- 事案は『回答内容』と強く整合し、論点をずらさない\n\n"
        f"【業種】{tenant_id}\n"
        f"【相談】{user_prompt}\n"
        f"【回答】{assistant_answer[:1200]}\n\n"
        "出力:"
    ).format(n=max_items)
    try:
        out = call_llm(prompt, history=[], sys=sys) or ""
    except Exception:
        return []
    lines = []
    for raw in (out or "").splitlines():
        s = (raw or "").strip()
        s = re.sub(r"^[\-\*\d\.\)\(\s]+", "", s)  # 箇条書き/番号の除去
        if not s:
            continue
        if len(s) > 80:
            s = s[:80].rstrip()
        lines.append(s)
        if len(lines) >= max_items:
            break
    # 重複除去（順序保持）
    uniq = []
    seen = set()
    for x in lines:
        k = x.strip()
        if k and k not in seen:
            uniq.append(k)
            seen.add(k)
    return uniq


# -----------------------------
# Chat Summary（会話サマリー自動保存 & 文脈継続）
# -----------------------------

def _summary_col():
    fs_guard()
    return db.collection("chat_summaries")

def save_chat_summary(uid: str, tenant_id: str, user_prompt: str, assistant_answer: str) -> Optional[str]:
    """
    1ターン分の会話を3行サマリーに圧縮してFirestoreに保存し、
    ベクトル化してRAGの検索対象（長期記憶）として登録する。
    """
    if not client:
        return None
    try:
        sys_s = "あなたは優秀な議事録AI。余計な前置き・後書き禁止。出力は日本語の箇条書き3行のみ。"
        prompt_s = (
            "以下の1ターン会話を、後日AIが文脈として参照できる形で3行に要約せよ。\n"
            "- 行1：ユーザーが抱えていた課題・状況（具体的に）\n"
            "- 行2：AIが示した結論・提言（断定形で）\n"
            "- 行3：この会話で生まれた合意・次のアクション\n\n"
            f"【業種】{tenant_id}\n"
            f"【ユーザー】{user_prompt[:400]}\n"
            f"【AI回答】{assistant_answer[:600]}\n\n"
            "出力（3行のみ）:"
        )
        summary_text = call_llm(prompt_s, history=[], sys=sys_s).strip()
        if not summary_text or len(summary_text) < 10:
            return None

        # 1. 履歴管理用コレクションへの保存
        #    ★ 修正: raw_conversation フィールドに生の会話を明示保存（要約元として再要約時に使用）
        doc_ref = _summary_col().document()
        doc_id = doc_ref.id
        doc_ref.set({
            "uid": uid,
            "tenant_id": tenant_id,
            "summary": summary_text,
            "source_prompt": user_prompt[:200],       # 生の質問（後方互換維持）
            "raw_user_prompt": user_prompt[:800],     # ★ 再要約用：生の質問（フル）
            "raw_assistant_answer": assistant_answer[:800],  # ★ 再要約用：生のAI回答
            "created_at": firestore.SERVER_TIMESTAMP,
        })
        
        # 2. RAGの検索母集団（長期記憶）への登録
        sid = f"chat_sum_{uid}_{doc_id}"
        # ★ 修正: タイトルを要約テキストの先頭行から生成する（生の質問を露出しない）
        _sum_first_line = (summary_text.split("\n")[0].strip())[:40] if summary_text else ""
        title = f"会話要約: {_sum_first_line}" if _sum_first_line else f"会話要約: {_now_utc().strftime('%Y%m%d_%H%M')}"
        category = "chat_summary"
        
        # 【修正】中央ソース（倉庫）へ保存。sid, title, summary_text を正しく使用。
        sources_col().document(sid).set({
            "source_id": sid,
            "title": title,
            "content": summary_text,
            "category": category,
            "source_type": "chat_summary",
            "created_at": firestore.SERVER_TIMESTAMP,
            "updated_at": firestore.SERVER_TIMESTAMP
        }, merge=True)
        
        # 業種リンク（インデックス）へ紐付け
        link_id = tenant_source_link_doc_id(tenant_id, sid)
        tenant_source_links_col().document(link_id).set({
            "tenant_id":     tenant_id,
            "uid":           uid,
            "source_id":     sid,
            "category":      category,
            "enabled":       True,
            "priority":      0,
            "visibility":    "private",
            # ★ モード制御フィールド（空=全モードで有効）
            "allowed_modes": [],      # 空=制限なし。["legal","finance"] なら指定モードのみ
            "blocked_modes": [],      # 指定モードでは検索除外
            "force_include": False,   # True=該当モードでは必ず上位に注入
            "risk_tags":     [],      # ["confidential","high_stakes"] など
            "updated_at":    firestore.SERVER_TIMESTAMP,
        }, merge=True)
        
        # 3. ベクトル化（長期記憶化）
        rag_cfg = load_rag_settings(tenant_id)
        upsert_doc_chunks(
            tenant_id=tenant_id,
            doc_id=sid,
            title=title,
            category=category,
            source_type="chat_summary",
            content_text=summary_text,
            chunk_chars=int(rag_cfg.get("chunk_chars", 1200)),
            overlap=0
        )
        return doc_id
    except Exception:
        return None

def load_recent_summaries(uid: str, tenant_id: str, limit: int = 5) -> List[str]:
    """
    直近N件のサマリーを新しい順で返す。
    呼び出し側でプロンプトに注入するためのリスト。
    """
    fs_guard()
    try:
        docs = list(
            _summary_col()
            .where("uid", "==", uid)
            .where("tenant_id", "==", tenant_id)
            .order_by("created_at", direction=firestore.Query.DESCENDING)
            .limit(limit)
            .stream()
        )
        result = []
        for d in reversed(docs):  # 古い→新しい順に並べ直す
            s = (d.to_dict() or {}).get("summary", "").strip()
            if s:
                result.append(s)
        return result
    except Exception:
        return []

def upsert_precompiled_summaries(
    tenant_id: str,
    doc_id: str,
    title: str,
    category: str,
    source_ref: str,
    text: str,
) -> int:
    """RAG設定に従い、3要素要約を summary chunks として保存する。"""
    rag = load_rag_settings(tenant_id)
    if not rag.get("summary_enabled", True):
        return 0
    preset = str(rag.get("summary_preset", "expert") or "expert").strip()
    max_chars = int(rag.get("summary_chars", 900))
    use_custom = bool(rag.get("summary_custom_enabled", False))
    custom_labels = (
        str(rag.get("summary_custom_a", "") or "").strip(),
        str(rag.get("summary_custom_b", "") or "").strip(),
        str(rag.get("summary_custom_c", "") or "").strip(),
    ) if use_custom else None

    sums = summarize_text_multi(text or "", preset_key=preset, max_chars=max_chars, custom_labels=custom_labels)
    if not sums:
        return 0

    if custom_labels and all(custom_labels):
        labels = custom_labels
    else:
        preset_obj = SUMMARY_PRESETS.get(preset) or SUMMARY_PRESETS.get("expert") or {}
        labels = preset_obj.get("labels") or ("要点1", "要点2", "要点3")

    wrote = 0
    errors = 0

    for key, label in zip(("a", "b", "c"), labels):
        s = (sums.get(key) or "").strip()
        if not s:
            continue
        sid = _sanitize_doc_id(f"{doc_id}__sum__{preset}__{key}")
        stitle = f"{title} (summary:{preset}:{label})"
        try:
            # 【重要】要約を検索母集団に認識させるため、中央ソースに登録する
            sources_col().document(sid).set(
                {
                    "source_id": sid,
                    "title": stitle,
                    "content": s,
                    "source_type": "summary",
                    "category": category,
                    "created_at": firestore.SERVER_TIMESTAMP,
                    "updated_at": firestore.SERVER_TIMESTAMP,
                },
                merge=True,
            )

            # tenant_idが指定されている場合のみリンクを作成（中央純粋保存時はスキップ）
            if tenant_id:
                link_id = tenant_source_link_doc_id(tenant_id, sid)
                tenant_source_links_col().document(link_id).set(
                    {
                        "tenant_id": tenant_id,
                        "source_id": sid,
                        "category": category,
                        "enabled": True,
                        "priority": 0,
                        "visibility": "internal",
                        "updated_at": firestore.SERVER_TIMESTAMP,
                    },
                    merge=True,
                )

            upsert_doc_chunks(
                tenant_id=tenant_id,
                doc_id=sid,
                title=stitle,
                category=category,          # ★同カテゴリにして原文と競わせる
                source_type="summary",
                source_ref=source_ref,
                content_text=s,
                chunk_chars=max_chars,
                overlap=0,
            )
            wrote += 1
        except Exception as e:
            errors += 1
            print(f"[precompile] failed sid={sid} preset={preset} key={key}: {e}")

    if errors:
        print(f"[precompile] errors={errors} / wrote={wrote}")

    return wrote

def link_precompiled_summaries_to_tenant(
    doc_id: str,
    tenant_id: str,
    category: str,
) -> int:
    """
    【完全中央化補助】既に中央倉庫に存在するサマリーソース/チャンクに対し、
    指定テナントへのリンク（tenant_source_links）だけを追加する。
    チャンクの再生成は行わない。
    upsert_precompiled_summaries を最初のテナントで1回呼んだ後、
    追加テナント分はこの関数を使う。
    """
    fs_guard()
    wrote = 0
    for preset_key in SUMMARY_PRESETS.keys():
        for key in ("a", "b", "c"):
            sid = _sanitize_doc_id(f"{doc_id}__sum__{preset_key}__{key}")
            try:
                sdoc = sources_col().document(sid).get()
                if not sdoc.exists:
                    continue
                link_id = tenant_source_link_doc_id(tenant_id, sid)
                tenant_source_links_col().document(link_id).set({
                    "tenant_id": tenant_id,
                    "source_id": sid,
                    "category": category,
                    "enabled": True,
                    "priority": 0,
                    "visibility": "internal",
                    "updated_at": firestore.SERVER_TIMESTAMP,
                }, merge=True)
                wrote += 1
            except Exception:
                pass
    return wrote

def recompile_precompiled_summaries_for_tenant(tenant_id: str, limit: int = 500) -> dict:
    """【新方式】tenantに紐づく sources を走査して、要約チャンクを再生成・再保存する。"""
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    limit = int(limit or 0) or 500

    processed = 0
    wrote_total = 0
    skipped = 0
    errors = 0

    try:
        links = list(
            tenant_source_links_col()
            .where("tenant_id", "==", tenant_id)
            .limit(limit)
            .stream()
        )

        for l in links:
            ld = l.to_dict() or {}
            source_id = ld.get("source_id") or ""
            if not source_id:
                skipped += 1
                continue

            processed += 1

            sdoc = sources_col().document(source_id).get()
            if not sdoc.exists:
                errors += 1
                continue

            d = sdoc.to_dict() or {}
            title = d.get("title") or source_id
            source_type = d.get("source_type") or "note"
            text = d.get("text") or d.get("content") or ""
            if not text.strip():
                skipped += 1
                continue

            try:
                wrote = upsert_precompiled_summaries(
                    tenant_id=tenant_id,
                    doc_id=source_id,
                    title=title,
                    category=(l.to_dict() or {}).get("category") or "general",
                    source_ref=source_id,
                    text=text,
                )
                wrote_total += int(wrote or 0)
            except Exception:
                errors += 1

    except Exception:
        errors += 1

    return {
        "tenant_id": tenant_id,
        "processed": processed,
        "wrote": wrote_total,
        "skipped": skipped,
        "errors": errors,
    }

def load_system_prompt(tenant_id: str) -> str:
    s = load_tenant_settings(tenant_id)
    return s["sys_prompt"]

def load_user_custom_settings(uid: str, tenant_settings: dict) -> dict:
    """
    tenant_settings をベースに、users ドキュメントの custom_sys_prompt で上書きする。
    フォールバック順: constant → default tenant → tenant → user（後勝ち）

    追加フィールド:
      custom_sys_prompt   : ユーザー固有の付加プロンプト（base の末尾に結合）
      custom_prompt_mode  : "append"（末尾追記）/ "replace"（完全上書き）
      has_user_custom     : カスタム設定が存在するか（UI表示用）
    """
    fs_guard()
    result = dict(tenant_settings)  # シャローコピー（modes は参照なので注意）
    result["sys_prompt_modes"] = dict(tenant_settings.get("sys_prompt_modes") or {})
    result["has_user_custom"] = False

    try:
        snap = users_col().document(uid).get()
        if not snap.exists:
            return result
        u = snap.to_dict() or {}
        custom = (u.get("custom_sys_prompt") or "").strip()
        mode = (u.get("custom_prompt_mode") or "append").strip()
        if not custom:
            return result

        result["has_user_custom"] = True

        if mode == "replace":
            # ユーザープロンプトで全モードを完全上書き
            result["sys_prompt"] = custom
            for mk in result["sys_prompt_modes"]:
                result["sys_prompt_modes"][mk] = custom
        else:
            # append（既定）：テナントプロンプトの末尾にユーザープロンプトを追記
            base = result["sys_prompt"]
            result["sys_prompt"] = base + "\n\n【このユーザーへの個別指示】\n" + custom
            for mk in list(result["sys_prompt_modes"].keys()):
                m_base = result["sys_prompt_modes"].get(mk) or base
                result["sys_prompt_modes"][mk] = m_base + "\n\n【このユーザーへの個別指示】\n" + custom
    except Exception:
        pass

    return result

def save_user_custom_prompt(uid: str, custom_sys_prompt: str, mode: str = "append"):
    """users ドキュメントにユーザー固有プロンプトを保存する。空文字で削除。"""
    fs_guard()
    users_col().document(uid).set(
        {
            "custom_sys_prompt": (custom_sys_prompt or "").strip(),
            "custom_prompt_mode": mode if mode in ("append", "replace") else "append",
            "updated_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )

# 3. 意図解析プロンプト
def update_user_intent_state(uid: str, history: list, current_p: str) -> dict:
    """ユーザーの『脳内カルテ（深層意図）』を診断・更新し、Firestoreに永続化する。"""
    if not client: return {}
    sys_diag = "あなたは深層心理と戦略に精通したプロファイラー。余計な前置き禁止。JSONのみ出力。"
    _intent_rcfg = load_rank_config(get_user_tenant(uid))
    _r1 = _intent_rcfg["rank_1_name"]
    _r2 = _intent_rcfg["rank_2_name"]
    _r3 = _intent_rcfg["rank_3_name"]
    _r4 = _intent_rcfg["rank_4_name"]
    diag_prompt = f"""
    以下の履歴と最新発言から、ユーザーの『現在の精神状態』と『真の意図』をJSONでプロファイリングせよ。
    【履歴】{str(history[-3:])}
    【最新】{current_p}
    【出力形式】
    {{
      "current_stage": "{_r1}/{_r2}/{_r3}/{_r4}",
      "true_desire": "ユーザーが本当に求めていること（15文字以内）",
      "bias": "かかっているバイアス",
      "missing_piece": "{_r4}になるために足りない観点",
      "confidence": 0.8
    }}
    """
    try:
        # ── 構造更新の最終判定 → Pro（脳内カルテの精度がRAG・Mentor比率に直結する）
        res = call_llm_pro(diag_prompt, history=[], sys=sys_diag)
        import json, re
        m = re.search(r"\{.*\}", res, re.DOTALL)
        state = json.loads(m.group(0)) if m else {}
        if state:
            # 例外ルール: confidence が Low なら Pro で再判定済みのため警告フラグだけ立てる
            if float((state.get("confidence") or 1.0)) < 0.5:
                state["_low_confidence"] = True
            users_col().document(uid).set({"intent_state": state}, merge=True)
        return state
    except:
        return {}

def get_user_intent_state(uid: str) -> dict:
    doc = get_user_doc(uid)
    if doc.exists:
        return doc.to_dict().get("intent_state", {})
    return {}

def _emb_f32_to_bytes(emb: List[float]) -> bytes:
    """float配列をfloat32バイナリへ（Firestore容量削減用）"""
    if not emb:
        return b""
    try:
        # little-endian float32
        return struct.pack("<" + "f" * len(emb), *[float(x) for x in emb])
    except Exception:
        return b""

def _emb_bytes_to_f32_list(b: bytes) -> List[float]:
    """float32バイナリをfloat配列へ（類似度計算用）"""
    if not b:
        return []
    try:
        n = len(b) // 4
        if n <= 0:
            return []
        return list(struct.unpack("<" + "f" * n, b[: n * 4]))
    except Exception:
        return []

def _get_embedding_from_doc(d: dict) -> List[float]:
    """
    旧: embedding(list[float])
    新: embedding_bytes(bytes)
    両対応で取り出す
    """
    if not d:
        return []
    eb = d.get("embedding_bytes")
    if isinstance(eb, (bytes, bytearray)):
        return _emb_bytes_to_f32_list(bytes(eb))
    # 旧形式
    e = d.get("embedding") or []
    return e if isinstance(e, list) else []

def delete_all_knowledge_sources_for_tenant(tenant_id: str, batch_size: int = 50) -> dict:
    """
    【新方式】指定tenantの「紐づけ(tenant_source_links)」を全削除する。
    - sources/source_chunks は “倉庫” なので削除しない（単独保持を守る）
    - UI上の「この業種のソースを全削除」は、このunlinkを意味する

    戻り値: deleted_links
    """
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    batch_size = int(batch_size or 0) or 50
    batch_size = max(10, min(50, batch_size))

    deleted_links = 0
    while True:
        links = list(
            tenant_source_links_col()
            .where("tenant_id", "==", tenant_id)
            .limit(batch_size)
            .stream()
        )
        if not links:
            break
        b = db.batch()
        for l in links:
            b.delete(l.reference)
        b.commit()
        deleted_links += len(links)

    return {
        "tenant_id": tenant_id,
        "deleted_links": deleted_links,
    }

def move_knowledge_source_to_tenant(
    from_tenant: str,
    doc_id: str,
    to_tenant: str,
    conflict: str = "skip",   # skip / overwrite
    reindex_chunks: bool = False,
) -> dict:
    """
    【新方式】source_id(=doc_id) の “リンク” を from_tenant → to_tenant に移動する。

    - sources/source_chunks は移動しない（単独保持）
    - conflict:
        skip      : to側に既にリンクがあれば何もしない
        overwrite : to側のリンクを作り直す（実質同じ）
    - reindex_chunks: Trueの場合、そのsourceのchunksを再生成（グローバルに上書き）
      ※基本はFalse推奨（tenant間移動に再生成は不要）

    戻り値: {ok, moved, ...}
    """
    fs_guard()
    from_tenant = from_tenant or DEFAULT_TENANT
    to_tenant = to_tenant or DEFAULT_TENANT
    source_id = (doc_id or "").strip()
    if not source_id:
        return {"ok": False, "reason": "empty_source_id"}

    if from_tenant == to_tenant:
        return {"ok": True, "moved": False, "reason": "same_tenant"}

    # from側リンクを探す
    from_links = list(
        tenant_source_links_col()
        .where("tenant_id", "==", from_tenant)
        .where("source_id", "==", source_id)
        .limit(1)
        .stream()
    )
    if not from_links:
        return {"ok": False, "reason": "link_not_found", "from_tenant": from_tenant, "source_id": source_id}

    # to側リンク存在確認
    to_links = list(
        tenant_source_links_col()
        .where("tenant_id", "==", to_tenant)
        .where("source_id", "==", source_id)
        .limit(1)
        .stream()
    )
    if to_links and (conflict or "skip") == "skip":
        # 既にto側にあるなら、from側を消すかはUI設計次第だが「移動」なので消す
        try:
            from_links[0].reference.delete()
        except Exception:
            pass
        return {"ok": True, "moved": True, "note": "already_linked_in_to_tenant; removed_from_from_tenant"}

    # to側リンク upsert
    link_id = tenant_source_link_doc_id(to_tenant, source_id)
    tenant_source_links_col().document(link_id).set(
        {
            "tenant_id": to_tenant,
            "source_id": source_id,
            "updated_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )

    # from側リンク削除
    try:
        from_links[0].reference.delete()
    except Exception:
        pass

    # 必要ならchunks再生成（グローバル）
    wrote = 0
    if reindex_chunks:
        try:
            sdoc = sources_col().document(source_id).get()
            if sdoc.exists:
                sd = sdoc.to_dict() or {}
                title = sd.get("title") or source_id
                source_type = sd.get("source_type") or "note"
                text = sd.get("text") or sd.get("content") or ""
                rag_cfg = load_rag_settings(to_tenant)
                cc = int(rag_cfg.get("chunk_chars", 1200))
                ov = int(rag_cfg.get("chunk_overlap", 200))
                wrote = upsert_doc_chunks(
                    tenant_id=to_tenant,
                    doc_id=source_id,
                    title=title,
                    category=sd.get("category") or "general",
                    source_type=source_type,
                    content_text=text,
                    chunk_chars=cc,
                    overlap=ov,
                )
        except Exception:
            wrote = 0

    return {"ok": True, "moved": True, "from_tenant": from_tenant, "to_tenant": to_tenant, "source_id": source_id, "chunks_rebuilt": int(wrote or 0)}

def delete_chunks_for_doc(tenant_id: str, doc_id: str, batch_size: int = 50) -> int:
    """
    【新方式】指定 source_id(=doc_id) の source_chunks を全削除（小分け）。
    ※ tenant_id は後方互換のため残すが、削除条件には使わない（グローバル削除）。
    """
    fs_guard()
    _ = tenant_id  # backward compat (unused)
    source_id = (doc_id or "").strip()
    if not source_id:
        return 0

    batch_size = int(batch_size or 0) or 50
    batch_size = max(10, min(50, batch_size))

    deleted = 0
    while True:
        snaps = list(
            source_chunks_col()
            .where("source_id", "==", source_id)
            .limit(batch_size)
            .stream()
        )
        if not snaps:
            break
        b = db.batch()
        for s in snaps:
            b.delete(s.reference)
        b.commit()
        deleted += len(snaps)
    return deleted

