# =====================================================================
# ④ 性能指標コレクション（model_performance_metrics）
# モデルversion別: NDCG推移 / rerank採用率 / 順位変動相関 / ユーザー評価改善率
# =====================================================================
def _perf_col():
    fs_guard()
    return db.collection("model_performance_metrics")

def load_performance_metrics_history(scope: str = None, limit: int = 30) -> list:
    """model_performance_metrics を新しい順で取得。ダッシュボード用。
    ★ where+order_by の複合インデックス不要化: Python側でフィルタ。
    """
    fs_guard()
    try:
        q = _perf_col().order_by("trained_at", direction=firestore.Query.DESCENDING)
        fetch_limit = limit * 10 if scope else limit
        docs = [
            {"doc_id": d.id, **(d.to_dict() or {})}
            for d in _fs_stream_list(q, limit=fetch_limit)
        ]
        if scope:
            docs = [d for d in docs if d.get("scope") == scope]
        return docs[:limit]
    except Exception:
        return []

def _compute_rerank_adoption_rate(tenant_id: str, window: int = 200) -> float:
    """rerank後チャンク採用率: 直近windowクエリの採用有無比率。"""
    try:
        total_q = (
            _lgbm_training_logs_col()
            .where("tenant_id", "==", tenant_id)
            .where("record_type", "==", "rerank_result")
            .order_by("ts", direction=firestore.Query.DESCENDING)
        )
        total_docs = _fs_stream_list(total_q, limit=window)
        if not total_docs:
            return 0.0

        query_ids = [
            qid for qid in {
                (d.to_dict() or {}).get("query_id", "")
                for d in total_docs if d
            }
            if qid
        ]
        if not query_ids:
            return 0.0

        adopted_q = (
            _lgbm_training_logs_col()
            .where("tenant_id", "==", tenant_id)
            .where("record_type", "==", "user_adoption")
        )
        adopted_docs = _fs_stream_list(adopted_q, limit=5000)
        adopted_qids = {
            (d.to_dict() or {}).get("query_id", "")
            for d in adopted_docs if d
        }
        return round(
            sum(1 for qid in query_ids if qid in adopted_qids) / len(query_ids),
            4,
        )
    except Exception:
        return 0.0

def _compute_rank_shift_correlation(tenant_id: str, window: int = 200) -> float:
    """
    rerank前後の順位変動相関を計算。
    rerank_result の rank_before / rank_after の Spearman 相関を返す。
    1.0=完全一致 / 負=逆転 / 0=無相関。
    """
    try:
        import numpy as np

        q = (
            _lgbm_training_logs_col()
            .where("tenant_id", "==", tenant_id)
            .where("record_type", "==", "rerank_result")
            .order_by("ts", direction=firestore.Query.DESCENDING)
        )
        docs = _fs_stream_list(q, limit=window)

        rb, ra = [], []
        for d in docs:
            dd = d.to_dict() or {}
            _rb = dd.get("rank_before")
            _ra = dd.get("rank_after")
            if _rb is not None and _ra is not None:
                rb.append(float(_rb))
                ra.append(float(_ra))

        if len(rb) < 5:
            return 0.0

        rb_arr = pd.Series(rb, dtype="float64").rank(method="average").to_numpy()
        ra_arr = pd.Series(ra, dtype="float64").rank(method="average").to_numpy()
        corr = float(np.corrcoef(rb_arr, ra_arr)[0, 1])
        return round(corr if not (corr != corr) else 0.0, 4)
    except Exception:
        return 0.0

def _compute_user_eval_improvement(tenant_id: str, window: int = 200) -> float:
    """
    最終ユーザー評価の改善率。
    実データ源は lgbm_training_logs の record_type="user_eval"。
    簡易版として、直近 window 件のポジティブ評価率を返す。
    """
    try:
        q = (
            _lgbm_training_logs_col()
            .where("tenant_id", "==", tenant_id)
            .where("record_type", "==", "user_eval")
            .order_by("ts", direction=firestore.Query.DESCENDING)
        )
        docs = _fs_stream_list(q, limit=window)

        _pos_keywords = {"good", "a", "s", "excellent", "positive"}
        total, pos = 0, 0
        for d in docs:
            dd = d.to_dict() or {}
            ev = str(dd.get("final_user_eval", "") or "").strip().lower()
            if not ev:
                continue
            total += 1
            try:
                ev_num = float(ev)
            except Exception:
                ev_num = None
            if ev in _pos_keywords or (ev_num is not None and ev_num >= 4.0):
                pos += 1

        return round(pos / total, 4) if total > 0 else 0.0
    except Exception:
        return 0.0

# =====================================================================
# ⑤ 週次・NDCG低下トリガー（閉ループ完成）
# =====================================================================
def check_and_enqueue_scheduled_training(tenant_id: str) -> dict:
    """
    ③ 再学習トリガーを3条件すべてチェックしてジョブをキューに積む。
    呼び出し元: 管理画面の定期チェックボタン、または Streamlit rerun 時フック。

    トリガー条件:
      A. 新規教師データ100件到達（record_user_adoptions 側でも積むが二重防止で確認）
      B. 週次定期実行（前回学習から7日以上）
      C. NDCG閾値割れ（現行モデルNDCG が _LGBM_NDCG_DROP_THRESHOLD 以上低下）
    返り値: {"triggered": bool, "reason": str, "job_id": str}
    """
    fs_guard()
    result = {"triggered": False, "reason": "", "job_id": ""}
    try:
        # ★ 全運用定数をFirestoreから取得
        _ops_se = load_lgbm_ops_config()

        _last_eq = _get_last_job_enqueued_at(tenant_id)
        _now_eq  = _now_utc()
        _elapsed_h = (
            (_now_eq - _last_eq).total_seconds() / 3600
            if _last_eq else _ops_se["max_train_freq_hours"] + 1
        )
        if _elapsed_h < _ops_se["max_train_freq_hours"]:
            result["reason"] = f"頻度ガード: 前回から{_elapsed_h:.1f}h（最短{_ops_se['max_train_freq_hours']}h）"
            return result

        trigger_reason = ""

        # トリガー A: 採用件数
        _adopt_since = _count_adoptions_since(tenant_id, _last_eq)
        if _adopt_since >= _ops_se["trigger_adopt_count"]:
            trigger_reason = f"採用{_adopt_since}件到達（閾値{_ops_se['trigger_adopt_count']}）"

        # トリガー B: 週次
        if not trigger_reason and _last_eq:
            _elapsed_days = (_now_eq - _last_eq).total_seconds() / 86400
            if _elapsed_days >= _ops_se["weekly_retrain_days"]:
                trigger_reason = f"週次定期実行（{_elapsed_days:.1f}日経過）"
        elif not trigger_reason and not _last_eq:
            trigger_reason = "初回学習"

        # トリガー C: NDCG低下
        if not trigger_reason:
            try:
                perf_hist = load_performance_metrics_history(scope=tenant_id, limit=2)
                if len(perf_hist) >= 2:
                    _ndcg_latest = float(perf_hist[0].get("ndcg") or 0.0)
                    _ndcg_prev   = float(perf_hist[1].get("ndcg") or 0.0)
                    if _ndcg_prev > 0 and (_ndcg_prev - _ndcg_latest) >= _ops_se["ndcg_drop_threshold"]:
                        trigger_reason = (
                            f"NDCG低下検知: {_ndcg_prev:.4f}→{_ndcg_latest:.4f}"
                            f"（低下幅{_ndcg_prev - _ndcg_latest:.4f}≥閾値{_ops_se['ndcg_drop_threshold']}）"
                        )
            except Exception:
                pass

        if not trigger_reason:
            result["reason"] = "トリガー条件なし（採用数・経過日数・NDCG すべて閾値未満）"
            return result

        # ★ 管理画面で設定した job_defaults を使用（ハードコード既定値への落下を防ぐ）
        _sched_defaults = load_lgbm_job_defaults()
        job_id = enqueue_train_job(
            scope=tenant_id,
            tenant_id=tenant_id,
            trigger_type="scheduled",
            trigger_window={"reason": trigger_reason},
            note=f"auto: {trigger_reason}",
            params=_sched_defaults["params"],
            feature_set_id=_sched_defaults.get("feature_set_id", ""),
            data_window=_sched_defaults["data_window"],
            label_def=_sched_defaults["label_def"],
        )
        result.update({"triggered": True, "reason": trigger_reason, "job_id": job_id})
    except Exception as _e:
        result["reason"] = f"エラー: {_e}"
    return result

def list_model_versions(scope: str = None, limit: int = 20) -> list:
    """★ where+order_by 複合インデックス不要化: Python側でscopeフィルタ"""
    fs_guard()
    try:
        q = _model_versions_col().order_by("saved_at", direction=firestore.Query.DESCENDING)
        fetch_limit = limit * 15 if scope else limit
        docs = [
            {"version_id": d.id, **(d.to_dict() or {})}
            for d in _fs_stream_list(q, limit=fetch_limit)
        ]
        if scope:
            docs = [d for d in docs if d.get("scope") == scope]
        return docs[:limit]
    except Exception:
        return []

# ── lgbm_feature_sets（学習に使う特徴量集合）──────────────────────────
def _lgbm_feature_sets_col():
    fs_guard()
    return db.collection("lgbm_feature_sets")

def save_feature_set(
    feature_set_id: str,
    enabled_features: list,
    enabled_crosses: list = None,
    missing_policy: str = "zero",
    version: str = "1",
    note: str = "",
):
    fs_guard()
    _lgbm_feature_sets_col().document(feature_set_id).set({
        "feature_set_id":   feature_set_id,
        "enabled_features": enabled_features,
        "enabled_crosses":  enabled_crosses or [],
        "missing_policy":   missing_policy,
        "version":          version,
        "note":             note,
        "updated_at":       firestore.SERVER_TIMESTAMP,
    }, merge=False)

def load_feature_set(feature_set_id: str) -> dict:
    fs_guard()
    try:
        doc = _lgbm_feature_sets_col().document(feature_set_id).get()
        return (doc.to_dict() or {}) if doc.exists else {}
    except Exception:
        return {}

def list_feature_sets() -> list:
    fs_guard()
    return [{"feature_set_id": d.id, **(d.to_dict() or {})} for d in _lgbm_feature_sets_col().stream()]

def delete_feature_set(feature_set_id: str):
    fs_guard()
    _lgbm_feature_sets_col().document(feature_set_id).delete()

# ── feature_registry（動的特徴量定義）────────────────────────────────
_FEATURE_TYPES    = ["numeric", "categorical", "boolean", "text_stat", "derived"]
_FEATURE_SOURCES  = ["firestore", "runtime", "computed"]
_FEATURE_EXTRACTORS = ["last_value", "count_7d", "count_30d", "avg_7d", "avg_30d",
                       "sum_7d", "sum_30d", "exists", "ratio", "hash_encode", "identity"]

