# =====================================================================
# LGBM — リアルタイム特徴量抽出・結合パイプライン
# =====================================================================

# ── ① セッションキャッシュ（Firestore 叩きすぎ防止）────────────────
# tenant属性など「全チャンクで共通」の値を 1リクエスト内で使い回す。
# TTL は Streamlit rerun 単位（= リクエスト単位）で自然にリセットされる。

def _lgbm_cache_get(key: str):
    return st.session_state.get(f"_lgbm_fc_{key}")

def _lgbm_cache_set(key: str, val):
    st.session_state[f"_lgbm_fc_{key}"] = val
    return val

# ── ② Firestore source特徴量の前引き（バッチ取得）──────────────────
def _lgbm_prefetch_source_attrs(source_ids: list) -> dict:
    """
    source_ids を一括で sources コレクションから取得してキャッシュ。
    推論ループ内での1件ずつ .get() を排除する。
    返り値: {source_id: {priority, category, source_type, risk_tags, updated_at, ...}}
    """
    if not source_ids:
        return {}
    cache_key = "source_attrs_" + hashlib.sha256(",".join(sorted(source_ids)).encode()).hexdigest()[:12]
    cached = _lgbm_cache_get(cache_key)
    if cached is not None:
        return cached
    result = {}
    # Firestore は in クエリが10件上限なので 10件ずつバッチ
    try:
        ids = list(set(source_ids))
        for i in range(0, len(ids), 10):
            batch_ids = ids[i:i+10]
            # ★ デッドコード（if False ブランチ）を削除。sources_col() を直接使用
            for sid in batch_ids:
                try:
                    doc = sources_col().document(sid).get()
                    result[sid] = (doc.to_dict() or {}) if doc.exists else {}  # ★ 括弧で優先順位を明示
                except Exception:
                    result[sid] = {}
    except Exception:
        pass
    return _lgbm_cache_set(cache_key, result)

# ── ③ tenant属性の取得（キャッシュ済み）────────────────────────────
def _lgbm_get_tenant_attrs(tenant_id: str) -> dict:
    """
    tenant属性（enabled, name等）をセッションキャッシュから取得。
    日次バッチで前計算した集計値もここに乗せる想定。
    """
    cache_key = f"tenant_attrs_{tenant_id}"
    cached = _lgbm_cache_get(cache_key)
    if cached is not None:
        return cached
    try:
        doc = db.collection("tenants").document(tenant_id).get()
        attrs = (doc.to_dict() or {}) if doc.exists else {}
    except Exception:
        attrs = {}
    # 日次バッチ前計算値を system_settings から合流（あれば）
    try:
        batch_key = f"lgbm_tenant_stats_{tenant_id}"
        bdoc = db.collection("system_settings").document(batch_key).get()
        if bdoc.exists:
            attrs.update(bdoc.to_dict() or {})
    except Exception:
        pass
    return _lgbm_cache_set(cache_key, attrs)

# ── ④ クロス特徴量の展開────────────────────────────────────────────
def _expand_cross_features(feat_vec: dict, cross_defs: list) -> dict:
    """
    feature_cross_registry の定義に従いクロス特徴量を生成して feat_vec に追加。
    method: hash_concat / bucket_interaction / lookup_stat
    output: categorical_hash (float) / numeric (float)
    """
    out = {}
    for cd in cross_defs:
        if not cd.get("enabled", True):
            continue
        cross_key = cd.get("cross_key", "")
        inputs    = cd.get("inputs") or []
        method    = cd.get("method", "hash_concat")
        cons      = cd.get("constraints") or {}
        max_card  = int(cons.get("max_cardinality", 10000) or 10000)
        whitelist = cons.get("whitelist") or []
        blacklist = cons.get("blacklist") or []

        # whitelist/blacklist は tenant_id を基準にフィルタ
        ctx_tenant = str(feat_vec.get("tenant_id_raw", ""))
        if whitelist and ctx_tenant not in whitelist:
            continue
        if blacklist and ctx_tenant in blacklist:
            continue

        # 入力値を収集（なければ"unknown"）
        vals = [str(feat_vec.get(inp, feat_vec.get(inp + "_raw", "unknown"))) for inp in inputs]

        try:
            if method == "hash_concat":
                # 全入力を "_" 結合して固定ハッシュ化
                combined = "_".join(vals)
                out[cross_key] = float(
                    int(hashlib.sha256(combined.encode()).hexdigest()[:8], 16) % max_card
                )
            elif method == "bucket_interaction":
                # 各入力を int 化して積（整数空間での乗算）→ mod max_card
                product = 1
                for v in vals:
                    try:
                        product *= (int(float(v)) + 1)
                    except Exception:
                        product *= _stable_hash_int(v, max_card)
                out[cross_key] = float(abs(product) % max_card)
            elif method == "lookup_stat":
                # キャッシュから集計値を取得（前計算バッチが system_settings に保存する想定）
                stat_key = "lgbm_cross_" + hashlib.sha256("_".join(vals).encode()).hexdigest()[:12]
                cached_stat = _lgbm_cache_get(stat_key)
                if cached_stat is not None:
                    out[cross_key] = float(cached_stat)
                else:
                    try:
                        sdoc = db.collection("system_settings").document(stat_key).get()
                        val  = float((sdoc.to_dict() or {}).get("value", 0.0)) if sdoc.exists else 0.0
                    except Exception:
                        val = 0.0
                    out[cross_key] = _lgbm_cache_set(stat_key, val)
        except Exception:
            out[cross_key] = 0.0

    return out

# ── ⑤ 欠損ポリシー適用───────────────────────────────────────────────
def _apply_missing_policy(feat_vec: dict, feature_keys: list,
                          defaults: dict, policy: str) -> dict:
    """
    feature_keys の欠損を policy（zero / mean / unknown_category）で補完。
    mean は feat_vec 全体の平均値、unknown_category は hash("unknown")。
    """
    if policy == "zero":
        for k in feature_keys:
            if feat_vec.get(k) is None:
                feat_vec[k] = float(defaults.get(k, 0.0))
    elif policy == "mean":
        vals = [float(v) for v in feat_vec.values()
                if isinstance(v, (int, float)) and v is not None]
        mean_val = (sum(vals) / len(vals)) if vals else 0.0
        for k in feature_keys:
            if feat_vec.get(k) is None:
                feat_vec[k] = float(defaults.get(k, mean_val))
    elif policy == "unknown_category":
        unk = float(_stable_hash_int("unknown", 10000))
        for k in feature_keys:
            if feat_vec.get(k) is None:
                feat_vec[k] = float(defaults.get(k, unk))
    return feat_vec

# ── ⑥ Feature Registry から 1チャンクの特徴量ベクトルを抽出────────
def _extract_features_for_chunk(
    chunk: dict,
    query: str,
    query_terms: list,
    tenant_id: str,
    tenant_attrs: dict,
    source_attrs: dict,      # {source_id: {...}} 事前バッチ取得済み
    feature_defs: list,      # list_feature_defs(enabled_only=True) の結果
    now_utc: "datetime.datetime",
) -> dict:
    """
    1チャンクに対して feature_registry の全 enabled 特徴量を抽出し
    {feature_key: float} の辞書を返す。
    source / runtime / computed に応じて取得元を分岐。
    """
    chunk_text = str(chunk.get("text") or chunk.get("chunk") or chunk.get("content") or "")
    source_id  = str(chunk.get("source_id") or "")
    src        = source_attrs.get(source_id) or {}
    raw_ts     = chunk.get("updated_at") or chunk.get("created_at") or src.get("updated_at")

    # recency_days 共通計算（複数特徴量が参照）
    recency_days = 9999.0
    try:
        if isinstance(raw_ts, datetime.datetime):
            dt = raw_ts.astimezone(datetime.timezone.utc).replace(tzinfo=None) \
                 if raw_ts.tzinfo else raw_ts
            recency_days = max(0.0, (now_utc - dt).total_seconds() / 86400.0)
        elif raw_ts:
            recency_days = max(0.0, (now_utc - _parse_iso(str(raw_ts))).total_seconds() / 86400.0)
    except Exception:
        pass

    fv: dict = {}
    # raw値（クロス展開用）
    fv["tenant_id_raw"] = tenant_id or DEFAULT_TENANT

    for fd in feature_defs:
        fkey      = fd.get("feature_key", "")
        ftype     = fd.get("type", "numeric")
        source    = fd.get("source", "runtime")
        path      = fd.get("path", "")
        extractor = fd.get("extractor", "identity")
        default   = fd.get("default", 0)
        do_hash   = fd.get("hashing", False)

        raw_val = None

        if source == "runtime":
            # ── runtime: クエリ・チャンク・類似度等をその場計算 ──
            if fkey == "base_sim":
                raw_val = _safe_float(chunk.get("score", 0.0), 0.0)
            elif fkey == "is_force_include":
                raw_val = 1.0 if _safe_float(chunk.get("score", 0.0), 0.0) > 1.0 else 0.0
            elif fkey == "query_len":
                raw_val = float(len(query))
            elif fkey == "query_term_hits":
                hits = sum(1 for t in query_terms[:20] if t and t in chunk_text)
                raw_val = float(min(10.0, hits))
            elif fkey == "chunk_len":
                raw_val = float(len(chunk_text))
            elif fkey == "recency_days":
                raw_val = recency_days
            elif fkey == "priority":
                raw_val = float(int(chunk.get("priority", 0) or
                                    src.get("priority", 0) or 0))
            elif fkey == "risk_tag_cnt":
                raw_val = float(len(chunk.get("risk_tags") or src.get("risk_tags") or []))
            elif fkey == "has_question":
                raw_val = 1.0 if ("?" in query or "？" in query) else 0.0
            elif fkey == "has_percent":
                raw_val = 1.0 if "%" in query else 0.0
            elif fkey == "has_summary_req":
                raw_val = 1.0 if any(kw in query for kw in ("要約","まとめ","結論")) else 0.0
            elif fkey == "has_steps_req":
                raw_val = 1.0 if any(kw in query for kw in ("手順","チェック","やり方","実装")) else 0.0
            else:
                raw_val = default

        elif source == "firestore":
            # ── firestore: path で示すドキュメント/フィールドを参照 ──
            # path 書式: "collection/field" または "chunk" / "source" のショートハンド
            if path.startswith("chunk."):
                raw_val = chunk.get(path[6:])
            elif path.startswith("source."):
                raw_val = src.get(path[7:])
            elif path.startswith("tenant."):
                raw_val = tenant_attrs.get(path[7:])
            else:
                # 汎用: フィールド名を chunk → source → tenant の順で探す
                raw_val = chunk.get(path) or src.get(path) or tenant_attrs.get(path)

            # extractor 適用
            if extractor == "last_value":
                pass  # そのまま
            elif extractor in ("count_7d", "count_30d", "sum_7d", "sum_30d", "avg_7d", "avg_30d"):
                # 前計算バッチ値を system_settings から取得（キャッシュ済み優先）
                batch_stat_key = f"lgbm_feat_{fkey}_{tenant_id}"
                cached_stat    = _lgbm_cache_get(batch_stat_key)
                if cached_stat is not None:
                    raw_val = cached_stat
                else:
                    try:
                        sdoc = db.collection("system_settings").document(batch_stat_key).get()
                        raw_val = float((sdoc.to_dict() or {}).get("value", default)) \
                                  if sdoc.exists else default
                    except Exception:
                        raw_val = default
                    _lgbm_cache_set(batch_stat_key, raw_val)
            elif extractor == "exists":
                raw_val = 1.0 if raw_val not in (None, "", [], {}) else 0.0
            elif extractor == "ratio":
                try:
                    raw_val = float(raw_val)
                except Exception:
                    raw_val = float(default)

        elif source == "computed":
            # ── computed: hashing 等の変換のみ（値は他 key に依存） ──
            raw_val = fv.get(path, default)

        # 型変換
        if raw_val is None:
            fv[fkey] = None          # 後で欠損ポリシー補完
            continue

        if do_hash or ftype == "categorical":
            try:
                fv[fkey] = float(_stable_hash_int(str(raw_val), 10000))
            except Exception:
                fv[fkey] = 0.0
        elif ftype == "boolean":
            fv[fkey] = 1.0 if raw_val else 0.0
        else:
            try:
                fv[fkey] = float(raw_val)
            except Exception:
                fv[fkey] = float(default) if default is not None else 0.0

    return fv

# ── ⑦ Feature Set から行列を構築する中心関数────────────────────────
def build_feature_matrix(
    rows: list,
    query: str,
    tenant_id: str,
    feature_set_id: str = "",
) -> tuple:
    """
    Feature Registry + Feature Set に従い rows 全チャンクの特徴量行列を構築。
    返り値: (X: list[list[float]], feature_keys: list[str])
    - feature_set_id が空 or 未登録 → Registry の全 enabled 特徴量を使用
    - 欠損は feature_set の missing_policy で補完
    - クロス特徴量も展開して列に追加
    """
    if not rows:
        return [], []

    # 1. Feature Set 読み込み
    fset = load_feature_set(feature_set_id) if feature_set_id else {}
    enabled_feat_keys    = fset.get("enabled_features") or []
    enabled_cross_keys   = fset.get("enabled_crosses") or []
    missing_policy       = fset.get("missing_policy", "zero")

    # 2. Registry から定義取得（enabled_features 指定があればその範囲で絞る）
    all_feat_defs = list_feature_defs(enabled_only=True)
    if enabled_feat_keys:
        feat_defs = [fd for fd in all_feat_defs if fd["feature_key"] in enabled_feat_keys]
    else:
        feat_defs = all_feat_defs

    # Registry が空（未設定）の場合は内蔵 runtime 特徴量セットで続行する。
    # 「Registry必須」から「Registry優先、無ければ内蔵」へ設計を緩める。
    # _extract_features_for_chunk が source=="runtime" で処理済みのキーのみ使用。
    if not feat_defs:
        feat_defs = [
            {"feature_key": "base_sim",        "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "query_len",        "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "query_term_hits",  "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "chunk_len",        "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "recency_days",     "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 9999.0, "hashing": False},
            {"feature_key": "priority",         "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "risk_tag_cnt",     "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "has_question",     "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "has_percent",      "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "has_summary_req",  "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
            {"feature_key": "has_steps_req",    "type": "numeric", "source": "runtime", "path": "", "extractor": "identity", "default": 0.0, "hashing": False},
        ]

    # 3. クロス定義取得
    all_cross_defs = list_cross_defs(enabled_only=True)
    if enabled_cross_keys:
        cross_defs = [cd for cd in all_cross_defs if cd["cross_key"] in enabled_cross_keys]
    else:
        cross_defs = all_cross_defs

    feature_keys = [fd["feature_key"] for fd in feat_defs] + \
                   [cd["cross_key"] for cd in cross_defs if cd.get("enabled", True)]
    defaults     = {fd["feature_key"]: fd.get("default", 0) for fd in feat_defs}

    # 4. テナント属性を1回だけ取得（キャッシュ）
    tenant_attrs = _lgbm_get_tenant_attrs(tenant_id)

    # 5. source_id 一覧を先読み（バッチ Firestore 取得）
    source_ids   = list({r.get("source_id") or "" for r in rows})
    source_attrs = _lgbm_prefetch_source_attrs(source_ids)

    # 6. クエリ前処理（ループ外で1回）
    q_terms  = [t for t in re.split(r"\s+", (query or "").strip()) if t]
    now_utc  = _now_utc()

    # 7. 全チャンクを並列に特徴量抽出 → クロス展開 → 欠損補完
    X = []
    for row in rows:
        fv = _extract_features_for_chunk(
            chunk=row,
            query=query,
            query_terms=q_terms,
            tenant_id=tenant_id,
            tenant_attrs=tenant_attrs,
            source_attrs=source_attrs,
            feature_defs=feat_defs,
            now_utc=now_utc,
        )
        # クロス展開（feature_key の値を参照するため抽出後に実施）
        cross_fv = _expand_cross_features(fv, cross_defs)
        fv.update(cross_fv)
        # 欠損補完
        fv = _apply_missing_policy(fv, feature_keys, defaults, missing_policy)
        # 行列の列順を feature_keys に固定
        X.append([float(fv.get(k, 0.0)) for k in feature_keys])

    return X, feature_keys

# ── ⑧ model_active からアクティブモデルをホットリロード──────────────
# =====================================================================
# LGBM テレメトリ — 稼働状態の全観測
# _lgbm_tel() が返す辞書に全状態を集約。管理画面の検査パネルが参照する。
# =====================================================================
_LGBM_TEL_KEY = "_lgbm_tel"

def _lgbm_tel() -> dict:
    """テレメトリ辞書を取得（なければ初期化して返す）。"""
    if _LGBM_TEL_KEY not in st.session_state:
        st.session_state[_LGBM_TEL_KEY] = {
            # ── Rerank booster ──────────────────────────────────────
            "booster_rerank_status":    "unloaded",   # unloaded/no_path/ok/error
            "booster_rerank_scope":     "global",
            "booster_rerank_version":   "",
            "booster_rerank_gcs":       "",
            "booster_rerank_local":     "",
            "booster_rerank_loaded_at": "",
            "booster_rerank_feat_n":    0,
            "booster_rerank_last_err":  "",
            # ── Mode booster ────────────────────────────────────────
            "booster_mode_status":      "unloaded",
            "booster_mode_path":        "",
            "booster_mode_last_err":    "",
            # ── Summary booster ─────────────────────────────────────
            "booster_summary_status":   "unloaded",
            "booster_summary_path":     "",
            "booster_summary_last_err": "",
            # ── Rerank predict カウンター ────────────────────────────
            "rerank_call_count":        0,
            "rerank_ok_count":          0,
            "rerank_skip_count":        0,
            "rerank_err_count":         0,
            "rerank_last_err":          "",
            "rerank_last_rows_in":      0,
            "rerank_last_rows_out":     0,
            "rerank_last_feat_n":       0,
            "rerank_last_scores":       [],   # predict スコアサンプル最大10件
            "rerank_last_ts":           "",
            "rerank_pipeline":          "unknown",  # "registry" / "tenant" / "blended" / "fallback"
            # ── Tenant booster（自動切替）────────────────────────────
            "tenant_booster_status":    "unloaded",  # unloaded/ok/invalid/error/no_model
            "tenant_booster_tenant":    "",
            "tenant_booster_loaded_at": "",
            "tenant_booster_last_err":  "",
            "rerank_used_scope":        "global",    # "global" or "tenant"
            "rerank_blend_alpha":       0.0,         # 0=pure global, 1=pure tenant
            "rerank_tenant_ok_count":   0,
            "rerank_blend_count":       0,
            "rerank_global_fallback_count": 0,
            # ── Mode predict カウンター ──────────────────────────────
            "mode_call_count":          0,
            "mode_ok_count":            0,
            "mode_skip_count":          0,
            "mode_last_err":            "",
            # ── Summary predict カウンター ───────────────────────────
            "summary_call_count":       0,
            "summary_ok_count":         0,
            "summary_skip_count":       0,
            "summary_last_err":         "",
        }
    return st.session_state[_LGBM_TEL_KEY]

def _lgbm_tel_set(key: str, val):
    _lgbm_tel()[key] = val

def _lgbm_tel_inc(key: str, delta: int = 1):
    d = _lgbm_tel()
    d[key] = int(d.get(key, 0)) + delta

def _lgbm_load_booster_by_key(model_key: str):
    """
    lgbm_model_registry の model_key からボスターをロード（セッションキャッシュ付き）。
    gcs_path / ローカルパス 両対応。失敗時は None を返す。
    """
    cache_key  = f"_lgbm_booster__{model_key.replace('/', '_')}"
    hash_key   = f"_lgbm_booster_hash__{model_key.replace('/', '_')}"

    entry = get_model_registry_entry(model_key)
    if not entry:
        return None

    gcs = entry.get("gcs_path", "")
    entry_hash = hashlib.sha256(gcs.encode()).hexdigest()[:12]

    # キャッシュヒット（gcs_path 変化なし）
    if st.session_state.get(hash_key) == entry_hash and cache_key in st.session_state:
        return st.session_state[cache_key]

    local_path = ""
    if gcs.startswith("gs://"):
        try:
            from google.cloud import storage as _gcs_st
            _cli = _gcs_st.Client()
            _stripped = gcs[5:]
            _bkt_n    = _stripped.split("/")[0]
            _blob_p   = "/".join(_stripped.split("/")[1:])
            local_path = f"/tmp/lgbm__{model_key.replace('/', '_')}.txt"
            _cli.bucket(_bkt_n).blob(_blob_p).download_to_filename(local_path)
        except Exception as _ge:
            local_path = ""
    elif gcs and os.path.exists(gcs):
        local_path = gcs

    booster = None
    if local_path and os.path.exists(local_path):
        try:
            import lightgbm as lgb
            booster = lgb.Booster(model_file=local_path)
        except Exception:
            booster = None

    st.session_state[cache_key]  = booster
    st.session_state[hash_key]   = entry_hash
    return booster

def _lgbm_load_active_booster(scope: str = "global"):
    """
    active_model_pointer を最優先で参照（ロールバック対応）。
    pointer が未設定の場合は lgbm_model_registry → 旧 model_active の順にフォールバック。
    """
    booster_key = f"_lgbm_booster_{scope}"
    ver_key     = f"_lgbm_booster_ver_{scope}"

    # ── ★ active_model_pointer を最優先（ロールバック即時反映）─────────
    try:
        _ptr = get_active_model_pointer(scope)
        _ptr_gcs = _ptr.get("active_gcs_path", "")
        _ptr_mid = _ptr.get("active_model_id", "")
        if _ptr_gcs and _ptr_mid:
            _ptr_cache_key = f"_lgbm_booster__ptr_{scope}"
            _ptr_hash_key  = f"_lgbm_booster_hash__ptr_{scope}"
            # ★ gcs_path だけでなく active_model_id もハッシュに含める。
            # 同一パスに新モデルが上書きされた場合でも model_id が変わればキャッシュが
            # 無効化されるため、旧モデルが推論に残り続けるバグを防ぐ。
            _ptr_path_hash = hashlib.sha256((_ptr_gcs + "|" + _ptr_mid).encode()).hexdigest()[:12]
            if (
                st.session_state.get(_ptr_hash_key) == _ptr_path_hash
                and _ptr_cache_key in st.session_state
                and st.session_state[_ptr_cache_key] is not None
            ):
                return st.session_state[_ptr_cache_key]
            _local = ""
            if _ptr_gcs.startswith("gs://"):
                try:
                    from google.cloud import storage as _gcs_st2
                    _cli2 = _gcs_st2.Client()
                    _s2   = _ptr_gcs[5:]
                    _bkt2 = _s2.split("/")[0]
                    _blb2 = "/".join(_s2.split("/")[1:])
                    _local = f"/tmp/lgbm__ptr_{scope}.txt"
                    _cli2.bucket(_bkt2).blob(_blb2).download_to_filename(_local)
                except Exception as _pe2:
                    _local = ""
                    if scope == "global":
                        _lgbm_tel_set("booster_rerank_last_err", f"pointer GCS失敗: {_pe2}"[:200])
            elif _ptr_gcs and os.path.exists(_ptr_gcs):
                _local = _ptr_gcs
            if _local and os.path.exists(_local):
                try:
                    import lightgbm as lgb
                    _ptr_booster = lgb.Booster(model_file=_local)
                    st.session_state[_ptr_cache_key] = _ptr_booster
                    st.session_state[_ptr_hash_key]  = _ptr_path_hash
                    if scope == "global":
                        _lgbm_tel_set("booster_rerank_status",    "ok")
                        _lgbm_tel_set("booster_rerank_scope",     scope)
                    _lgbm_tel_set("booster_rerank_version", _ptr_mid[-8:])
                    _lgbm_tel_set("booster_rerank_gcs",     _ptr_gcs)
                    _lgbm_tel_set("booster_rerank_loaded_at",
                                  _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
                    try:
                        _lgbm_tel_set("booster_rerank_feat_n", _ptr_booster.num_feature())
                    except Exception:
                        pass
                    return _ptr_booster
                except Exception as _le2:
                    if scope == "global":
                        _lgbm_tel_set("booster_rerank_status",   "error")
                        _lgbm_tel_set("booster_rerank_last_err", str(_le2)[:200])
    except Exception:
        pass

    # ── 新 registry を参照（pointer 未設定時のフォールバック）──────────
    model_key = "lgbm_rerank/global" if scope == "global" else f"lgbm_rerank/tenant/{scope}"
    entry = get_model_registry_entry(model_key)
    if entry and entry.get("gcs_path"):
        booster = _lgbm_load_booster_by_key(model_key)
        if scope == "global":
            status = "ok" if booster else "error"
            _lgbm_tel_set("booster_rerank_status",   status)
            _lgbm_tel_set("booster_rerank_scope",    scope)
            _lgbm_tel_set("booster_rerank_gcs",      entry.get("gcs_path",""))
            if booster:
                _lgbm_tel_set("booster_rerank_loaded_at",
                              _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
                try:
                    _lgbm_tel_set("booster_rerank_feat_n", booster.num_feature())
                except Exception:
                    pass
        st.session_state[booster_key] = booster
        return booster

    # ── 旧 model_active フォールバック ─────────────────────────────────
    try:
        meta    = get_active_model_version(scope)
        cur_ver = meta.get("active_model_version", "")
        gcs     = meta.get("gcs_path", "")
    except Exception as _me:
        cur_ver, gcs = "", ""
        if scope == "global":
            _lgbm_tel_set("booster_rerank_last_err", f"model_active 取得失敗: {_me}"[:300])

    cached_ver = st.session_state.get(ver_key, "")
    if cur_ver and cur_ver == cached_ver and booster_key in st.session_state:
        return st.session_state[booster_key]

    if scope == "global":
        _lgbm_tel_set("booster_rerank_scope",   scope)
        _lgbm_tel_set("booster_rerank_version", cur_ver)
        _lgbm_tel_set("booster_rerank_gcs",     gcs)

    local_path = ""
    if gcs.startswith("gs://"):
        try:
            from google.cloud import storage as _gcs_storage
            _gcs_client  = _gcs_storage.Client()
            gcs_stripped = gcs[5:]
            bucket_name  = gcs_stripped.split("/")[0]
            blob_path    = "/".join(gcs_stripped.split("/")[1:])
            local_path   = f"/tmp/lgbm_model_{scope}_{cur_ver}.txt"
            _gcs_client.bucket(bucket_name).blob(blob_path).download_to_filename(local_path)
        except Exception as _ge:
            local_path = ""
            if scope == "global":
                _lgbm_tel_set("booster_rerank_status",   "error")
                _lgbm_tel_set("booster_rerank_last_err", f"GCS DL失敗: {_ge}"[:300])
    elif gcs and os.path.exists(gcs):
        local_path = gcs

    if scope == "global":
        _lgbm_tel_set("booster_rerank_local", local_path)

    booster = None
    if local_path and os.path.exists(local_path):
        try:
            import lightgbm as lgb
            booster = lgb.Booster(model_file=local_path)
            if scope == "global":
                _lgbm_tel_set("booster_rerank_status",    "ok")
                _lgbm_tel_set("booster_rerank_loaded_at",
                              _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
                _lgbm_tel_set("booster_rerank_last_err",  "")
                try:
                    _lgbm_tel_set("booster_rerank_feat_n", booster.num_feature())
                except Exception:
                    pass
        except Exception as _le:
            booster = None
            if scope == "global":
                _lgbm_tel_set("booster_rerank_status",   "error")
                _lgbm_tel_set("booster_rerank_last_err", str(_le)[:300])
    else:
        if scope == "global" and not gcs:
            _lgbm_tel_set("booster_rerank_status", "no_path")

    st.session_state[booster_key] = booster
    st.session_state[ver_key]     = cur_ver
    return booster

def _lgbm_resolve_booster_for_tenant(tenant_id: str):
    """
    推論に使用するボスターを決定する。
    ★ モデルファイル直参照ではなく active_model_pointer（tenant×industry）を参照。
      これにより Trainer が原子切替した瞬間、次のリクエストから新モデルが使われる。
      ロールバック時も pointer を戻すだけで推論側は変更不要。

    優先順位:
      1. active_model_pointer に active_gcs_path がある → そのモデルを使う
      2. なければ lgbm_model_registry の is_valid==True にフォールバック
      3. それもなければ global

    返り値: (global_booster, tenant_booster, alpha, used_scope)
    """
    global_booster = _lgbm_load_active_booster("global")

    if not tenant_id or tenant_id == DEFAULT_TENANT:
        _lgbm_tel_set("rerank_used_scope",  "global")
        _lgbm_tel_set("rerank_blend_alpha", 0.0)
        return global_booster, None, 0.0, "global"

    # ── ① active_model_pointer を参照（原子切替の受け側）──────────────────
    try:
        pointer = get_active_model_pointer(tenant_id)
        ptr_gcs = pointer.get("active_gcs_path", "")
        ptr_mid = pointer.get("active_model_id", "")
        if ptr_gcs and ptr_mid:
            # pointer が指す gcs_path でキャッシュキーを構築してロード
            _ptr_cache_key  = f"_lgbm_booster__ptr_{tenant_id}"
            _ptr_hash_key   = f"_lgbm_booster_hash__ptr_{tenant_id}"
            # ★ gcs_path だけでなく active_model_id もハッシュに含める。
            # 同一パスに新モデルが上書きされた場合でも model_id が変わればキャッシュが
            # 無効化されるため、旧モデルが推論に残り続けるバグを防ぐ（global側と統一）。
            _ptr_path_hash  = hashlib.sha256((ptr_gcs + "|" + ptr_mid).encode()).hexdigest()[:12]

            # キャッシュヒット判定（pointer更新時はハッシュが変わるので自動再ロード）
            if (
                st.session_state.get(_ptr_hash_key) == _ptr_path_hash
                and _ptr_cache_key in st.session_state
                and st.session_state[_ptr_cache_key] is not None
            ):
                tenant_booster = st.session_state[_ptr_cache_key]
            else:
                # ロード（GCS / ローカル両対応）
                local_path = ""
                if ptr_gcs.startswith("gs://"):
                    try:
                        from google.cloud import storage as _gcs_st
                        _cli = _gcs_st.Client()
                        _s   = ptr_gcs[5:]
                        _bkt = _s.split("/")[0]
                        _blb = "/".join(_s.split("/")[1:])
                        local_path = f"/tmp/lgbm__ptr_{tenant_id}.txt"
                        _cli.bucket(_bkt).blob(_blb).download_to_filename(local_path)
                    except Exception as _ge:
                        _lgbm_tel_set("tenant_booster_last_err", f"pointer GCS失敗: {_ge}"[:200])
                        local_path = ""
                elif ptr_gcs and os.path.exists(ptr_gcs):
                    local_path = ptr_gcs

                tenant_booster = None
                if local_path and os.path.exists(local_path):
                    try:
                        import lightgbm as lgb
                        tenant_booster = lgb.Booster(model_file=local_path)
                    except Exception as _le:
                        _lgbm_tel_set("tenant_booster_last_err", str(_le)[:200])

                st.session_state[_ptr_cache_key] = tenant_booster
                st.session_state[_ptr_hash_key]  = _ptr_path_hash

            if tenant_booster:
                # registry からメトリクス取得（alpha算出用）
                _entry = get_model_registry_entry(f"lgbm_rerank/tenant/{tenant_id}")
                train_rows = int((_entry or {}).get("train_rows", 0))
                _blend_r = load_lgbm_ops_config()["blend_r"]
                alpha = float(min(1.0, max(0.0, train_rows / _blend_r)))
                _lgbm_tel_set("rerank_used_scope",        "pointer")
                _lgbm_tel_set("rerank_blend_alpha",       alpha)
                _lgbm_tel_set("tenant_booster_status",    "ok")
                _lgbm_tel_set("tenant_booster_tenant",    tenant_id)
                _lgbm_tel_set("tenant_booster_model_id",  ptr_mid)
                _lgbm_tel_set("tenant_booster_loaded_at", _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
                _lgbm_tel_set("tenant_booster_last_err",  "")
                try:
                    _lgbm_tel_set("booster_rerank_feat_n", tenant_booster.num_feature())
                except Exception:
                    pass
                return global_booster, tenant_booster, alpha, "pointer"
    except Exception as _pe:
        _lgbm_tel_set("tenant_booster_last_err", f"pointer参照失敗: {_pe}"[:200])

    # ── ② フォールバック: registry is_valid==True ──────────────────────────
    # pointer未設定またはロード失敗時のみここに来る（旧互換）
    tenant_mk    = f"lgbm_rerank/tenant/{tenant_id}"
    tenant_entry = get_model_registry_entry(tenant_mk)
    if tenant_entry and tenant_entry.get("is_valid", False) and tenant_entry.get("status") == "active":
        try:
            tenant_booster = _lgbm_load_booster_by_key(tenant_mk)
            if tenant_booster:
                train_rows = int(tenant_entry.get("train_rows", 0))
                _blend_r2 = load_lgbm_ops_config()["blend_r"]
                alpha = float(min(1.0, max(0.0, train_rows / _blend_r2)))
                _lgbm_tel_set("rerank_used_scope",        "registry_fallback")
                _lgbm_tel_set("rerank_blend_alpha",       alpha)
                _lgbm_tel_set("tenant_booster_status",    "ok")
                _lgbm_tel_set("tenant_booster_tenant",    tenant_id)
                _lgbm_tel_set("tenant_booster_loaded_at", _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
                _lgbm_tel_set("tenant_booster_last_err",  "")
                try:
                    _lgbm_tel_set("booster_rerank_feat_n", tenant_booster.num_feature())
                except Exception:
                    pass
                return global_booster, tenant_booster, alpha, "tenant"
        except Exception as _te:
            _lgbm_tel_set("tenant_booster_status",   "error")
            _lgbm_tel_set("tenant_booster_last_err", str(_te)[:200])
    else:
        _lgbm_tel_set("tenant_booster_status",  "no_model" if not tenant_entry else "invalid")
        _lgbm_tel_set("tenant_booster_tenant",  tenant_id)

    # ── ③ 最終フォールバック: global ─────────────────────────────────────
    _lgbm_tel_inc("rerank_global_fallback_count")
    _lgbm_tel_set("rerank_used_scope",  "global")
    _lgbm_tel_set("rerank_blend_alpha", 0.0)
    return global_booster, None, 0.0, "global"

# -----------------------------
# LGBM Rerank (optional)
# -----------------------------
def _stable_hash_int(s: str, mod: int = 1000) -> int:
    try:
        h = hashlib.sha256((s or "").encode("utf-8")).hexdigest()
        return int(h[:8], 16) % int(mod)
    except Exception:
        return 0

def _lgbm_score_single(booster, feat: list) -> float:
    """booster.predict を1行に適用してスカラースコアを返す。失敗時は 0.0。"""
    try:
        import numpy as np
        arr = np.array([feat], dtype=float)
        result = booster.predict(arr)
        return float(result[0])
    except Exception:
        return 0.0

def _lgbm_rerank_rows(rows: list, query: str, tenant_id: str = None, shared_query_id: str = "") -> list:
    """
    Global / Tenant 自動切替 + 混合スコアによるリランク。
    ① tenant モデルが is_valid → α でブレンド
    ② tenant モデル無効 / 未存在 → global のみ（フォールバック）
    ③ モデル未ロード → rows そのまま返す
    ④ rerank 結果を lgbm_training_logs に保存（教師ログ）
    shared_query_id: チャット1ターン内の複数RAG呼び出しで共有するquery_id。
                     渡された場合はそれを使用し、session_stateの上書き断線を防ぐ。
    """
    if not rows:
        return rows

    _lgbm_tel_inc("rerank_call_count")
    _lgbm_tel_set("rerank_last_ts",      _now_utc().strftime("%Y-%m-%d %H:%M:%S UTC"))
    _lgbm_tel_set("rerank_last_rows_in", len(rows))

    _tid = tenant_id or DEFAULT_TENANT

    # ── ① ボスター解決（Global / Tenant 自動切替）────────────────────
    try:
        global_booster, tenant_booster, alpha, used_scope = (
            _lgbm_resolve_booster_for_tenant(_tid)
        )
    except Exception as _re0:
        _lgbm_tel_inc("rerank_err_count")
        _lgbm_tel_set("rerank_last_err", f"resolve失敗: {_re0}"[:200])
        return rows

    # モデルが何もない → フォールバック（cold start: 教師ログを保存して初回学習を可能にする）
    if not global_booster and not tenant_booster:
        _lgbm_tel_inc("rerank_skip_count")
        _lgbm_tel_set("rerank_pipeline",      "fallback")
        _lgbm_tel_set("rerank_last_rows_out", len(rows))
        # ★ fallback 経路でも active_model_pointer から model_id を取得して監査ログに残す。
        # これがないと used_model_id="" で保存され、後からどのモデルが使われるべきだったか
        # 照合できなくなる（Issue #5 修正）。
        _fallback_mid_cs  = ""
        _fallback_mver_cs = ""
        try:
            _fb_ptr = get_active_model_pointer(_tid)
            _fallback_mid_cs  = str(_fb_ptr.get("active_model_id", "") or "").strip()
            _fallback_mver_cs = str(_fb_ptr.get("model_version",   "") or "").strip()
        except Exception:
            pass

        try:
            _fsid_cs = ""
            try:
                _fsid_cs = str((load_lgbm_job_defaults() or {}).get("feature_set_id", "") or "").strip()
            except Exception:
                pass
            X_cs, fkeys_cs = build_feature_matrix(
                rows=rows, query=query, tenant_id=_tid, feature_set_id=_fsid_cs,
            )
            if X_cs:
                _schema_cs    = _compute_feature_schema_hash(fkeys_cs or [])
                _qid_cs       = shared_query_id or hashlib.sha256(
                    (_tid + query + _now_utc().isoformat()).encode("utf-8")
                ).hexdigest()[:20]
                _smap_cs:     dict = {}
                _best_cid_cs  = ""
                _pred_best_cs = -1.0

                # ★ Bug1修正: fallbackでも実際のユーザーランクを取得してDBに保存する
                # user_rank_index=0固定のままだとcompute_sample_weightが0.0を返し
                # 全サンプルがrank_gate除外され初回モデル学習が永久に不可になる
                _uid_cs        = authed_uid() or ""
                _rank_idx_cs   = 0
                _decision_cs   = "B"
                try:
                    if _uid_cs:
                        _u_snap_cs = users_col().document(_uid_cs).get()
                        _u_dict_cs = _u_snap_cs.to_dict() if _u_snap_cs.exists else {}
                        _level_score_cs = int(_u_dict_cs.get("level_score", 0))
                        _rank_cfg_cs    = load_rank_config(_tid)
                        _rank_name_cs   = score_to_rank_name(_level_score_cs, _rank_cfg_cs)
                        _all_names_cs   = [
                            _rank_cfg_cs["rank_1_name"], _rank_cfg_cs["rank_2_name"],
                            _rank_cfg_cs["rank_3_name"], _rank_cfg_cs["rank_4_name"],
                        ]
                        _rank_idx_cs = (
                            _all_names_cs.index(_rank_name_cs) + 1
                            if _rank_name_cs in _all_names_cs else 0
                        )
                        if _rank_idx_cs >= 4:
                            _decision_cs = "S"
                        elif _rank_idx_cs == 3:
                            _decision_cs = "A"
                        else:
                            _decision_cs = "B"
                except Exception:
                    pass

                for _ri, _row in enumerate(rows):
                    _cid  = str(_row.get("chunk_id") or _row.get("doc_id") or "")
                    _sc   = float(_row.get("score", 0.0))
                    _feat = X_cs[_ri] if _ri < len(X_cs) else []
                    _smap_cs[_cid] = _sc
                    if _sc > _pred_best_cs:
                        _pred_best_cs = _sc
                        _best_cid_cs  = _cid
                    save_rerank_result(
                        query_id=_qid_cs,
                        tenant_id=_tid,
                        chunk_id=_cid,
                        rerank_rank=_ri + 1,
                        rerank_score=_sc,
                        features_snapshot=_feat,
                        user_rank_index=_rank_idx_cs,
                        decision_grade=_decision_cs,
                        rank_before=_ri + 1,
                        rank_after=_ri + 1,
                        feature_set_id=_fsid_cs,
                        feature_schema_hash=_schema_cs,
                        # ★ fallback時もpointerのmodel_idとversionを記録（空のままだと監査ログ空振り）
                        used_model_id=_fallback_mid_cs,
                        used_model_version=_fallback_mver_cs,
                        used_scope="fallback",
                    )
                st.session_state["_lgbm_last_query_id"]  = _qid_cs
                st.session_state["_lgbm_last_tenant_id"] = _tid
                # score_map はマージ（arch/exec/ment 各 rerank 結果を蓄積、上書き禁止）
                _ex_smap_cs = st.session_state.get("_lgbm_last_score_map") or {}
                _ex_smap_cs.update(_smap_cs)
                st.session_state["_lgbm_last_score_map"] = _ex_smap_cs
                # pred_best / best_chunk_id は全 rerank 通じた最高値のみ更新
                _ex_pred_cs = float(st.session_state.get("_lgbm_last_pred_best", -1.0))
                if _pred_best_cs > _ex_pred_cs:
                    st.session_state["_lgbm_last_best_chunk_id"] = _best_cid_cs
                    st.session_state["_lgbm_last_pred_best"]     = _pred_best_cs
                st.session_state["_lgbm_last_rank_idx"]       = _rank_idx_cs
                st.session_state["_lgbm_last_decision_grade"] = _decision_cs
                st.session_state["_lgbm_last_decision"]       = _decision_cs
        except Exception:
            pass
        return rows

    try:
        import numpy as np

        # ── ② Feature Set / schema 解決 → 特徴量行列構築 ───────────────
        _fsid = ""
        _expect_t_hash = ""
        _expect_g_hash = ""
        # ★ 推論ログ用: どのモデルIDとversionを使ったかを保持
        # 実運用の主キーは model_id（model_version == model_id）。
        # 3点照合: Trainer cand["model_id"] == pointer.active_model_id == rerank_result.used_model_id
        _used_model_id_log      = ""
        _used_model_version_log = ""
        try:
            if used_scope == "pointer":
                _ptr_log = get_active_model_pointer(_tid)
                _used_model_id_log      = str(_ptr_log.get("active_model_id", "") or "").strip()
                _used_model_version_log = str(_ptr_log.get("model_version",   "") or "").strip()
        except Exception:
            pass

        # tenant pointer → 期待スキーマ（最優先）
        try:
            if _tid and _tid != DEFAULT_TENANT:
                _ptr = get_active_model_pointer(_tid)
                _m = (_ptr.get("metrics") or {}) if isinstance(_ptr, dict) else {}
                _fsid = str(_m.get("feature_set_id", "") or "").strip()
                _expect_t_hash = str(_m.get("feature_schema_hash", "") or "").strip()
        except Exception:
            pass

        # registry → 期待スキーマ（フォールバック）
        try:
            _t_entry = get_model_registry_entry(f"lgbm_rerank/tenant/{_tid}") if (_tid and _tid != DEFAULT_TENANT) else {}
            if not _fsid:
                _fsid = str((_t_entry or {}).get("feature_set_id", "") or "").strip()
            if not _expect_t_hash:
                _expect_t_hash = str((_t_entry or {}).get("feature_schema_hash", "") or "").strip()
        except Exception:
            pass

        try:
            _g_entry = get_model_registry_entry("lgbm_rerank/global")
            _expect_g_hash = str((_g_entry or {}).get("feature_schema_hash", "") or "").strip()
            if not _fsid:
                _fsid = str((_g_entry or {}).get("feature_set_id", "") or "").strip()
        except Exception:
            pass

        # job_defaults → 最終フォールバック（モデル未設定時）
        if not _fsid:
            try:
                _fsid = str((load_lgbm_job_defaults() or {}).get("feature_set_id", "") or "").strip()
            except Exception:
                _fsid = ""

        X, feature_keys = build_feature_matrix(
            rows=rows, query=query, tenant_id=_tid, feature_set_id=_fsid,
        )
        if X is None or not X:
            _lgbm_tel_inc("rerank_skip_count")
            _lgbm_tel_set("rerank_pipeline",      "fallback")
            _lgbm_tel_set("rerank_last_rows_out", len(rows))
            return rows

        schema_hash = _compute_feature_schema_hash(feature_keys or [])
        _lgbm_tel_set("rerank_feature_set_id", _fsid)
        _lgbm_tel_set("rerank_feature_schema_hash", schema_hash)

        # ── booster の schema 互換を検査（不一致なら無効化）──────────────
        if tenant_booster and _expect_t_hash and _expect_t_hash != schema_hash:
            tenant_booster = None
            alpha = 0.0
            _lgbm_tel_set(
                "tenant_booster_last_err",
                f"schema_mismatch: {_expect_t_hash} != {schema_hash}"[:200],
            )
        if global_booster and _expect_g_hash and _expect_g_hash != schema_hash:
            global_booster = None
            _lgbm_tel_set(
                "booster_rerank_last_err",
                f"schema_mismatch: {_expect_g_hash} != {schema_hash}"[:200],
            )

        if not global_booster and not tenant_booster:
            _lgbm_tel_inc("rerank_skip_count")
            _lgbm_tel_set("rerank_pipeline",      "fallback")
            _lgbm_tel_set("rerank_last_rows_out", len(rows))
            return rows

        arr = np.array(X, dtype=float)

        # ── ③ スコア計算（ブレンド or single）────────────────────────
        if tenant_booster and global_booster and 0.0 < alpha < 1.0:
            scores_t = tenant_booster.predict(arr)
            scores_g = global_booster.predict(arr)
            scores   = alpha * scores_t + (1.0 - alpha) * scores_g
            pipeline = "blended"
            _lgbm_tel_inc("rerank_blend_count")
        elif tenant_booster and alpha >= 1.0:
            scores   = tenant_booster.predict(arr)
            pipeline = "tenant"
            _lgbm_tel_inc("rerank_tenant_ok_count")
        else:
            scores   = global_booster.predict(arr)
            pipeline = "global"

        _lgbm_tel_set("rerank_last_feat_n", len(feature_keys or []))
        _lgbm_tel_set("rerank_pipeline",    pipeline)

        # ── ④ スコア付与 & ソート ────────────────────────────────────
        row_idx_map = {id(r): i for i, r in enumerate(rows)}
        for i, row in enumerate(rows):
            row["_lgbm_score"] = float(scores[i])

        rows_sorted = sorted(rows, key=lambda r: r.get("_lgbm_score", 0.0), reverse=True)

        sample = sorted([float(s) for s in scores], reverse=True)[:10]
        _lgbm_tel_set("rerank_last_scores",   sample)
        _lgbm_tel_set("rerank_last_rows_out", len(rows_sorted))
        _lgbm_tel_inc("rerank_ok_count")

        # ── ⑤ 教師ログ保存（lgbm_training_logs）+ score_map をセッション保持 ──
        try:
            query_id = shared_query_id or hashlib.sha256(
                (_tid + query + _now_utc().isoformat()).encode("utf-8")
            ).hexdigest()[:20]

            # ユーザーランク・ディシジョンを1回だけ取得
            _uid_for_log  = authed_uid() or ""
            _rank_idx_log = 0
            _decision_log = "B"

            _fc_score_at_log = 0.0   # ★ 追加: FC Scoreをログ時点でスナップショット
            try:
                if _uid_for_log:
                    _u_snap = users_col().document(_uid_for_log).get()
                    _u_dict = _u_snap.to_dict() if _u_snap.exists else {}
                    _level_score = int(_u_dict.get("level_score", 0))
                    _fc_score_at_log = float(_u_dict.get("fixed_concept_score", 0.0))   # ★ 追加
                    _rank_cfg    = load_rank_config(_tid)
                    _rank_name   = score_to_rank_name(_level_score, _rank_cfg)
                    _all_names   = [
                        _rank_cfg["rank_1_name"], _rank_cfg["rank_2_name"],
                        _rank_cfg["rank_3_name"], _rank_cfg["rank_4_name"],
                    ]
                    _rank_idx_log = (
                        _all_names.index(_rank_name) + 1
                        if _rank_name in _all_names else 0
                    )
            except Exception:
                pass

            # rank_idx → decision_grade（4=S / 3=A / 1-2=B）
            if _rank_idx_log >= 4:
                _decision_log = "S"
            elif _rank_idx_log == 3:
                _decision_log = "A"
            else:
                _decision_log = "B"

            # chunk_id → lgbm_score マップ（record_user_adoptions で fixed_gap に使用）
            _score_map: dict = {}
            _best_chunk_id  = ""
            _pred_best      = -1.0

            for rank_i, row in enumerate(rows_sorted):
                orig_idx = row_idx_map.get(id(row), -1)
                feat_vec = X[orig_idx] if orig_idx >= 0 else []
                cid      = str(row.get("chunk_id") or row.get("doc_id") or "")
                lgbm_sc  = float(row.get("_lgbm_score", 0.0))

                _score_map[cid] = lgbm_sc
                if lgbm_sc > _pred_best:
                    _pred_best     = lgbm_sc
                    _best_chunk_id = cid

                save_rerank_result(
                    query_id=query_id,
                    tenant_id=_tid,
                    chunk_id=cid,
                    rerank_rank=rank_i + 1,
                    rerank_score=lgbm_sc,
                    features_snapshot=feat_vec,
                    user_rank_index=_rank_idx_log,
                    decision_grade=_decision_log,
                    rank_before=orig_idx + 1,
                    rank_after=rank_i + 1,
                    fc_score_at_log=_fc_score_at_log,
                    feature_set_id=_fsid,
                    feature_schema_hash=schema_hash,
                    used_model_id=_used_model_id_log,
                    used_model_version=_used_model_version_log,
                    used_scope=used_scope,
                )

            # セッションに保持（record_user_adoptions が参照する）
            # shared_query_id 使用時は同値での上書きなので安全
            st.session_state["_lgbm_last_query_id"]  = query_id
            st.session_state["_lgbm_last_tenant_id"] = _tid
            # score_map はマージ（arch/exec/ment 各 rerank 結果を蓄積、上書き禁止）
            _ex_sm = st.session_state.get("_lgbm_last_score_map") or {}
            _ex_sm.update(_score_map)
            st.session_state["_lgbm_last_score_map"] = _ex_sm
            # ★ 断線1修正: feat_map もマージ（save_user_click が features_snapshot を参照するために必要）
            _feat_map_new: dict = {}
            for _fmi, _fmrow in enumerate(rows_sorted):
                _fmidx = row_idx_map.get(id(_fmrow), -1)
                _fmcid = str(_fmrow.get("chunk_id") or _fmrow.get("doc_id") or "")
                _fmvec = X[_fmidx] if _fmidx >= 0 else []
                if _fmcid:
                    _feat_map_new[_fmcid] = [float(v) for v in _fmvec]
            _ex_fm = st.session_state.get("_lgbm_last_feat_map") or {}
            _ex_fm.update(_feat_map_new)
            st.session_state["_lgbm_last_feat_map"] = _ex_fm
            # pred_best / best_chunk_id は全 rerank 通じた最高値のみ更新
            _ex_pred = float(st.session_state.get("_lgbm_last_pred_best", -1.0))
            if _pred_best > _ex_pred:
                st.session_state["_lgbm_last_best_chunk_id"] = _best_chunk_id
                st.session_state["_lgbm_last_pred_best"]     = _pred_best
            st.session_state["_lgbm_last_rank_idx"]       = _rank_idx_log
            st.session_state["_lgbm_last_decision_grade"] = _decision_log
            st.session_state["_lgbm_last_decision"]       = _decision_log

            # 自動再学習トリガーチェック（非 global）
            if _tid != DEFAULT_TENANT:
                try:
                    check_and_trigger_auto_retrain(_tid)
                except Exception:
                    pass
        except Exception:
            pass  # ログ保存失敗でもリランク結果は返す

        return rows_sorted

    except Exception as _re:
        _lgbm_tel_inc("rerank_err_count")
        _lgbm_tel_set("rerank_last_err", str(_re)[:300])
        # 例外時は global のみで再試行
        try:
            if global_booster:
                import numpy as np
                _fs2 = ""
                try:
                    _fs2 = str(_fsid or "").strip()
                except Exception:
                    _fs2 = ""
                if not _fs2:
                    try:
                        _fs2 = str((load_lgbm_job_defaults() or {}).get("feature_set_id", "") or "").strip()
                    except Exception:
                        _fs2 = ""

                X2, fkeys2 = build_feature_matrix(rows=rows, query=query, tenant_id=_tid, feature_set_id=_fs2)
                if X2:
                    sc2 = global_booster.predict(np.array(X2, dtype=float))
                    for i, row in enumerate(rows):
                        row["_lgbm_score"] = float(sc2[i])
                    _lgbm_tel_set("rerank_pipeline", "global_fallback_on_err")
                    _rows_fb = sorted(rows, key=lambda r: r.get("_lgbm_score", 0.0), reverse=True)
                    # ★ fallback 経路でも session_state を更新
                    # （record_user_adoptions → save_user_click の features_snapshot 断線を閉じる）
                    try:
                        _fb_qid = (
                            shared_query_id
                            or hashlib.sha256(
                                ((_tid or "") + (query or "") + _now_utc().isoformat()).encode("utf-8")
                            ).hexdigest()[:20]
                        )
                        _fb_score_map: dict = {}
                        _fb_feat_map:  dict = {}
                        for _fb_i, _fb_row in enumerate(_rows_fb):
                            _fb_cid = str(_fb_row.get("chunk_id") or _fb_row.get("doc_id") or "")
                            if _fb_cid:
                                _fb_score_map[_fb_cid] = float(_fb_row.get("_lgbm_score", 0.0))
                                _fb_feat_map[_fb_cid]  = [
                                    float(v) for v in (X2[_fb_i] if _fb_i < len(X2) else [])
                                ]
                        st.session_state["_lgbm_last_query_id"]  = _fb_qid
                        st.session_state["_lgbm_last_tenant_id"] = _tid
                        _ex_fb_sm = st.session_state.get("_lgbm_last_score_map") or {}
                        _ex_fb_sm.update(_fb_score_map)
                        st.session_state["_lgbm_last_score_map"] = _ex_fb_sm
                        _ex_fb_fm = st.session_state.get("_lgbm_last_feat_map") or {}
                        _ex_fb_fm.update(_fb_feat_map)
                        st.session_state["_lgbm_last_feat_map"]  = _ex_fb_fm
                    except Exception:
                        pass
                    return _rows_fb
        except Exception:
            pass
        return rows

def _text_basic_stats(text: str) -> dict:
    """クエリテキストの基本統計量を返す（LGBM特徴量用）。"""
    t = text or ""
    tl = t.lower()
    return {
        "len":         float(len(t)),
        "non_space":   float(sum(1 for c in t if not c.isspace())),
        "digits":      float(sum(1 for c in t if c.isdigit())),
        "has_percent": 1.0 if "%" in t else 0.0,
        "has_steps":   1.0 if any(kw in tl for kw in ("手順", "ステップ", "step", "①", "1.")) else 0.0,
        "has_summary": 1.0 if any(kw in tl for kw in ("要約", "まとめ", "サマリ", "summary")) else 0.0,
    }

def _try_load_lgbm_booster():
    """グローバルスコープのアクティブboosterをリロードして返す。"""
    return _lgbm_load_active_booster("global")

def lgbm_select_purpose_mode(
    query: str,
    tenant_id: str,
    enabled_modes: list = None,
    fallback: str = "auto",
) -> str:
    """LGBMスコアで purpose mode を選択する。モデル未ロード時は fallback を返す。"""
    booster = _lgbm_load_active_booster("global")
    if not booster:
        return detect_purpose_mode_auto(query, enabled_modes=enabled_modes) or fallback

    _enabled = [m for m in (enabled_modes or list(MODE_REGISTRY.keys())) if m and m != "auto" and m in MODE_REGISTRY]
    if not _enabled:
        return fallback

    stats = _text_basic_stats(query)
    t_hash = float(_stable_hash_int(str(tenant_id or DEFAULT_TENANT), 100000))

    best_mode = fallback
    best_score = float("-inf")

    q_lower = (query or "").lower()
    for mk in _enabled:
        reg = MODE_REGISTRY.get(mk) or {}
        kw_hits = 0.0
        for kw in (reg.get("detect_keywords") or [])[:40]:
            if kw and str(kw).lower() in q_lower:
                kw_hits += 1.0
        kw_hits = float(min(20.0, kw_hits))

        is_fallback = 1.0 if mk == fallback else 0.0

        feat = [
            t_hash,
            float(_stable_hash_int(str(mk), 10000)),
            stats["len"],
            stats["non_space"],
            stats["digits"],
            stats["has_percent"],
            stats["has_steps"],
            stats["has_summary"],
            kw_hits,
            is_fallback,
        ]
        sc = _lgbm_score_single(booster, feat)
        if sc > best_score:
            best_score = sc
            best_mode = mk

    return best_mode or fallback

def _try_load_lgbm_booster_from_path(model_path: str, _tel_prefix: str = "") -> object:
    """
    ローカルパスまたはGCSパスからboosterをロードする。
    キャッシュキーはパスのハッシュ。失敗時はNoneを返す。
    """
    if not model_path:
        return None
    cache_key = f"_lgbm_booster_path_{_stable_hash_int(model_path, 999999999)}"
    if cache_key in st.session_state:
        return st.session_state[cache_key]

    local_path = ""
    if model_path.startswith("gs://"):
        try:
            from google.cloud import storage as _gcs_storage
            _cli = _gcs_storage.Client()
            _stripped = model_path[5:]
            _bkt = _stripped.split("/")[0]
            _blob = "/".join(_stripped.split("/")[1:])
            local_path = f"/tmp/lgbm_path_{_stable_hash_int(model_path, 999999999)}.txt"
            _cli.bucket(_bkt).blob(_blob).download_to_filename(local_path)
        except Exception as _e:
            if _tel_prefix:
                _lgbm_tel_set(f"{_tel_prefix}_booster_err", str(_e)[:200])
            st.session_state[cache_key] = None
            return None
    elif os.path.exists(model_path):
        local_path = model_path

    booster = None
    if local_path and os.path.exists(local_path):
        try:
            import lightgbm as lgb
            booster = lgb.Booster(model_file=local_path)
        except Exception as _e2:
            if _tel_prefix:
                _lgbm_tel_set(f"{_tel_prefix}_booster_err", str(_e2)[:200])

    st.session_state[cache_key] = booster
    return booster

def lgbm_select_summary_lens(query: str, tenant_id: str, chosen_mode: str, default_preset: str = "expert") -> tuple:
    """summary preset と hierarchy を LGBM で選ぶ。返り値: (preset_key, hierarchy). テレメトリ計装済み。"""
    _lgbm_tel_inc("summary_call_count")
    preset_keys = list(SUMMARY_PRESETS.keys()) or ["expert", "executor", "mentor", "general"]
    default_preset = (default_preset or "expert").strip() or "expert"
    if default_preset not in preset_keys:
        default_preset = preset_keys[0]

    hier_candidates = ["raw", "prefer_summary", "summary_only"]

    model_path = os.environ.get("LGBM_SUMMARY_MODEL_PATH") or os.environ.get("LGBM_RERANK_MODEL_PATH") or ""
    
    booster = _try_load_lgbm_booster_from_path(model_path, _tel_prefix="summary")
    if not booster:
        _lgbm_tel_inc("summary_skip_count")
        ql = (query or "")
        hier = "prefer_summary" if ("要約" in ql or "まとめ" in ql) else "raw"
        return default_preset, hier

    stats = _text_basic_stats(query)
    t_hash = float(_stable_hash_int(str(tenant_id or DEFAULT_TENANT), 100000))
    m_hash = float(_stable_hash_int(str(chosen_mode or "auto"), 10000))
    q_lower = (query or "").lower()

    # --- preset selection (rank)
    best_preset = default_preset
    best_score = float("-inf")
    for pk in preset_keys:
        # ざっくり誘導：executor/mentor っぽい語のヒット数
        kw_hits = 0.0
        if pk == "executor":
            for kw in ("手順", "実装", "チェック", "ToDo", "todo", "運用", "具体"):
                if kw.lower() in q_lower:
                    kw_hits += 1.0
        elif pk == "mentor":
            for kw in ("習慣", "訓練", "メンタル", "マインド", "継続", "成長"):
                if kw.lower() in q_lower:
                    kw_hits += 1.0
        elif pk == "expert":
            for kw in ("構造", "戦略", "最適化", "原因", "支配", "力学"):
                if kw.lower() in q_lower:
                    kw_hits += 1.0
        else:
            for kw in ("概要", "まとめ", "全体", "要点"):
                if kw.lower() in q_lower:
                    kw_hits += 1.0
        kw_hits = float(min(10.0, kw_hits))

        is_default = 1.0 if pk == default_preset else 0.0
        feat = [
            t_hash,
            m_hash,
            float(_stable_hash_int(str(pk), 10000)),
            stats["len"],
            stats["digits"],
            stats["has_steps"],
            stats["has_summary"],
            kw_hits,
            is_default,
        ]
        sc = _lgbm_score_single(booster, feat)
        if sc > best_score:
            best_score = sc
            best_preset = pk

    # --- hierarchy selection (rank)
    best_hier = "raw"
    best_hsc = float("-inf")
    for hk in hier_candidates:
        # summary_only は「要約が欲しい」強いシグナルがないと選びにくくする
        bias = 0.0
        if hk == "summary_only":
            bias = 0.5 if stats["has_summary"] >= 1.0 else -0.5
        elif hk == "prefer_summary":
            bias = 0.2 if stats["has_summary"] >= 1.0 else 0.0

        feat = [
            t_hash,
            m_hash,
            float(_stable_hash_int(str(best_preset), 10000)),
            float(_stable_hash_int(str(hk), 10000)),
            stats["len"],
            stats["has_steps"],
            stats["has_summary"],
            bias,
        ]
        sc = _lgbm_score_single(booster, feat)
        if sc > best_hsc:
            best_hsc = sc
            best_hier = hk

    return best_preset, best_hier


def rag_retrieve_chunks(
    tenant_id: str,
    query: str,
    uid: str = "",
    per_category: int = 4,
    per_source_type: int = 3,
    total_limit: int = 18,
    fetch_cap: int = 800,
    min_score: float = 0.15,
    force_top: int = 6,
    query_plan: dict = None,
    rag_cfg: dict = None,
    chosen_mode: str = None,    # ★ モード別ソースフィルタ用
    shared_query_id: str = "",  # ★ 複数RAG呼び出し間で共有するquery_id（断線①修正）
):
    """
    改善版：Query Planによる強支配（パラメータ直接制御）に対応
    """
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    per_category = int(per_category or 0)
    per_source_type = int(per_source_type or 0)
    total_limit = int(total_limit or 0) or 18
    fetch_cap = int(fetch_cap or 0) or 800
    MIN_SCORE = float(min_score or 0.0)

    # ★ Query Plan 展開
    plan_cats = {}
    recency = "low"
    summary_preset = ""
    summary_hierarchy = "raw"   # raw / prefer_summary / summary_only
    if query_plan:
        retrieval_plan = query_plan.get("retrieval", {})
        # 呼出元がA/E/M比率を計算済みなため、ここでは total_limit を上書きしない
        plan_cats = retrieval_plan.get("categories", {})
        recency = retrieval_plan.get("recency_bias", "low")
        try:
            sl = query_plan.get("summary_lens", {}) or {}
            summary_preset = str(sl.get("preset", "") or "").strip()
            summary_hierarchy = str(sl.get("hierarchy", "raw") or "raw").strip()
        except Exception:
            summary_preset = ""
            summary_hierarchy = "raw"

    q_emb = embed_text(query, model="gemini-embedding-001")
    if not q_emb: return []

    links = _fs_stream_list(tenant_source_links_col().where("tenant_id", "==", tenant_id), limit=2000)
    allowed_sources = {}   # {source_id: {"category": str, "force_include": bool, "risk_tags": list}}

    for lnk in links:
        ld = lnk.to_dict() or {}
        if not ld.get("enabled", True):
            continue
        sid = ld.get("source_id")
        if not sid:
            continue

        # モード制御チェック
        _allowed_modes = ld.get("allowed_modes") or []
        _blocked_modes = ld.get("blocked_modes") or []
        if _allowed_modes and chosen_mode and chosen_mode not in _allowed_modes:
            continue   # このソースは指定モードで使用不可
        if _blocked_modes and chosen_mode and chosen_mode in _blocked_modes:
            continue   # このソースは指定モードでブロック

        allowed_sources[sid] = {
            "category":      ld.get("category", "general"),
            "force_include": bool(ld.get("force_include", False)),
            "risk_tags":     ld.get("risk_tags") or [],
            "priority":      int(ld.get("priority", 0)),
        }

    if not allowed_sources:
        return []

    # force_include ソースを最優先で確保
    force_source_ids = {sid for sid, meta in allowed_sources.items() if meta["force_include"]}

    source_ids = list(allowed_sources.keys())
    rows = []
    _img_ready_cache = {}  # {source_id: bool} 画像status確認のキャッシュ
    BATCH = 10  # Firestore "in" クエリの上限

    for i in range(0, len(source_ids), BATCH):
        batch_ids = source_ids[i:i + BATCH]
        try:
            snaps = _fs_stream_list(
                source_chunks_col()
                .where("source_id", "in", batch_ids)
                .limit(fetch_cap)
            )
        except Exception:
            continue

        for snap in snaps:
            d = snap.to_dict() or {}
            sid = d.get("source_id") or d.get("doc_id")

            if sid not in allowed_sources:
                continue

            meta = allowed_sources[sid]
            d["priority"] = int(meta.get("priority", 0))
            cat = meta["category"]
            d["category"] = cat
            d["doc_id"] = sid

            # force_include チャンクはスコアを最大に底上げして確実に上位へ
            if meta["force_include"]:
                d["score"] = 1.5   # cosine は最大1.0 なので強制上位
                rows.append(d)
                continue

            emb = _get_embedding_from_doc(d)
            sim = _cosine_sim(q_emb, emb)

            # ★ summary hierarchy 制御（Query Plan / LGBM の結果を反映）
            try:
                stype = str(d.get("source_type") or "").strip().lower()

                # ★ 画像ソースは status=ready のみ検索対象（pending/processing/error を除外）
                if stype == "image":
                    if sid not in _img_ready_cache:
                        try:
                            _sdoc = sources_col().document(sid).get()
                            _sd = (_sdoc.to_dict() or {}) if _sdoc.exists else {}
                            _img_ready_cache[sid] = (_sd.get("status") == "ready")
                        except Exception:
                            _img_ready_cache[sid] = False
                    if not _img_ready_cache.get(sid, False):
                        continue

                if summary_hierarchy == "summary_only":
                    if stype != "summary":
                        continue
                elif summary_hierarchy == "prefer_summary":
                    if stype == "summary":
                        sim += 0.08
                        if summary_preset:
                            _hay = (str(d.get("doc_id") or "") + " " + str(d.get("title") or "")).lower()
                            if f"__sum__{summary_preset.lower()}__" in _hay or f"summary:{summary_preset.lower()}" in _hay:
                                sim += 0.05
            except Exception:
                pass

            if sim >= MIN_SCORE:
                d["score"] = float(sim)
                rows.append(d)

    # ★ ブースト統一適用: retrieve_only の場合のみここでブースト適用してソート
    rag_cfg_local = rag_cfg if rag_cfg else load_rag_settings(tenant_id)
    if rag_cfg_local.get("apply_plan_boost_stage", "retrieve_only") == "retrieve_only":
        rows = apply_query_plan_boost(rows, query_plan, rag_cfg_local)
    else:
        rows.sort(key=lambda x: x.get("score", -1.0), reverse=True)

    # ★ LGBM rerank（任意・モデルがある場合のみ）
    # tenant_id を渡すことで lgbm_training_logs にテナント別で保存される
    rows = _lgbm_rerank_rows(rows, query, tenant_id=tenant_id, shared_query_id=shared_query_id)

    out = []
    rest = []
    if force_top > 0:
        out = rows[:force_top]
        rest = rows[force_top:]
    else:
        rest = rows

    by_cat = {}
    for r in rest:
        c = _norm_category(r.get("category") or "general")
        stp = r.get("source_type") or "note"
        by_cat.setdefault(c, {}).setdefault(stp, []).append(r)

    for c in by_cat.keys():
        for stp in by_cat[c].keys():
            by_cat[c][stp].sort(key=lambda x: x.get("score", -1.0), reverse=True)

    cat_best = []
    for c, mp in by_cat.items():
        best = -1.0
        for stp, arr in mp.items():
            if arr: best = max(best, float(arr[0].get("score", -1.0)))
        cat_best.append((c, best))
    cat_best.sort(key=lambda x: x[1], reverse=True)
    cats = [c for c, _ in cat_best]

    stype_order = {}
    for c in cats:
        bests = []
        for stp, arr in by_cat[c].items():
            b = float(arr[0].get("score", -1.0)) if arr else -1.0
            bests.append((stp, b))
        bests.sort(key=lambda x: x[1], reverse=True)
        stype_order[c] = [stp for stp, _ in bests]

    if per_source_type > 0:
        for c in cats:
            for stp in list(by_cat[c].keys()):
                by_cat[c][stp] = by_cat[c][stp][:per_source_type]

    picked_by_cat = {c: [] for c in cats}
    for c in cats:
        stypes = stype_order.get(c, list(by_cat[c].keys()))
        
        # ★ プランによるカテゴリ別取得上限の強支配
        cat_limit = per_category
        if plan_cats and c in plan_cats:
            try: cat_limit = int(plan_cats[c])
            except: pass
            
        while (cat_limit <= 0 or len(picked_by_cat[c]) < cat_limit) and any(by_cat[c].get(stp) for stp in stypes):
            for stp in stypes:
                arr = by_cat[c].get(stp) or []
                if arr:
                    picked_by_cat[c].append(arr.pop(0))
                    if cat_limit > 0 and len(picked_by_cat[c]) >= cat_limit:
                        break

    while len(out) < total_limit and any(picked_by_cat[c] for c in cats):
        for c in cats:
            if picked_by_cat[c]:
                out.append(picked_by_cat[c].pop(0))
                if len(out) >= total_limit:
                    break

    return out[:total_limit]

def _format_source_label(source_id: str, source_dict: dict) -> str:
    """source_id ではなく、日本語タイトル主体で見せるための表示ラベル。"""
    sd = source_dict or {}
    title = str(sd.get("title") or source_id).strip()
    category = str(sd.get("category") or "general").strip()
    return f"{title} ｜ {category} ｜ {source_id}"

def load_knowledge_docs(tenant_id: str, limit: int = 30):
    """【新方式】tenant_source_links → sources の順で、この業種のソース一覧を返す。"""
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    limit = int(limit or 0) or 30

    links = list(
        tenant_source_links_col()
        .where("tenant_id", "==", tenant_id)
        .limit(limit)
        .stream()
    )
    out = []
    for l in links:
        ld = l.to_dict() or {}
        sid = (ld.get("source_id") or "").strip()
        if not sid:
            continue
        try:
            sdoc = sources_col().document(sid).get()
            if sdoc.exists:
                # chat_summary（会話自動登録）は管理画面ソース一覧に表示しない
                sd = sdoc.to_dict() or {}
                if sd.get("source_type") == "chat_summary":
                    continue
                # 画像は status=ready のみ（pending/processing/error は検索・表示のノイズ源）
                if sd.get("source_type") == "image" and sd.get("status") != "ready":
                    continue
                out.append(sdoc)
        except Exception:
            continue
    return out

def migrate_knowledge_missing_to_default(max_docs: int = 500):
    """
    【新方式】中央倉庫(sources)を走査し、どの業種にも紐づいていないソースを 
    DEFAULT_TENANT ("default") に紐づけるリンクを作成する。
    """
    fs_guard()
    all_sources = list(sources_col().limit(int(max_docs)).stream())
    cnt = 0

    for sdoc in all_sources:
        sid = sdoc.id

        links = list(
            tenant_source_links_col()
            .where("source_id", "==", sid)
            .limit(1)
            .stream()
        )
        if links:
            continue

        sd = sdoc.to_dict() or {}
        cat = sd.get("category") or "general"

        # ★決定的doc_id
        link_id = tenant_source_link_doc_id(DEFAULT_TENANT, sid)

        tenant_source_links_col().document(link_id).set({
            "tenant_id": DEFAULT_TENANT,
            "source_id": sid,
            "category": cat,
            "enabled": True,
            "priority": 0,
            "visibility": "tenant",
            "created_at": firestore.SERVER_TIMESTAMP,
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        cnt += 1

    return cnt

def _norm_category(s: str) -> str:
    """カテゴリ名の正規化（空なら general）。"""
    s = (s or "").strip()
    if not s:
        return "general"
    # 余計な空白だけ整形（日本語カテゴリも許容）
    s = re.sub(r"\s+", " ", s).strip()
    return s[:60]

def _guess_source_type(filename: str = "", url: str = "") -> str:
    """ナレッジの入力元を推定。"""
    if (url or "").strip():
        return "url"
    name = (filename or "").lower().strip()
    if name.endswith(".pdf"):
        return "pdf"
    if name.endswith(".md") or name.endswith(".txt") or name.endswith(".text"):
        return "text"
    if name.endswith(".html") or name.endswith(".htm"):
        return "html"
    if name.endswith(".json"):
        return "json"
    if name.endswith(".odt") or name.endswith(".ods"):
        return "odf"
    if name.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
        return "image"
    return "note"

def _as_datetime(x):
    if x is None:
        return None
    # Firestore Timestamp は datetime 互換（DatetimeWithNanoseconds）のことが多い
    if isinstance(x, datetime.datetime):
        return x
    try:
        # google.protobuf Timestamp 互換
        if hasattr(x, "ToDatetime"):
            return x.ToDatetime()
        if hasattr(x, "to_datetime"):
            return x.to_datetime()
    except Exception:
        return None
    return None

def load_knowledge_docs_for_lm(
    tenant_id: str,
    per_category: int = 5,
    max_age_days: int = 180,
    total_limit: int = 40,
    fetch_cap: int = 400,
) -> List[dict]:
    """
    【新方式】LM投入用に sources を取得（tenant_source_links 経由、Round-Robin方式）。
    1. tenantに紐づくsourceを取得
    2. カテゴリごとに分類し、日付順ソート（updated_at / created_at）
    3. カテゴリごとに per_category 件まで足切り
    4. 残りをラウンドロビンで total_limit まで詰め込む
    5. 最終結果を日付順（新しい順）に戻して返す
    """
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    per_category = int(per_category or 0) if per_category is not None else 0
    max_age_days = int(max_age_days or 0) if max_age_days is not None else 0
    total_limit = int(total_limit or 0) if total_limit is not None else 0
    fetch_cap = int(fetch_cap or 0) if fetch_cap is not None else 0

    # 1) links → sources
    links = list(
        tenant_source_links_col()
        .where("tenant_id", "==", tenant_id)
        .limit(fetch_cap or 400)
        .stream()
    )

    snaps = []
    for l in links:
        sid = ((l.to_dict() or {}).get("source_id") or "").strip()
        if not sid:
            continue
        try:
            sdoc = sources_col().document(sid).get()
            if sdoc.exists:
                snaps.append(sdoc)
        except Exception:
            continue

    # dict化
    docs = []
    for s in snaps:
        d = s.to_dict() or {}
        d["doc_id"] = d.get("doc_id") or getattr(s, "id", "")
        docs.append(d)

    # タイムゾーンAware（UTC）な変換関数を共通化
    def _ts(dct):
        t = dct.get("updated_at") or dct.get("created_at")
        if hasattr(t, "to_datetime"):
            try:
                return t.to_datetime().astimezone(datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(t, datetime.datetime):
            return t.astimezone(datetime.timezone.utc) if t.tzinfo else t.replace(tzinfo=datetime.timezone.utc)
        return None

    # max_age_days フィルタ
    if max_age_days and max_age_days > 0:
        # tz-aware (UTC) な現在時刻から cutoff を計算
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=max_age_days)
        docs2 = []
        for d in docs:
            t = _ts(d)
            if t is None or t >= cutoff:
                docs2.append(d)
        docs = docs2

    # カテゴリごとに分ける
    buckets = {}
    for d in docs:
        cat = (d.get("category") or "general").strip()
        buckets.setdefault(cat, []).append(d)

    # 日付で降順ソート
    def _sort_key(dct):
        t = _ts(dct)
        # missing 時も tz-aware な min を返すことで TypeError を防ぐ
        return t if t else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    for cat, arr in buckets.items():
        arr.sort(key=_sort_key, reverse=True)
        if per_category and per_category > 0:
            buckets[cat] = arr[:per_category]

    # ラウンドロビン
    cats = list(buckets.keys())
    # カテゴリの巡回順：各カテゴリ先頭の新しさで並べる
    cats.sort(key=lambda c: _sort_key(buckets[c][0]) if buckets.get(c) else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    out = []
    idx = 0
    while cats and (not total_limit or len(out) < total_limit):
        cat = cats[idx % len(cats)]
        if buckets.get(cat):
            out.append(buckets[cat].pop(0))
        if not buckets.get(cat):
            cats.remove(cat)
            if not cats:
                break
            idx = idx % len(cats)
        else:
            idx += 1

    # 最終を新しい順に戻す
    out.sort(key=_sort_key, reverse=True)
    if total_limit and total_limit > 0:
        out = out[:total_limit]
    return out

def create_usage_log(user_id: str, tenant_id: str, prompt: str, is_admin_test: bool = False, purpose_mode: str = ""):
    """usage_logs を作成し、後で response/cases を追記できるよう DocumentReference を返す。"""
    fs_guard()
    ref = db.collection("usage_logs").document()
    ref.set(
        {
            "user_id": user_id,
            "tenant_id": tenant_id or DEFAULT_TENANT,
            "prompt": prompt,
            "timestamp": firestore.SERVER_TIMESTAMP,
            "is_admin_test": bool(is_admin_test),
            "purpose_mode": (purpose_mode or "").strip(),
        },
        merge=True,
    )
    return ref

def update_usage_log(ref, response: str = "", cases: Optional[List[str]] = None,
                     chunk_ids: Optional[List[str]] = None,
                     decision_grade: str = "",
                     lgbm_query_id: str = ""):
    """create_usage_log の ref に追記。ref が無ければ何もしない。"""
    try:
        if ref is None:
            return
        payload = {"updated_at": firestore.SERVER_TIMESTAMP}
        if response is not None:
            payload["response"] = response
        if cases is not None:
            payload["cases"] = list(cases)
        if chunk_ids is not None:
            payload["chunk_ids"] = [str(c) for c in chunk_ids if c]
        if decision_grade:
            payload["decision_grade"] = str(decision_grade).upper()
        if lgbm_query_id:
            payload["lgbm_query_id"] = str(lgbm_query_id)
        ref.set(payload, merge=True)
    except Exception:
        pass

def load_usage_logs_df(limit: int = 3000) -> pd.DataFrame:
    fs_guard()
    try:
        q = db.collection("usage_logs").order_by("timestamp", direction=firestore.Query.DESCENDING)
        logs = _fs_stream_list(q, limit=limit)
    except Exception:
        logs = _fs_stream_list(db.collection("usage_logs"), limit=limit)

    if not logs:
        return pd.DataFrame()
    rows = [l.to_dict() for l in logs]
    df = pd.DataFrame(rows)
    if "timestamp" in df.columns:
        df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce", utc=True)
    if "is_admin_test" not in df.columns:
        df["is_admin_test"] = False
    if "tenant_id" not in df.columns:
        df["tenant_id"] = DEFAULT_TENANT
    df["tenant_id"] = df["tenant_id"].fillna(DEFAULT_TENANT)
    if "user_id" not in df.columns:
        df["user_id"] = ""
    if "prompt" not in df.columns:
        df["prompt"] = ""
    if "response" not in df.columns:
        df["response"] = ""
    # cases は list[str] の想定。ランキング用にテキスト化しておく
    if "cases_text" not in df.columns:
        if "cases" in df.columns:
            def _cases_to_text(v):
                if isinstance(v, list):
                    return "".join([str(x) for x in v if str(x).strip()])
                if v is None:
                    return ""
                return str(v)
            df["cases_text"] = df["cases"].apply(_cases_to_text)
        else:
            df["cases_text"] = ""
    return df

def load_usage_logs_for_user_tenant(uid: str, tenant_id: str, limit: int = 200) -> pd.DataFrame:
    fs_guard()
    docs = []
    try:
        q = (
            db.collection("usage_logs")
            .where("user_id", "==", uid)
            .where("tenant_id", "==", tenant_id)
            .where("is_admin_test", "==", False)
            .order_by("timestamp", direction=firestore.Query.DESCENDING)
            .limit(int(limit))
        )
        docs = _fs_stream_list(q)
    except Exception:
        try:
            q = (
                db.collection("usage_logs")
                .where("user_id", "==", uid)
                .where("tenant_id", "==", tenant_id)
                .limit(int(limit))
            )
            docs = _fs_stream_list(q)
        except Exception:
            docs = []

    if not docs:
        return pd.DataFrame(columns=["timestamp", "prompt", "user_id", "tenant_id", "is_admin_test"])
    
    rows = [d.to_dict() for d in docs]
    df = pd.DataFrame(rows)
    
    if "timestamp" in df.columns:
        df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce", utc=True)
    if "is_admin_test" not in df.columns:
        df["is_admin_test"] = False
    if "prompt" not in df.columns:
        df["prompt"] = ""
    if "response" not in df.columns:
        df["response"] = ""
    if "cases_text" not in df.columns:
        if "cases" in df.columns:
            def _cases_to_text(v):
                if isinstance(v, list):
                    return "".join([str(x) for x in v if str(x).strip()])
                if v is None:
                    return ""
                return str(v)
            df["cases_text"] = df["cases"].apply(_cases_to_text)
        else:
            df["cases_text"] = ""

    df = df[df["is_admin_test"] != True]
    
    if not df.empty and "timestamp" in df.columns:
        df = df.sort_values("timestamp", ascending=True)
    
    return df.reset_index(drop=True)

def load_usage_logs_for_tenant(tenant_id: str, limit: int = 5000) -> pd.DataFrame:
    fs_guard()
    docs = []
    try:
        q = (
            db.collection("usage_logs")
            .where("tenant_id", "==", tenant_id)
            .where("is_admin_test", "==", False)
            .order_by("timestamp", direction=firestore.Query.DESCENDING)
            .limit(int(limit))
        )
        docs = _fs_stream_list(q)
    except Exception:
        try:
            q = (
                db.collection("usage_logs")
                .where("tenant_id", "==", tenant_id)
                .limit(int(limit))
            )
            docs = _fs_stream_list(q)
        except Exception:
            docs = []

    if not docs:
        return pd.DataFrame(columns=["timestamp", "prompt", "response", "user_id", "tenant_id", "is_admin_test"])
    
    rows = [d.to_dict() for d in docs]
    df = pd.DataFrame(rows)

    if "timestamp" in df.columns:
        df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce", utc=True)
    if "prompt" not in df.columns:
        df["prompt"] = ""
    if "response" not in df.columns:
        df["response"] = ""
    if "is_admin_test" not in df.columns:
        df["is_admin_test"] = False
        
    df = df[df["is_admin_test"] != True]

    if not df.empty and "timestamp" in df.columns:
        df = df.sort_values("timestamp", ascending=False)

    return df.head(limit)


# ===== 使用ワードランキング（簡易） =====
_WORD_TOKEN_RE = re.compile(r"[A-Za-z0-9_]+|[一-龥々〆ヵヶぁ-んァ-ヴー]+")

_DEFAULT_STOPWORDS = {
    "これ","それ","あれ","ここ","そこ","あそこ","こちら","どちら","あちら",
    "です","ます","でした","ました","する","して","した","なる","なっ","ある","いる",
    "ので","ため","から","まで","より","など","そして","また","ただ","しかし","でも","ので",
    "こと","もの","よう","ほう","ところ","時","場合",
    "the","a","an","and","or","to","of","in","on","for","with","as","is","are","be","was","were",
}

def word_ranking_from_text(text: str, top_n: int = 30, extra_stopwords=None) -> pd.DataFrame:
    if not text:
        return pd.DataFrame(columns=["word", "count"])

    sw = set(_DEFAULT_STOPWORDS)
    if extra_stopwords:
        sw.update({s.strip() for s in extra_stopwords if str(s).strip()})

    tokens = _WORD_TOKEN_RE.findall(text)
    counts = {}
    for t in tokens:
        t = t.strip().lower()
        if not t:
            continue
        if (t.isascii() and len(t) < 3) or (not t.isascii() and len(t) < 2):
            continue
        if t in sw:
            continue
        # ノイズトークン除外（base64・アンダースコア・純数字・ファイル系）
        if "_" in t:
            continue
        if t.isdigit():
            continue
        if len(t) >= 8 and t.isalnum() and t.isascii():
            continue
        _noise_words = {
            "png","jpg","jpeg","gif","svg","pdf","csv","json","xml","html",
            "http","https","image","images","img","file","files","data",
            "base64","bytes","size","type","true","false","none","null",
            "width","height","url","uri","path","uid","token","str","int",
            "float","list","dict","bool","hxl","ncy","hxi",
        }
        if t in _noise_words:
            continue
            continue
        counts[t] = counts.get(t, 0) + 1

    items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[:top_n]
    return pd.DataFrame(items, columns=["word", "count"])

def word_ranking_df(df: pd.DataFrame, cols: List[str], top_n: int = 30, exclude: Optional[Set[str]] = None):
    if df is None or df.empty:
        return pd.DataFrame(columns=["word", "count"])
    use_cols = [c for c in cols if c in df.columns]
    if not use_cols:
        return pd.DataFrame(columns=["word", "count"])
    txt = "\n".join(df[use_cols].astype(str).fillna("").agg(" ".join, axis=1).tolist())
    return word_ranking_from_text(txt, top_n=top_n, extra_stopwords=exclude)

def word_ranking_from_chat_messages(msgs: List[dict], top_n: int = 30, exclude: Optional[Set[str]] = None) -> pd.DataFrame:
    if not msgs:
        return pd.DataFrame(columns=["word", "count"])
    # ユーザー発言のみカウント（AI応答を含めると頻出語が大幅に水増しされるため）
    txt = "\n".join([str(m.get("content", "")) for m in msgs if (m.get("content") or "").strip() and m.get("role") == "user"])
    return word_ranking_from_text(txt, top_n=top_n, extra_stopwords=exclude)

def merge_word_ranking(dfs: List[pd.DataFrame]) -> pd.DataFrame:
    base = {}
    for df in dfs:
        if df is None or df.empty:
            continue
        for _, r in df.iterrows():
            w = str(r.get("word", "")).strip()
            c = int(r.get("count", 0) or 0)
            if not w:
                continue
            base[w] = base.get(w, 0) + c
    items = sorted(base.items(), key=lambda x: (-x[1], x[0]))
    return pd.DataFrame(items, columns=["word", "count"])

def customer_activity_summary(df_logs: pd.DataFrame) -> pd.DataFrame:
    if df_logs is None or df_logs.empty:
        return pd.DataFrame(columns=["uid", "tenant_id", "actions", "last_action"])
    df = df_logs.copy()
    if "is_admin_test" in df.columns:
        df = df[df["is_admin_test"] != True]
    g = (
        df.groupby(["user_id", "tenant_id"], dropna=True)
        .agg(actions=("prompt", "count"), last_action=("timestamp", "max"))
        .reset_index()
        .rename(columns={"user_id": "uid"})
    )
    g["last_action"] = pd.to_datetime(g["last_action"], errors="coerce", utc=True)
    return g.sort_values(["actions", "uid"], ascending=[False, True]).reset_index(drop=True)


# -----------------------------
# Chat persistence (threaded)
# -----------------------------
SS_CHAT_ID = "chat_id"  # ★追加：スレッドID（ユーザーが新規チャットを増やすため）

def _normalize_chat_id(chat_id: str) -> str:
    chat_id = (chat_id or "").strip()
    return chat_id or "main"

def _get_active_chat_id(chat_id: str = None) -> str:
    # 画面側が未対応でも落ちないようにする（デフォルト main）
    if chat_id is not None:
        return _normalize_chat_id(chat_id)
    return _normalize_chat_id(st.session_state.get(SS_CHAT_ID, "main"))

def _chat_session_doc_id(scope: str, tenant_id: str, uid: str, chat_id: str = None) -> str:
    _cid = _get_active_chat_id(chat_id)
    return f"{scope}__{tenant_id}__{uid}__{_cid}"

def _chat_session_doc_ref(scope: str, tenant_id: str, uid: str, chat_id: str = None):
    fs_guard()
    return db.collection("chat_sessions").document(
        _chat_session_doc_id(scope, tenant_id, uid, chat_id=chat_id)
    )

def _default_chat_title(chat_id: str) -> str:
    _cid = _normalize_chat_id(chat_id)
    return "main" if _cid == "main" else _cid

def ensure_chat_session(scope: str, tenant_id: str, uid: str, chat_id: str = None, title: str = None):
    fs_guard()
    _cid = _get_active_chat_id(chat_id)
    _title = (title or "").strip() or _default_chat_title(_cid)
    _chat_session_doc_ref(scope, tenant_id, uid, chat_id=_cid).set(
        {
            "scope": scope,
            "tenant_id": tenant_id or DEFAULT_TENANT,
            "uid": uid,
            "chat_id": _cid,
            "title": _title,
            "is_deleted": False,
            "updated_at": firestore.SERVER_TIMESTAMP,
            "created_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )

def save_chat_session_label(scope: str, tenant_id: str, uid: str, chat_id: str, title: str):
    fs_guard()
    _cid = _get_active_chat_id(chat_id)
    _title = (title or "").strip() or _default_chat_title(_cid)
    ensure_chat_session(scope, tenant_id, uid, chat_id=_cid, title=_title)
    _chat_session_doc_ref(scope, tenant_id, uid, chat_id=_cid).set(
        {
            "title": _title,
            "is_deleted": False,
            "updated_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )

def chat_ref(scope: str, tenant_id: str, uid: str, chat_id: str = None):
    fs_guard()
    return _chat_session_doc_ref(scope, tenant_id, uid, chat_id=chat_id).collection("messages")

def _chat_doc_parts(doc) -> Tuple[str, str, str, str]:
    try:
        parent_doc = doc.reference.parent.parent
        chat_doc_id = parent_doc.id if parent_doc else ""
    except Exception:
        chat_doc_id = ""

    parts = str(chat_doc_id).split("__", 3)
    if len(parts) < 4:
        return "", "", "", ""
    return (
        str(parts[0]).strip(),
        str(parts[1]).strip(),
        str(parts[2]).strip(),
        str(parts[3]).strip(),
    )

def _chat_doc_scope_and_tenant(doc) -> Tuple[str, str]:
    """
    chat_sessions/{scope}__{tenant_id}__{uid}__{chat_id}/messages/{msg_id}
    から scope / tenant_id を安全に復元する。
    """
    _scope, _tenant_id, _, _ = _chat_doc_parts(doc)
    return _scope, _tenant_id

def _chat_sort_dt(v):
    try:
        if hasattr(v, "to_datetime"):
            v = v.to_datetime()
        if isinstance(v, datetime.datetime):
            if v.tzinfo is not None:
                return v.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return v
    except Exception:
        pass
    return datetime.datetime.min

def load_chat_sessions(scope: str, tenant_id: str, uid: str, include_main: bool = True, scan_limit: int = 3000) -> List[dict]:
    fs_guard()
    tenant_id = tenant_id or DEFAULT_TENANT
    rows = {}

    # 1) まず親ドキュメントから復元
    try:
        q = (
            db.collection("chat_sessions")
            .where("scope", "==", scope)
            .where("tenant_id", "==", tenant_id)
            .where("uid", "==", uid)
        )
        for d in _fs_stream_list(q):
            x = d.to_dict() or {}
            if bool(x.get("is_deleted", False)):
                continue
            _cid = _normalize_chat_id(x.get("chat_id") or d.id.split("__")[-1])
            rows[_cid] = {
                "chat_id": _cid,
                "title": (x.get("title") or "").strip() or _default_chat_title(_cid),
                "updated_at": x.get("updated_at") or x.get("last_message_at") or x.get("created_at"),
            }
    except Exception:
        pass

    # 2) 旧データ救済：messages だけ存在するスレッドを拾って親ドキュメントを自動作成
    try:
        docs = []
        try:
            docs = list(
                db.collection_group("messages")
                .order_by("ts", direction=firestore.Query.DESCENDING)
                .limit(scan_limit)
                .stream()
            )
        except Exception:
            docs = list(db.collection_group("messages").limit(scan_limit).stream())

        for d in docs:
            _scope, _tenant_id, _uid, _cid = _chat_doc_parts(d)
            if _scope != scope or _tenant_id != tenant_id or _uid != uid:
                continue

            _cid = _normalize_chat_id(_cid)
            _ts = (d.to_dict() or {}).get("ts")

            if _cid not in rows:
                rows[_cid] = {
                    "chat_id": _cid,
                    "title": _default_chat_title(_cid),
                    "updated_at": _ts,
                }
                ensure_chat_session(scope, tenant_id, uid, chat_id=_cid, title=rows[_cid]["title"])
            else:
                if _chat_sort_dt(_ts) > _chat_sort_dt(rows[_cid].get("updated_at")):
                    rows[_cid]["updated_at"] = _ts
    except Exception:
        pass

    # 3) main は必ず存在させる
    if include_main and "main" not in rows:
        rows["main"] = {"chat_id": "main", "title": "main", "updated_at": None}
        ensure_chat_session(scope, tenant_id, uid, chat_id="main", title="main")

    out = list(rows.values())
    out.sort(
        key=lambda x: (_chat_sort_dt(x.get("updated_at")), x.get("chat_id") != "main"),
        reverse=True,
    )

    if include_main:
        out_map = {x["chat_id"]: x for x in out}
        main_row = out_map.pop("main", {"chat_id": "main", "title": "main", "updated_at": None})
        out = [main_row] + list(out_map.values())

    return out

def save_chat_message(
    scope: str,
    tenant_id: str,
    uid: str,
    msg_role: str,
    content: str,
    cases: list = None,
    chat_id: str = None,
    generated_images: list = None,
):
    _cid = _get_active_chat_id(chat_id)

    # メッセージ保存前に親スレッドを確実に作る
    ensure_chat_session(scope, tenant_id, uid, chat_id=_cid)

    # スレッドの更新時刻も更新
    _chat_session_doc_ref(scope, tenant_id, uid, chat_id=_cid).set(
        {
            "scope": scope,
            "tenant_id": tenant_id or DEFAULT_TENANT,
            "uid": uid,
            "chat_id": _cid,
            "last_message_at": firestore.SERVER_TIMESTAMP,
            "updated_at": firestore.SERVER_TIMESTAMP,
            "is_deleted": False,
        },
        merge=True,
    )

    ref = chat_ref(scope, tenant_id, uid, chat_id=_cid)
    doc = {"role": msg_role, "content": content, "ts": firestore.SERVER_TIMESTAMP}

    if cases:
        doc["cases"] = cases

    # ── 画像は chat_image_blobs コレクションに1枚1ドキュメントで保存 ──
    # Firestore のドキュメント上限は 1MB。
    # base64画像データをメッセージ本体に直接入れると超過して 400 になるため分離する。
    _image_blob_ids = []
    for _img in (generated_images or []):
        if not isinstance(_img, dict):
            continue

        _data = _img.get("data")

        if isinstance(_data, (bytes, bytearray)) and _data:
            _data = base64.b64encode(bytes(_data)).decode("utf-8")
        elif isinstance(_data, str):
            _data = _data.strip()
        else:
            try:
                _data = base64.b64encode(bytes(_data)).decode("utf-8")
            except Exception:
                continue

        if not _data or not isinstance(_data, str):
            continue

        _mime = str(_img.get("mime_type") or "image/png")

        try:
            # 画像1枚 = 独立ドキュメント（サイズ上限回避）
            # Firestore ドキュメント上限は 1MB。base64 画像が大きい場合はここで失敗する。
            _blob_ref = db.collection("chat_image_blobs").add({
                "mime_type": _mime,
                "data":      _data,
                "ts":        firestore.SERVER_TIMESTAMP,
                "scope":     scope,
                "tenant_id": tenant_id or DEFAULT_TENANT,
                "uid":       uid,
            })
            # add() は (update_time, DocumentReference) を返す
            _blob_doc_id = _blob_ref[1].id if isinstance(_blob_ref, tuple) else _blob_ref.id
            _image_blob_ids.append(str(_blob_doc_id))
        except Exception as _blob_err:
            # 保存失敗：セッションにフラグを立てて呼び出し元で警告表示できるようにする
            print(f"[IMG_BLOB_SAVE_ERR] {_blob_err}")
            try:
                import streamlit as _st_inner
                _st_inner.session_state["_img_blob_save_failed"] = True
            except Exception:
                pass
            continue

    # メッセージ本体にはIDのみ保存（データは持たない）
    if _image_blob_ids:
        doc["image_blob_ids"] = _image_blob_ids

    ref.add(doc)

def load_chat_messages(scope: str, tenant_id: str, uid: str, limit: int = 60, chat_id: str = None):
    ref = chat_ref(scope, tenant_id, uid, chat_id=chat_id)
    q = ref.order_by("ts", direction=firestore.Query.DESCENDING).limit(limit).stream()
    rows = [d.to_dict() for d in q]
    rows.reverse()

    msgs = []
    for r in rows:
        rr = r.get("role")
        cc = r.get("content", "")
        if rr in ("user", "assistant") and cc:
            msg = {"role": rr, "content": cc}

            if rr == "assistant" and r.get("cases"):
                msg["cases"] = r["cases"]

            if rr == "assistant":
                _restored_images = []

                # ── 新形式: image_blob_ids からFirestoreを引いて復元 ──
                _blob_ids = r.get("image_blob_ids") or []
                for _bid in _blob_ids:
                    try:
                        _bdoc = db.collection("chat_image_blobs").document(str(_bid)).get()
                        if not _bdoc.exists:
                            continue
                        _bdata = _bdoc.to_dict() or {}
                        _d = _bdata.get("data")
                        _m = str(_bdata.get("mime_type") or "image/png")
                        if isinstance(_d, str) and _d.strip():
                            _restored_images.append({"mime_type": _m, "data": _d.strip()})
                    except Exception as _be:
                        print(f"[IMG_BLOB_LOAD_ERR] blob_id={_bid} err={_be}")
                        continue

                # ── 旧形式: generated_images が直接入っている場合の後方互換 ──
                for _img in (r.get("generated_images") or []):
                    if not isinstance(_img, dict):
                        continue
                    _data = _img.get("data")
                    if not isinstance(_data, str) or not _data.strip():
                        continue
                    _restored_images.append({
                        "mime_type": str(_img.get("mime_type") or "image/png"),
                        "data": _data.strip(),
                    })

                if _restored_images:
                    msg["generated_images"] = _restored_images

            msgs.append(msg)

    return msgs

def delete_chat_session(scope: str, tenant_id: str, uid: str, chat_id: str):
    fs_guard()
    _cid = _get_active_chat_id(chat_id)
    clear_chat(scope, tenant_id, uid, chat_id=_cid)
    try:
        _chat_session_doc_ref(scope, tenant_id, uid, chat_id=_cid).delete()
    except Exception:
        pass


def load_all_chat_messages(limit: int = 8000) -> List[dict]:
    """
    chat_sessions/*/messages を横断して、userスコープの role=user/assistant の
    content を集約する。
    """
    fs_guard()
    limit = max(1, int(limit or 8000))
    rows = []
    docs = []

    try:
        q = (
            db.collection_group("messages")
            .order_by("ts", direction=firestore.Query.DESCENDING)
            .limit(limit)
        )
        docs = list(q.stream())
    except Exception:
        try:
            q = db.collection_group("messages").limit(limit)
            docs = list(q.stream())

            def _get_ts(d):
                t = (d.to_dict() or {}).get("ts")
                if hasattr(t, "to_datetime"):
                    try:
                        return t.to_datetime()
                    except Exception:
                        pass
                if isinstance(t, datetime.datetime):
                    return t
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

            docs.sort(key=_get_ts, reverse=True)
        except Exception:
            return []

    for d in docs:
        if "admin_test" in d.reference.path:
            continue

        scope, _tenant_id = _chat_doc_scope_and_tenant(d)
        if scope and scope != "user":
            continue

        x = d.to_dict() or {}
        rr = x.get("role")
        cc = (x.get("content") or "").strip()
        if rr in ("user", "assistant") and cc:
            rows.append({"role": rr, "content": cc})

    rows.reverse()
    return rows


def load_all_chat_messages_for_tenant(tenant_id: str, limit: int = 8000) -> List[dict]:
    """
    chat_sessions/*/messages を横断し、指定 tenant の user スコープのみ集約する。
    collection_group 側で tenant 条件を直接掛けられないため、取得後に親doc_idを解析して絞る。
    """
    fs_guard()
    tenant_id = str(tenant_id or DEFAULT_TENANT).strip() or DEFAULT_TENANT
    limit = max(1, int(limit or 8000))
    fetch_limit = max(limit * 5, limit)

    rows = []
    docs = []

    try:
        q = (
            db.collection_group("messages")
            .order_by("ts", direction=firestore.Query.DESCENDING)
            .limit(fetch_limit)
        )
        docs = list(q.stream())
    except Exception:
        try:
            q = db.collection_group("messages").limit(fetch_limit)
            docs = list(q.stream())

            def _get_ts(d):
                t = (d.to_dict() or {}).get("ts")
                if hasattr(t, "to_datetime"):
                    try:
                        return t.to_datetime()
                    except Exception:
                        pass
                if isinstance(t, datetime.datetime):
                    return t
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

            docs.sort(key=_get_ts, reverse=True)
        except Exception:
            return []

    for d in docs:
        if "admin_test" in d.reference.path:
            continue

        scope, msg_tenant = _chat_doc_scope_and_tenant(d)
        if scope != "user" or msg_tenant != tenant_id:
            continue

        x = d.to_dict() or {}
        rr = x.get("role")
        cc = (x.get("content") or "").strip()
        if rr in ("user", "assistant") and cc:
            rows.append({"role": rr, "content": cc})
            if len(rows) >= limit:
                break

    rows.reverse()
    return rows

def clear_chat(scope: str, tenant_id: str, uid: str, batch_size: int = 100, chat_id: str = None):
    fs_guard()
    ref = chat_ref(scope, tenant_id, uid, chat_id=chat_id)
    while True:
        q = list(ref.order_by("ts", direction=firestore.Query.DESCENDING).limit(batch_size).stream())
        if not q:
            break
        batch = db.batch()
        for d in q:
            batch.delete(d.reference)
        batch.commit()

def load_chat_messages_across_sessions(
    uid: str, tenant_id: str, limit: int = 60
) -> List[dict]:
    """
    ユーザーの全 chat_session（全 chat_id）を横断して直近 limit 件のメッセージを返す。
    単一セッションしか見ない load_chat_messages の制限を回避する。
    """
    fs_guard()
    tenant_id = str(tenant_id or DEFAULT_TENANT).strip() or DEFAULT_TENANT
    _prefix = f"user__{tenant_id}__{uid}__"

    # ① 対象テナント+ユーザーのセッションドキュメント一覧を取得
    try:
        _all_refs = list(db.collection("chat_sessions").list_documents())
        _target_refs = [r for r in _all_refs if r.id.startswith(_prefix)]
    except Exception:
        # list_documents が使えない環境 → "main" のみフォールバック
        _target_refs = [
            db.collection("chat_sessions").document(f"{_prefix}main")
        ]

    if not _target_refs:
        _target_refs = [
            db.collection("chat_sessions").document(f"{_prefix}main")
        ]

    # ② 各セッションの messages を取得してマージ
    _all_msgs: List[dict] = []
    _fetch_per_session = max(limit, 60)
    for _sref in _target_refs:
        try:
            _qdocs = list(
                _sref.collection("messages")
                .order_by("ts", direction=firestore.Query.DESCENDING)
                .limit(_fetch_per_session)
                .stream()
            )
            for d in _qdocs:
                _x = d.to_dict() or {}
                _rr = _x.get("role")
                _cc = (_x.get("content") or "").strip()
                _ts = _x.get("ts")
                if _rr in ("user", "assistant") and _cc:
                    _all_msgs.append({"role": _rr, "content": _cc, "_ts": _ts})
        except Exception:
            continue

    if not _all_msgs:
        return []

    # ③ ts 降順ソート → 直近 limit 件 → 昇順に戻す
    def _sort_key(m):
        t = m.get("_ts")
        try:
            if hasattr(t, "to_datetime"):
                return t.to_datetime()
            if isinstance(t, datetime.datetime):
                return t
        except Exception:
            pass
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    _all_msgs.sort(key=_sort_key, reverse=True)
    _all_msgs = _all_msgs[:limit]
    _all_msgs.reverse()

    return [{"role": m["role"], "content": m["content"]} for m in _all_msgs]


def delete_usage_logs_for_user(uid: str, batch_size: int = 100):
    fs_guard()
    col = db.collection("usage_logs")
    while True:
        q = list(col.where("user_id", "==", uid).limit(batch_size).stream())
        if not q:
            break
        batch = db.batch()
        for d in q:
            batch.delete(d.reference)
        batch.commit()

def delete_chat_sessions_for_user(uid: str, tenant_id: Optional[str] = None):
    """スレッド化後の全 chat_id を対象に messages を削除し、親ドキュメントも消す。"""
    fs_guard()
    tenants_list = [tenant_id] if tenant_id else [t["tenant_id"] for t in list_tenants(include_disabled=True)]
    for t in tenants_list:
        # スレッド化後の全親ドキュメントを列挙して削除
        try:
            _parent_prefix = f"user__{t}__{uid}__"
            _all_session_docs = list(
                db.collection("chat_sessions")
                .list_documents()
            )
        except Exception:
            _all_session_docs = []

        _deleted_any = False
        for _doc_ref in _all_session_docs:
            if _doc_ref.id.startswith(f"user__{t}__{uid}__"):
                # サブコレクション messages を全削除してから親を消す
                _chat_id_part = _doc_ref.id.split("__")[-1]
                clear_chat("user", t, uid, chat_id=_chat_id_part)
                try:
                    _doc_ref.delete()
                except Exception:
                    pass
                _deleted_any = True

        if not _deleted_any:
            # list_documents が使えない環境用フォールバック（旧形式 + main のみ）
            clear_chat("user", t, uid, chat_id="main")
            try:
                db.collection("chat_sessions").document(f"user__{t}__{uid}").delete()
            except Exception:
                pass

