def compute_decision_metrics_from_usage(uid: str, tenant_id: str, level_score: int = 0, weights: dict = None) -> dict:
    """
    チャット利用データからリアルタイムに6指標を演算する。
    Firestoreの保存済み診断に依存しない常時表示用。
    Q: level_score基準  R: プロンプト語彙多様性
    S: 平均プロンプト長  V: ターン累計数
    P: 継続セッション日数 E: 利用密度（ターン×長さ）
    weights: 各指標のウェイト辞書（合計100想定）。Noneの場合はデフォルト使用。
    """
    # ウェイト正規化（合計が0なら全均等、それ以外は0〜1に正規化）
    _DEFAULT_WEIGHTS = {"Q": 30, "R": 20, "S": 15, "V": 15, "P": 10, "E": 10}
    _w = {k: float(v) for k, v in (weights or _DEFAULT_WEIGHTS).items()}
    _w_sum = sum(_w.values()) or 100.0
    _w = {k: v / _w_sum for k, v in _w.items()}
    fs_guard()

    turn_count      = 0
    avg_prompt_len  = 0.0
    session_count   = 0
    unique_keywords = 0

    try:
        _logs_raw = list(
            db.collection("usage_logs")
            .where("user_id", "==", uid)
            .limit(200)
            .stream()
        )
        _logs = [
            l for l in _logs_raw
            if (l.to_dict() or {}).get("tenant_id") == tenant_id
            and not (l.to_dict() or {}).get("is_admin_test")
        ][:60]
        turn_count = len(_logs)
        if _logs:
            _prompts = []
            _dates   = set()
            for _l in _logs:
                _d = _l.to_dict() or {}
                _p = str(_d.get("prompt", "")).strip()
                if _p:
                    _prompts.append(_p)
                _ts = _d.get("timestamp")
                if _ts and hasattr(_ts, "strftime"):
                    _dates.add(_ts.strftime("%Y-%m-%d"))
            if _prompts:
                avg_prompt_len = sum(len(p) for p in _prompts) / len(_prompts)
                unique_keywords = len(set(" ".join(_prompts).split()))
            session_count = len(_dates)
    except Exception:
        pass

    # Q 意思決定精度: level_score → 50-95
    if level_score >= 451:
        decision_quality_score = 90.0
    elif level_score >= 201:
        decision_quality_score = 75.0 + (level_score - 201) / 250 * 15.0
    elif level_score >= 81:
        decision_quality_score = 60.0 + (level_score - 81)  / 120 * 15.0
    else:
        decision_quality_score = 50.0 + level_score / 80 * 10.0
    decision_quality_score = round(min(decision_quality_score, 95.0), 1)

    # R リスク耐性: プロンプト語彙の多様性
    if unique_keywords >= 200:  risk_tolerance = 85.0
    elif unique_keywords >= 80: risk_tolerance = 65.0
    elif unique_keywords >= 20: risk_tolerance = 55.0
    else:                       risk_tolerance = 45.0

    # S 構造理解: 平均プロンプト文字数（構造化度代理）
    if avg_prompt_len >= 150:  structural_intelligence = 85.0
    elif avg_prompt_len >= 60: structural_intelligence = 65.0
    elif avg_prompt_len >= 20: structural_intelligence = 55.0
    else:                      structural_intelligence = 45.0

    # V 判断速度: 累計チャットターン数
    if turn_count >= 36:  decision_velocity = 85.0
    elif turn_count >= 18: decision_velocity = 70.0
    elif turn_count >= 6:  decision_velocity = 60.0
    else:                  decision_velocity = 50.0

    # P 予測精度: 継続利用セッション日数（長期的視野の代理）
    if session_count >= 10:  prediction_accuracy = 85.0
    elif session_count >= 4: prediction_accuracy = 70.0
    elif session_count >= 2: prediction_accuracy = 60.0
    else:                    prediction_accuracy = 50.0

    # E 実行一貫性: ターン数×平均長（利用密度）
    _e_raw = min(turn_count * avg_prompt_len / 1000.0, 100.0)
    if _e_raw >= 15:  execution_consistency = 85.0
    elif _e_raw >= 5: execution_consistency = 70.0
    elif _e_raw >= 1: execution_consistency = 55.0
    else:             execution_consistency = 45.0

    # 総合診断スコア（6指標全合成 / 業種ウェイト適用）
    diagnosis_total_score = round(
        _w["Q"] * decision_quality_score  +
        _w["R"] * risk_tolerance          +
        _w["S"] * structural_intelligence +
        _w["V"] * decision_velocity       +
        _w["P"] * prediction_accuracy     +
        _w["E"] * execution_consistency,
        1
    )

    # 診断ランク
    if   diagnosis_total_score >= 90: diagnosis_rank = "S"
    elif diagnosis_total_score >= 82: diagnosis_rank = "A+"
    elif diagnosis_total_score >= 78: diagnosis_rank = "A"
    elif diagnosis_total_score >= 74: diagnosis_rank = "A-"
    elif diagnosis_total_score >= 70: diagnosis_rank = "B+"
    elif diagnosis_total_score >= 65: diagnosis_rank = "B"
    elif diagnosis_total_score >= 60: diagnosis_rank = "B-"
    elif diagnosis_total_score >= 55: diagnosis_rank = "C+"
    elif diagnosis_total_score >= 50: diagnosis_rank = "C"
    else:                             diagnosis_rank = "D"

    return {
        "decision_quality_score":  decision_quality_score,
        "risk_tolerance":          risk_tolerance,
        "decision_velocity":       decision_velocity,
        "structural_intelligence": structural_intelligence,
        "prediction_accuracy":     prediction_accuracy,
        "execution_consistency":   execution_consistency,
        "diagnosis_total_score":   diagnosis_total_score,
        "diagnosis_rank":          diagnosis_rank,
    }


def load_all_decision_metrics_admin(limit: int = 200) -> list:
    """
    Admin用：全ユーザーの decision_metrics を収集して返す。
    ※ collection group query を使用（Firestoreインデックス要）。
    """
    fs_guard()
    try:
        docs = list(
            db.collection_group("records")
            .order_by("created_at", direction=firestore.Query.DESCENDING)
            .limit(limit)
            .stream()
        )
        result = []
        for d in docs:
            data = d.to_dict() or {}
            # decision_metrics の records だけを対象にする
            if "diagnosis_total_score" in data:
                _ts = data.get("created_at")
                if hasattr(_ts, "strftime"):
                    data["created_at"] = _ts.strftime("%Y-%m-%d %H:%M")
                elif _ts is not None:
                    data["created_at"] = str(_ts)[:16]
                result.append(data)
        return result
    except Exception:
        return []


def deep_delete_user(uid: str):
    delete_usage_logs_for_user(uid)
    delete_chat_sessions_for_user(uid, tenant_id=None)

    # user_diagnoses 削除
    try:
        _diag_docs = list(_user_diagnoses_col().where("uid", "==", uid).stream())
        for _dd in _diag_docs:
            _dd.reference.delete()
    except Exception:
        pass

    # ★ fixed_concept_logs 削除
    try:
        _fc_docs = list(
            db.collection("fixed_concept_logs").where("uid", "==", uid).stream()
        )
        for _fc in _fc_docs:
            _fc.reference.delete()
    except Exception:
        pass

    # ★ user_fc_reports 削除
    try:
        _fr_docs = list(
            db.collection("user_fc_reports").where("uid", "==", uid).stream()
        )
        for _fr in _fr_docs:
            _fr.reference.delete()
    except Exception:
        pass

    # ★ decision_metrics/{uid}/records サブコレクション削除
    try:
        _dm_recs = list(
            db.collection("decision_metrics").document(uid).collection("records").stream()
        )
        for _dm in _dm_recs:
            _dm.reference.delete()
        db.collection("decision_metrics").document(uid).delete()
    except Exception:
        pass

    # ★ weekly_reports 削除（フィールド名は target_uid）
    try:
        _wr_docs = list(
            db.collection("weekly_reports").where("target_uid", "==", uid).stream()
        )
        for _wr in _wr_docs:
            _wr.reference.delete()
    except Exception:
        pass

    delete_user(uid)

# -----------------------------
# Gemini models
# -----------------------------
@st.cache_resource
def list_models_cached(_api_key_present: bool):
    if not _api_key_present or client is None:
        return []
    names = []
    try:
        for m in client.models.list():
            n = getattr(m, "name", "") or ""
            if n:
                names.append(n.split("/")[-1])
    except Exception:
        return []
    return sorted(list(set(names)))

def list_available_models() -> List[str]:
    return list_models_cached(bool(api_key))

# ── モデル優先リスト（Flash = 作業層 / Pro = 判定層）──────────────────────
_FLASH_PREFERRED = [
    "gemini-2.5-flash",
    "gemini-2.0-flash-latest",
    "gemini-1.5-flash",
    "gemini-1.5-flash-latest",
]
_PRO_PREFERRED = [
    "gemini-2.0-pro",
    "gemini-2.0-pro-latest",
    "gemini-1.5-pro-latest",
    "gemini-1.5-pro",
]

def pick_model_candidates(use_pro: bool = False) -> List[str]:
    available = set(list_available_models())
    preferred = _PRO_PREFERRED if use_pro else _FLASH_PREFERRED
    if available:
        picked = [m for m in preferred if m in available]
        if picked:
            return picked
        # フォールバック: Pro要求でも Flash が残れば使う
        fallback = _FLASH_PREFERRED if use_pro else []
        for m in fallback:
            if m in available:
                return [m]
        any_match = [m for m in available if ("flash" in m or "pro" in m)]
        return sorted(any_match)[:2] if any_match else preferred
    return preferred

def _quota_hint_from_err(s: str) -> str:
    s_low = (s or "").lower()
    if "quota exceeded" in s_low or "resource_exhausted" in s_low or "429" in s_low:
        return (
            "原因: Gemini API のクォータ不足（free tier=0 / レート制限 / 請求未設定 等）。\n"
            "対処(最短):\n"
            "1) 使用している APIキーが「Google AI Studio（ai.google.dev）」発行の Gemini API キーか確認\n"
            "2) そのキーが紐づくプロジェクトで Gemini API のクォータが 0 になっていないか確認\n"
            "3) 0 の場合は、プロジェクト側で課金有効化（または別プロジェクト/別キーへ切替）が必要\n"
        )
    if "not found" in s_low or "404" in s_low:
        return "原因: 指定モデル名が利用不可（ListModelsに無い）。候補の選定/キー権限/リージョンを確認。"
    if "unavailable" in s_low or "503" in s_low:
        return "原因: 一時的高負荷（503）。再試行が有効。"
    return ""

def _call_llm_inner(
    prompt: str,
    history: list,
    sys: str,
    tenant_id: Optional[str],
    use_pro: bool = False,
    temperature: Optional[float] = None,
    file_parts: Optional[list] = None,  # ★ 画像/PDFのPart列
) -> str:
    """Flash / Pro 共通の内部実装。use_pro=True で Pro モデルを優先。"""
    if client is None:
        return "エラー: GEMINI_API_KEY が設定されていません。Cloud Run の Secret/環境変数(GEMINI_API_KEY)を確認してください。"

    _temperature = temperature if temperature is not None else 0.7
    if tenant_id and temperature is None:
        try:
            _temp_raw = (sys_col().document(tenant_id).get().to_dict() or {}).get("temperature")
            if _temp_raw is not None:
                _temperature = float(_temp_raw)
        except Exception:
            pass

    cfg = types.GenerateContentConfig(
        system_instruction=sys,
        max_output_tokens=8192,
        temperature=_temperature,
    )

    contents = []
    for h in (history or [])[-10:]:
        role = "user" if h.get("role") == "user" else "model"
        contents.append(types.Content(role=role, parts=[types.Part(text=h.get("content", ""))]))
    # ★ ファイルパーツ（画像/PDF）をユーザー発言に結合
    _user_parts = [types.Part(text=prompt)]
    if file_parts:
        _user_parts.extend(file_parts)
    contents.append(types.Content(role="user", parts=_user_parts))

    errs = {}
    candidates = pick_model_candidates(use_pro=use_pro)
    # ★ 確認ログ4: UI→API 点検 (3) APIに渡す直前の全パラメータをサーバーログに出力
    print(f"[API_SEND] tenant={tenant_id} model_candidates={candidates} "
          f"history_len={len(history or [])} file_parts={len(file_parts or [])} "
          f"prompt_head={repr(prompt[:200])}")
    for m in candidates:
        try:
            print(f"[API_CALL] model={m} contents_count={len(contents)}")
            res = client.models.generate_content(model=m, contents=contents, config=cfg)
            txt = getattr(res, "text", None)
            if txt:
                print(f"[API_OK] model={m} response_len={len(txt)}")
                return txt
        except Exception as e:
            errs[m] = str(e)

    avail = list_available_models()
    avail_hint = ", ".join(avail[:12]) + (" ..." if len(avail) > 12 else "")
    err_lines = "\n".join([f"- {k}: {v}" for k, v in list(errs.items())[:4]])
    hint = _quota_hint_from_err("\n".join(list(errs.values())[:2]))
    if hint:
        hint = "\n\n" + hint
    return (
        "AI接続失敗。\n"
        f"候補モデル: {candidates}\n"
        f"利用可能モデル(一部): {avail_hint if avail else '(ListModels取得失敗)'}\n"
        f"詳細エラー:\n{err_lines if err_lines else '(エラー情報なし)'}"
        f"{hint}"
    )

def call_llm(prompt: str, history=None, sys: Optional[str] = None, tenant_id: str = None,
             file_parts: Optional[list] = None) -> str:
    """Flash モデルで呼ぶ通常版（作業層: 返信生成/要約/クエリ整形/分類など）。"""
    if history is None:
        history = []
    if sys is None:
        sys = DEFAULT_SYSTEM_PROMPT
    # ★ 確認ログ3: UI→API 点検 (2) call_llmがpromptを受け取ったことを確認
    print(f"[CALL_LLM_RECV] tenant={tenant_id} prompt_len={len(prompt)} prompt_head={repr(prompt[:200])}")
    return _call_llm_inner(prompt, history, sys, tenant_id, use_pro=False, file_parts=file_parts)

# ── Image → Text（OCR/Caption/Tags）→ RAG登録用テキスト生成 ───────────────

def _image_mime_from_name(name: str) -> str:
    n = (name or "").lower().strip()
    if n.endswith(".png"):  return "image/png"
    if n.endswith(".gif"):  return "image/gif"
    if n.endswith(".webp"): return "image/webp"
    if n.endswith(".jpg") or n.endswith(".jpeg"): return "image/jpeg"
    # fallback
    return "image/jpeg"

def _image_ext_from_mime(m: str) -> str:
    m = (m or "").lower().strip()
    if "png" in m:  return "png"
    if "gif" in m:  return "gif"
    if "webp" in m: return "webp"
    return "jpg"

def _safe_parse_json_obj(text: str) -> dict:
    import json as _json
    if not text:
        return {}
    t = text.strip()
    try:
        return _json.loads(t)
    except Exception:
        pass
    # JSONっぽい塊だけ拾う（モデルが前後に余計な文字を出す保険）
    try:
        m = re.search(r"\{[\s\S]*\}", t)
        if m:
            return _json.loads(m.group(0))
    except Exception:
        pass
    return {}

def _normalize_tags(tags, limit: int = 12) -> list:
    if isinstance(tags, str):
        tags = [t.strip() for t in re.split(r"[,\n/]", tags) if t.strip()]
    if not isinstance(tags, list):
        tags = []
    out, seen = [], set()
    for t in tags:
        s = str(t).strip()
        if not s or s in seen:
            continue
        seen.add(s)
        out.append(s[:40])
        if len(out) >= int(limit):
            break
    return out

def _guess_mime_from_name(name: str) -> str:
    import mimetypes
    mt, _ = mimetypes.guess_type(name or "")
    return (mt or "application/octet-stream").strip()

def _gcs_image_path(sha256_hex: str, mime_type: str) -> str:
    ext = _image_ext_from_mime(mime_type)
    sh = (sha256_hex or "").strip().lower()
    p1 = sh[:2] if len(sh) >= 2 else "00"
    return f"central/images/{p1}/{sh}.{ext}"

def _gcs_attachment_path(sha256_hex: str, filename: str) -> str:
    sh = (sha256_hex or "").strip().lower()
    p1 = sh[:2] if len(sh) >= 2 else "00"
    ext = os.path.splitext(filename or "")[1].lower()
    if not re.fullmatch(r"\.[a-z0-9]{1,10}", ext or ""):
        ext = ".bin"
    return f"central/files/{p1}/{sh}{ext}"

def _image_analysis_col():
    fs_guard()
    return db.collection("source_image_analysis")

def _upsert_image_analysis_doc(
    source_id: str,
    sha256_hex: str,
    title: str,
    mime_type: str,
    category: str,
    analysis: dict,
    rag_text: str,
    first_saved_at,
    prev_version: int = 0,
    bump_version: bool = True,
) -> int:
    """画像解析結果を sources とは独立して永続化する（検索用テキストも同梱）。"""
    fs_guard()
    sid = (source_id or "").strip()
    if not sid:
        return int(prev_version or 0)

    ver = int(prev_version or 0)
    if bump_version:
        ver += 1
    if ver <= 0:
        ver = 1

    _image_analysis_col().document(sid).set(
        {
            "source_id": sid,
            "sha256": (sha256_hex or "").strip(),
            "title": (title or "").strip(),
            "image_mime": (mime_type or "").strip(),
            "category": (category or "").strip() or "general",
            "analysis": analysis or {},
            "text": rag_text or "",
            "first_saved_at": first_saved_at,
            "updated_at": firestore.SERVER_TIMESTAMP,
            "version": int(ver),
        },
        merge=True,
    )
    return int(ver)

def _extract_text_like_bytes(content_bytes: bytes, filename: str) -> str:
    name = (filename or "").lower().strip()

    if name.endswith((".odt", ".ods")):
        import zipfile
        import xml.etree.ElementTree as ET
        with zipfile.ZipFile(io.BytesIO(content_bytes)) as zf:
            tree = ET.fromstring(zf.read("content.xml"))
            txt = "".join(tree.itertext())
            return re.sub(r"\n{3,}", "\n\n", txt).strip()

    raw = ""
    for enc in ("utf-8-sig", "utf-8", "cp932", "shift_jis", "euc_jp", "latin-1"):
        try:
            raw = content_bytes.decode(enc)
            break
        except Exception:
            continue

    if name.endswith((".html", ".htm")):
        raw = re.sub(r"(?is)<(script|style).*?>.*?</\\1>", "\n", raw)
        raw = re.sub(r"(?s)<[^>]+>", "\n", raw)
        raw = re.sub(r"\n{3,}", "\n\n", raw).strip()

    return (raw or "").strip()

def _extract_pdf_text_and_meta(content_bytes: bytes, filename: str) -> dict:
    try:
        import PyPDF2
    except Exception as e:
        raise RuntimeError(f"PyPDF2未導入: {e}")

    reader = PyPDF2.PdfReader(io.BytesIO(content_bytes))
    page_count = len(reader.pages)
    texts = []
    for p in reader.pages:
        try:
            t = p.extract_text() or ""
        except Exception:
            t = ""
        if t and t.strip():
            texts.append(t.strip())

    raw_text = "\n\n".join(texts).strip()
    scan_like = len(raw_text) < 80

    return {
        "page_count": int(page_count),
        "raw_text": raw_text,
        "scan_like": bool(scan_like),
        "extract_method": "pypdf2_text",
    }

def _build_attachment_knowledge(
    filename: str,
    mime_type: str,
    source_type: str,
    raw_text: str,
    file_parts=None,
    extra_meta: dict = None,
) -> dict:
    raw_text = (raw_text or "").strip()
    text_preview = raw_text  # 全文をLLMに渡す（切り捨てなし）
    extra_meta = extra_meta or {}

    sys_doc = "あなたは添付ファイルを中央倉庫の検索資産へ変換するエンジンです。余計な文章は禁止。出力はJSONのみ。"
    prompt = (
        "次の添付ファイルを、RAG検索で再利用できる知識へ変換してください。\n"
        "必須キー: summary, content, ocr_text, tags, metadata\n"
        "- summary: 120字以内の日本語要約\n"
        "- content: 検索に強い自然文。『何の資料か』『主要論点』『何に使えるか』『固有名詞/OCR文字』を含めて3〜8文で記述\n"
        "- ocr_text: PDF等から読めた文字列。無ければ空文字\n"
        "- tags: 最大12個、短い日本語、重複なし\n"
        "- metadata: object。document_type, use_case, key_points(list) を含める\n"
        f"filename: {filename}\n"
        f"mime_type: {mime_type}\n"
        f"source_type: {source_type}\n"
        f"補助meta: {str(extra_meta)[:2000]}\n"
        f"抽出済み本文(あれば):\n{text_preview}"
    )

    out = call_llm(
        prompt,
        history=[],
        sys=sys_doc,
        file_parts=file_parts if file_parts else None,
    ) or ""
    obj = _safe_parse_json_obj(out)

    summary = str(obj.get("summary") or "").strip()
    content = str(obj.get("content") or "").strip()
    ocr_text = str(obj.get("ocr_text") or "").strip()
    tags = _normalize_tags(obj.get("tags") or [])
    metadata = obj.get("metadata") or {}
    if not isinstance(metadata, dict):
        metadata = {}

    if not summary:
        summary = f"{filename} の要約"
    summary = summary[:300]

    if not content:
        lead = text_preview[:2000].strip()
        content = (
            f"【添付資料】{filename}\n"
            f"このファイルは {source_type} 形式の資料です。"
            f"{lead if lead else '本文抽出は限定的でした。'}"
        ).strip()
    # content上限撤廃（全文保持）

    if not ocr_text and source_type == "pdf":
        ocr_text = text_preview[:4000]

    kp = metadata.get("key_points") or []
    if isinstance(kp, str):
        kp = [x.strip() for x in re.split(r"[,\n]", kp) if x.strip()]
    if not isinstance(kp, list):
        kp = []
    metadata["key_points"] = [str(x)[:120] for x in kp[:12]]

    return {
        "summary": summary,
        "content": content,
        "ocr_text": ocr_text[:8000],
        "tags": tags,
        "metadata": metadata,
    }

def _apply_source_tenant_link(source_id: str, tenant_id: str, category: str, source_type: str = "") -> bool:
    fs_guard()
    tid = (tenant_id or "").strip()
    sid = (source_id or "").strip()
    if not tid or not sid:
        return False

    link_id = tenant_source_link_doc_id(tid, sid)
    tenant_source_links_col().document(link_id).set(
        {
            "tenant_id": tid,
            "source_id": sid,
            "category": (category or "").strip() or "general",
            "source_type": (source_type or "").strip(),
            "enabled": True,
            "priority": 0,
            "visibility": "internal",
            "updated_at": firestore.SERVER_TIMESTAMP,
        },
        merge=True,
    )

    try:
        sdoc = sources_col().document(sid).get()
        sd = sdoc.to_dict() or {}
        tenant_links = list(sd.get("tenant_links") or [])
        if tid not in tenant_links:
            tenant_links.append(tid)
        sources_col().document(sid).set(
            {
                "tenant_links": tenant_links,
                "updated_at": firestore.SERVER_TIMESTAMP,
            },
            merge=True,
        )
    except Exception:
        pass
    return True

def _source_has_chunks(source_id: str) -> bool:
    try:
        return bool(_fs_stream_list(source_chunks_col().where("source_id", "==", source_id), limit=1))
    except Exception:
        return False

def _derive_final_category(base_category: str, case_theme: str, classifier_text: str) -> str:
    cat = (base_category or "").strip() or "auto"
    if cat == "auto":
        cat = classify_main_category_once(classifier_text or "")
    cat = (cat or "").strip() or "general"
    if cat == "auto":
        cat = "general"

    if cat == "case" and (case_theme or ""):
        th = str(case_theme)
        if th == "auto":
            th = classify_case_theme_once(classifier_text or "")
        if th and th != "auto":
            cat = f"case_{th}"
    return cat

def _analyze_image_bytes(image_bytes: bytes, mime_type: str, title_hint: str = "") -> dict:
    if not client:
        raise RuntimeError("Gemini client is not initialized")
    if not image_bytes:
        return {"caption": "", "ocr_text": "", "tags": []}

    sys_img = "あなたは画像解析エンジン。余計な文章は禁止。出力はJSONのみ。"
    prompt = (
        "次の画像を解析し、JSONのみで返してください。\n"
        "必須キー: caption, ocr_text, tags\n"
        "- caption: 1〜2文の日本語キャプション（簡潔）\n"
        "- ocr_text: 画像内の文字を可能な限り正確に抽出（無ければ空文字）\n"
        "- tags: 重要キーワード（最大12、短い日本語、重複なし）\n"
        f"補助情報(ファイル名): {title_hint}\n"
        "出力例: {\"caption\":\"...\",\"ocr_text\":\"...\",\"tags\":[\"...\",\"...\"]}"
    )

    fp = [types.Part(inline_data=types.Blob(data=image_bytes, mime_type=mime_type))]
    out = call_llm(prompt, history=[], sys=sys_img, file_parts=fp) or ""
    obj = _safe_parse_json_obj(out)

    caption = str(obj.get("caption") or "").strip()
    ocr_text = str(obj.get("ocr_text") or "").strip()
    tags = _normalize_tags(obj.get("tags") or [])

    if len(ocr_text) > 8000:
        ocr_text = ocr_text[:8000].rstrip()

    return {"caption": caption[:400], "ocr_text": ocr_text, "tags": tags}

def _compose_image_rag_text(title: str, analysis: dict) -> str:
    title = (title or "").strip()
    cap = str((analysis or {}).get("caption") or "").strip()
    ocr = str((analysis or {}).get("ocr_text") or "").strip()
    tags = _normalize_tags((analysis or {}).get("tags") or [])

    parts = []
    if title:
        parts.append(f"【画像】{title}")
    if cap:
        parts.append(f"キャプション: {cap}")
    if ocr:
        parts.append("OCR:\n" + ocr if len(ocr) >= 60 else "OCR(短): " + ocr)
    if tags:
        parts.append("タグ: " + " / ".join(tags))
    return "\n".join(parts).strip()

def _process_image_source_upload(
    name: str,
    content_bytes: bytes,
    cw_kb_category: str,
    cw_case_theme_files: str = "",
    tenant_id: str = "",
    source_context: str = "admin_central_upload",
) -> dict:
    fs_guard()

    if not _GCS_OK:
        return {"ok": False, "error": f"google-cloud-storage 未導入: {_GCS_IMPORT_ERR}"}
    if not CENTRAL_BLOB_BUCKET:
        return {"ok": False, "error": "環境変数 CENTRAL_BLOB_BUCKET が未設定です（画像保存不可）。"}
    if not content_bytes:
        return {"ok": False, "error": "画像バイトが空です。"}
    if len(content_bytes) > int(MAX_IMAGE_BYTES):
        return {"ok": False, "error": f"画像サイズ上限超過: {len(content_bytes)} bytes > {int(MAX_IMAGE_BYTES)} bytes"}

    mime = _image_mime_from_name(name)
    sha = hashlib.sha256(content_bytes).hexdigest()
    doc_id = "doc__" + sha[:24]
    gcs_path = _gcs_image_path(sha, mime)

    old = {}
    try:
        sdoc0 = sources_col().document(doc_id).get()
        old = (sdoc0.to_dict() or {}) if sdoc0.exists else {}
    except Exception:
        old = {}

    prev_ver = int(old.get("analysis_version", 0) or 0)
    first_saved_at = old.get("analysis_first_saved_at") or firestore.SERVER_TIMESTAMP
    prev_tenant_links = list(old.get("tenant_links") or [])

    try:
        last_started = old.get("analysis_started_at")
        if last_started and hasattr(last_started, "to_datetime"):
            last_started = last_started.to_datetime()
        if isinstance(last_started, datetime.datetime):
            if last_started.tzinfo is not None:
                last_started = last_started.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            diff = (_now_utc().replace(tzinfo=None) - last_started).total_seconds()
            if diff < float(IMAGE_REANALYZE_MIN_INTERVAL_SEC):
                return {"ok": False, "error": f"再解析が短時間に連打されています（{diff:.1f}s）。少し待ってください。"}
    except Exception:
        pass

    try:
        _gcs_put_bytes(CENTRAL_BLOB_BUCKET, gcs_path, content_bytes, content_type=mime)
    except Exception as e:
        return {"ok": False, "error": f"GCS upload failed: {e}"}

    sources_col().document(doc_id).set({
        "source_id": doc_id,
        "title": name,
        "original_filename": name,
        "mime_type": mime,
        "image_mime": mime,
        "storage_path": gcs_path,
        "gcs_bucket": CENTRAL_BLOB_BUCKET,
        "gcs_path": gcs_path,
        "source_type": "image",
        "sha256": sha,
        "size_bytes": int(len(content_bytes)),
        "content": f"[IMAGE:{name}]",
        "summary": str(old.get("summary") or ""),
        "ocr_text": str(old.get("ocr_text") or ""),
        "image_description": str(old.get("image_description") or ""),
        "tags": list(old.get("tags") or []),
        "metadata": {
            **(old.get("metadata") or {}),
            "file_kind": "attachment",
            "ingest_context": source_context,
        },
        "tenant_links": prev_tenant_links,
        "parse_status": "uploaded",
        "parse_error": "",
        "parse_version": int(ATTACHMENT_PARSE_VERSION),
        "status": "processing",
        "error_reason": "",
        "analysis_ref": (old.get("analysis_ref") or doc_id),
        "analysis_started_at": firestore.SERVER_TIMESTAMP,
        "created_at": old.get("created_at") or firestore.SERVER_TIMESTAMP,
        "updated_at": firestore.SERVER_TIMESTAMP,
    }, merge=True)

    sources_col().document(doc_id).set({
        "parse_status": "parsing",
        "parse_error": "",
        "status": "processing",
        "error_reason": "",
        "updated_at": firestore.SERVER_TIMESTAMP,
    }, merge=True)

    try:
        analysis = _analyze_image_bytes(content_bytes, mime, title_hint=name)
        rag_text = _compose_image_rag_text(name, analysis)
        cat = _derive_final_category(cw_kb_category, cw_case_theme_files, rag_text)

        old_text = str(old.get("text") or old.get("content") or "")
        old_cat  = str(old.get("category") or "")
        no_diff = (old.get("status") == "ready" and old_text.strip() == rag_text.strip() and old_cat.strip() == cat.strip())

        ver = _upsert_image_analysis_doc(
            source_id=doc_id,
            sha256_hex=sha,
            title=name,
            mime_type=mime,
            category=cat,
            analysis=analysis,
            rag_text=rag_text,
            first_saved_at=first_saved_at,
            prev_version=prev_ver,
            bump_version=(not no_diff),
        )

        sources_col().document(doc_id).set({
            "category": cat,
            "analysis": analysis,
            "text": rag_text,
            "content": rag_text,
            "summary": str(analysis.get("caption") or "")[:300],
            "ocr_text": str(analysis.get("ocr_text") or "")[:8000],
            "image_description": str(analysis.get("caption") or "")[:800],
            "tags": _normalize_tags(analysis.get("tags") or []),
            "analysis_ref": (old.get("analysis_ref") or doc_id),
            "analysis_version": int(ver or prev_ver or 0),
            "analysis_first_saved_at": first_saved_at,
            "parse_status": "parsed",
            "parse_error": "",
            "status": "processing",
            "error_reason": "",
            "analysis_completed_at": firestore.SERVER_TIMESTAMP,
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        if not no_diff:
            delete_chunks_for_doc("", doc_id)
            _central_rag = load_rag_settings(DEFAULT_TENANT)
            total_chunks = upsert_doc_chunks(
                tenant_id="",
                doc_id=doc_id,
                title=name,
                category=cat,
                source_type="image",
                content_text=rag_text,
                chunk_chars=int(_central_rag.get("chunk_chars", 1200)),
                overlap=int(_central_rag.get("chunk_overlap", 200)),
            )
            upsert_precompiled_summaries(
                tenant_id="",
                doc_id=doc_id,
                title=name,
                category=cat,
                source_ref=doc_id,
                text=rag_text,
            )
        else:
            total_chunks = 0

        linked_tenants = list(prev_tenant_links)
        if tenant_id:
            _apply_source_tenant_link(doc_id, tenant_id, cat, "image")
            link_precompiled_summaries_to_tenant(doc_id, tenant_id, cat)
            if tenant_id not in linked_tenants:
                linked_tenants.append(tenant_id)
            final_parse_status = "linked"
        else:
            final_parse_status = "embedded"

        sources_col().document(doc_id).set({
            "tenant_links": linked_tenants,
            "parse_status": final_parse_status,
            "parse_error": "",
            "status": "ready",
            "error_reason": "",
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        sdoc = sources_col().document(doc_id).get()
        sd = sdoc.to_dict() or {}
        return {
            "ok": True,
            "doc_id": doc_id,
            "category": cat,
            "chunks": int(total_chunks or 0),
            "summary": str(sd.get("summary") or ""),
            "content": str(sd.get("content") or ""),
            "parse_status": final_parse_status,
        }

    except Exception as e:
        err = str(e)[:600]
        sources_col().document(doc_id).set({
            "parse_status": "parse_failed",
            "parse_error": err,
            "status": "error",
            "error_reason": err,
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return {"ok": False, "doc_id": doc_id, "error": err}

def ingest_attachment_to_central_knowledge(
    name: str,
    content_bytes: bytes,
    tenant_id: str = "",
    category: str = "auto",
    case_theme: str = "",
    source_context: str = "chat_attachment",
) -> dict:
    fs_guard()

    name = (name or "unknown").strip()
    doc_id = ""
    source_type = _guess_source_type(filename=name)

    if source_type == "image":
        return _process_image_source_upload(
            name=name,
            content_bytes=content_bytes,
            cw_kb_category=category,
            cw_case_theme_files=case_theme,
            tenant_id=tenant_id,
            source_context=source_context,
        )

    if not content_bytes:
        return {"ok": False, "error": "ファイルバイトが空です。"}
    if len(content_bytes) > int(MAX_ATTACHMENT_BYTES):
        return {"ok": False, "error": f"ファイルサイズ上限超過: {len(content_bytes)} bytes > {int(MAX_ATTACHMENT_BYTES)} bytes"}

    mime_type = _guess_mime_from_name(name)
    sha = hashlib.sha256(content_bytes).hexdigest()
    doc_id = "doc__" + sha[:24]
    gcs_bucket = CENTRAL_FILE_BUCKET or CENTRAL_BLOB_BUCKET
    storage_path = _gcs_attachment_path(sha, name)
    _gcs_available = _GCS_OK and bool(gcs_bucket)
    _gcs_available = _GCS_OK and bool(gcs_bucket)

    old = {}
    try:
        sdoc0 = sources_col().document(doc_id).get()
        old = (sdoc0.to_dict() or {}) if sdoc0.exists else {}
    except Exception:
        old = {}

    prev_tenant_links = list(old.get("tenant_links") or [])

    try:
        sources_col().document(doc_id).set({
            "source_id": doc_id,
            "title": name,
            "original_filename": name,
            "mime_type": mime_type,
            "source_type": source_type,
            "sha256": sha,
            "size_bytes": int(len(content_bytes)),
            "storage_path": storage_path if _gcs_available else "",
            "gcs_bucket": gcs_bucket if _gcs_available else "",
            "gcs_path": storage_path if _gcs_available else "",
            "summary": str(old.get("summary") or ""),
            "content": str(old.get("content") or ""),
            "ocr_text": str(old.get("ocr_text") or ""),
            "image_description": "",
            "tags": list(old.get("tags") or []),
            "metadata": {
                **(old.get("metadata") or {}),
                "file_kind": "attachment",
                "ingest_context": source_context,
            },
            "tenant_links": prev_tenant_links,
            "parse_status": "uploaded",
            "parse_error": "",
            "parse_version": int(ATTACHMENT_PARSE_VERSION),
            "status": "processing",
            "error_reason": "",
            "created_at": old.get("created_at") or firestore.SERVER_TIMESTAMP,
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        if _gcs_available:
            _gcs_put_bytes(gcs_bucket, storage_path, content_bytes, content_type=mime_type)

        sources_col().document(doc_id).set({
            "parse_status": "parsing",
            "parse_error": "",
            "status": "processing",
            "error_reason": "",
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        if source_type == "pdf":
            pdf_meta = _extract_pdf_text_and_meta(content_bytes, name)
            raw_text = str(pdf_meta.get("raw_text") or "").strip()
            pdf_part = types.Part(
                inline_data=types.Blob(
                    mime_type="application/pdf",
                    data=base64.b64encode(content_bytes).decode("utf-8")
                )
            )
            knowledge = _build_attachment_knowledge(
                filename=name,
                mime_type=mime_type,
                source_type=source_type,
                raw_text=raw_text,
                file_parts=[pdf_part],
                extra_meta=pdf_meta,
            )
            meta = {
                **pdf_meta,
                **(knowledge.get("metadata") or {}),
                "file_kind": "attachment",
                "ingest_context": source_context,
                "raw_text_chars": int(len(raw_text)),
            }
            ocr_text = str(knowledge.get("ocr_text") or raw_text[:4000]).strip()
        else:
            raw_text = _extract_text_like_bytes(content_bytes, name)
            knowledge = _build_attachment_knowledge(
                filename=name,
                mime_type=mime_type,
                source_type=source_type,
                raw_text=raw_text,
                file_parts=None,
                extra_meta={},
            )
            meta = {
                **(knowledge.get("metadata") or {}),
                "file_kind": "attachment",
                "ingest_context": source_context,
                "raw_text_chars": int(len(raw_text)),
            }
            ocr_text = ""

        content = str(knowledge.get("content") or "").strip()
        summary = str(knowledge.get("summary") or "").strip()
        tags = _normalize_tags(knowledge.get("tags") or [])
        classifier_text = "\n".join([summary, content, raw_text[:3000]]).strip()
        cat = _derive_final_category(category, case_theme, classifier_text)

        if not content:
            raise RuntimeError("content生成に失敗しました")

        sources_col().document(doc_id).set({
            "category": cat,
            "summary": summary[:300],
            "content": content[:12000],
            "ocr_text": ocr_text[:8000],
            "image_description": "",
            "tags": tags,
            "metadata": meta,
            "parse_status": "parsed",
            "parse_error": "",
            "status": "processing",
            "error_reason": "",
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        delete_chunks_for_doc("", doc_id)
        _central_rag = load_rag_settings(DEFAULT_TENANT)
        total_chunks = upsert_doc_chunks(
            tenant_id="",
            doc_id=doc_id,
            title=name,
            category=cat,
            source_type=source_type,
            content_text=raw_text,  # 全文からchunk作成
            chunk_chars=int(_central_rag.get("chunk_chars", 1200)),
            overlap=int(_central_rag.get("chunk_overlap", 200)),
        )
        upsert_precompiled_summaries(
            tenant_id="",
            doc_id=doc_id,
            title=name,
            category=cat,
            source_ref=doc_id,
            text=raw_text,  # 全文からサマリー作成
        )
        st.info(f"✅ チャンク数: {total_chunks}件 / 全文文字数: {len(raw_text)}文字 / サマリー生成完了")

        linked_tenants = list(prev_tenant_links)
        if tenant_id:
            _apply_source_tenant_link(doc_id, tenant_id, cat, source_type)
            link_precompiled_summaries_to_tenant(doc_id, tenant_id, cat)
            if tenant_id not in linked_tenants:
                linked_tenants.append(tenant_id)
            final_parse_status = "linked"
        else:
            final_parse_status = "embedded"

        sources_col().document(doc_id).set({
            "tenant_links": linked_tenants,
            "parse_status": final_parse_status,
            "parse_error": "",
            "status": "ready",
            "error_reason": "",
            "updated_at": firestore.SERVER_TIMESTAMP,
        }, merge=True)

        return {
            "ok": True,
            "doc_id": doc_id,
            "category": cat,
            "summary": summary[:300],
            "content": content[:12000],
            "tags": tags,
            "chunks": int(total_chunks or 0),
            "parse_status": final_parse_status,
            "mime_type": mime_type,
            "source_type": source_type,
        }

    except Exception as e:
        err = str(e)[:600]
        if doc_id:
            try:
                sources_col().document(doc_id).set({
                    "parse_status": "parse_failed",
                    "parse_error": err,
                    "status": "error",
                    "error_reason": err,
                    "updated_at": firestore.SERVER_TIMESTAMP,
                }, merge=True)
            except Exception:
                pass
        return {"ok": False, "doc_id": doc_id, "error": err}

def _reanalyze_image_source(source_id: str) -> dict:
    fs_guard()
    sid = (source_id or "").strip()
    if not sid:
        return {"ok": False, "error": "source_id empty"}

    sdoc = sources_col().document(sid).get()
    if not sdoc.exists:
        return {"ok": False, "error": "source not found"}

    sd = sdoc.to_dict() or {}
    if (sd.get("source_type") or "") != "image":
        return {"ok": False, "error": "not image source"}

    bkt = (sd.get("gcs_bucket") or CENTRAL_BLOB_BUCKET or "").strip()
    path = (sd.get("gcs_path") or "").strip()
    title = sd.get("title") or sid
    if not bkt or not path:
        return {"ok": False, "error": "gcs_bucket/path missing"}

    img_bytes = _gcs_get_bytes(bkt, path)
    return _process_image_source_upload(
        name=title,
        content_bytes=img_bytes,
        cw_kb_category="auto",
        cw_case_theme_files="",
        tenant_id="",
        source_context="reparse_image",
    )
    
def call_llm_pro(prompt: str, history=None, sys: Optional[str] = None, tenant_id: str = None) -> str:
    """Pro モデルで呼ぶ判定層版（教師採用最終判定 / 構造更新 / 固定概念算出 / rerank最終判定）。"""
    if history is None:
        history = []
    if sys is None:
        sys = DEFAULT_SYSTEM_PROMPT
    # ★ 確認ログC: call_llm_pro が prompt を受け取ったことを確認（Pro経由API点検）
    print(f"[CALL_LLM_PRO_RECV] tenant={tenant_id} prompt_len={len(prompt)} prompt_head={repr(prompt[:200])}")
    return _call_llm_inner(prompt, history, sys, tenant_id, use_pro=True)

def call_llm_pro_or_flash(
    prompt: str,
    flash_result: str,
    confidence_check_fn,
    history=None,
    sys: Optional[str] = None,
    tenant_id: str = None,
) -> str:
    """
    例外ルール保険: Flash結果を confidence_check_fn で評価し、
    不確実/矛盾/低信頼なら Pro に再判定させる。
    confidence_check_fn(flash_result) → True: Flash採用 / False: Pro再判定
    """
    if confidence_check_fn(flash_result):
        return flash_result
    return call_llm_pro(prompt, history=history or [], sys=sys, tenant_id=tenant_id)

_IMAGE_MODEL_PREFERRED = [
    "gemini-3.1-flash-image-preview",
    "gemini-3-pro-image-preview",
    "gemini-2.5-flash-image",
]

def _is_spreadsheet_file(name: str = "", mime_type: str = "") -> bool:
    lower = (name or "").lower().strip()
    m = (mime_type or "").lower().strip()
    if lower.endswith((".xlsx", ".xls", ".ods", ".csv", ".tsv")):
        return True
    return (
        m in {
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "application/vnd.ms-excel",
            "application/vnd.oasis.opendocument.spreadsheet",
            "text/csv",
            "text/tab-separated-values",
        }
        or "spreadsheet" in m
        or "excel" in m
    )

def _extract_spreadsheet_inline_text(
    file_obj,
    max_sheets: int = 5,
    max_rows: int = 40,
    max_cols: int = 12,
    max_chars: int = 12000,
) -> str:
    name = getattr(file_obj, "name", "spreadsheet")
    mime_type = (getattr(file_obj, "type", "") or "").lower().strip()
    lower = name.lower()
    try:
        raw = file_obj.getvalue()
    except Exception:
        return ""
    if not raw:
        return ""

    frames = []
    try:
        if lower.endswith(".csv") or mime_type == "text/csv":
            frames = [("Sheet1", pd.read_csv(io.BytesIO(raw)))]
        elif lower.endswith(".tsv") or mime_type == "text/tab-separated-values":
            frames = [("Sheet1", pd.read_csv(io.BytesIO(raw), sep="\t"))]
        elif lower.endswith(".ods"):
            try:
                book = pd.read_excel(io.BytesIO(raw), sheet_name=None, engine="odf")
                frames = list((book or {}).items())[:max_sheets]
            except Exception:
                import zipfile
                import xml.etree.ElementTree as ET
                with zipfile.ZipFile(io.BytesIO(raw)) as zf:
                    tree = ET.fromstring(zf.read("content.xml"))
                txt = re.sub(r"\s+", " ", "".join(tree.itertext())).strip()
                if txt:
                    return f"【スプレッドシート添付: {name}】\n{txt[:max_chars]}" + ("\n...(truncated)" if len(txt) > max_chars else "")
                return ""
        else:
            book = pd.read_excel(io.BytesIO(raw), sheet_name=None)
            frames = list((book or {}).items())[:max_sheets]
    except Exception:
        return ""

    out = []
    for sheet_name, df in (frames or []):
        try:
            if df is None:
                continue
            _rows, _cols = df.shape
            _df = df.copy().iloc[:max_rows, :max_cols].fillna("")
            if hasattr(_df.columns, "tolist"):
                _df.columns = [re.sub(r"\s+", " ", str(c)).strip()[:60] for c in _df.columns.tolist()]
            for col in _df.columns:
                _df[col] = _df[col].astype(str).str.replace(r"\s+", " ", regex=True).str.slice(0, 120)
            out.append(
                f"【シート: {sheet_name} / rows={_rows} / cols={_cols}】\n{_df.to_csv(index=False)}"
            )
        except Exception:
            continue

    txt = "\n\n".join([x for x in out if x]).strip()
    if not txt:
        return ""
    if len(txt) > max_chars:
        txt = txt[:max_chars] + "\n...(truncated)"
    return f"【スプレッドシート添付: {name}】\n{txt}"

def _looks_like_image_generation_request(text: str, files: Optional[list] = None) -> bool:
    t = (text or "").strip().lower()
    if not t:
        return False

    image_words = [
        "画像", "イメージ", "イラスト", "写真", "ロゴ", "アイコン", "バナー",
        "ポスター", "サムネ", "図", "image", "illustration", "logo", "icon",
        "banner", "poster", "thumbnail",
    ]
    action_words = [
        "作って", "作成", "生成", "描いて", "描画", "出力", "デザイン",
        "作る", "つくる", "generate", "create", "draw", "design", "render",
    ]
    edit_words = [
        "編集", "加工", "修正", "変換", "背景", "切り抜", "色変更",
        "style transfer", "edit", "modify", "restyle",
    ]
    analysis_words = [
        "解析", "分析", "要約", "読んで", "説明", "pdf", "spreadsheet",
        "excel", "スプレッドシート",
    ]

    has_subject = any(w in t for w in image_words)
    has_action = any(w in t for w in action_words)
    has_edit = any(w in t for w in edit_words)
    has_analysis = any(w in t for w in analysis_words)

    if files and has_edit:
        return True
    if has_subject and has_action and not has_analysis:
        return True
    return False

def pick_image_model_candidates() -> List[str]:
    available = set(list_available_models())
    if available:
        picked = [m for m in _IMAGE_MODEL_PREFERRED if m in available]
        if picked:
            return picked
        fallback = [m for m in sorted(available) if ("gemini" in m and "image" in m)]
        if fallback:
            return fallback[:3]
    return list(_IMAGE_MODEL_PREFERRED)

def _response_parts_any(res) -> list:
    """レスポンスの全candidate × 全partを収集して返す（candidates[0]固定の取りこぼし防止）"""
    # res.parts が直接ある場合（一部APIバージョン）
    direct = getattr(res, "parts", None)
    if direct:
        return list(direct)
    # candidates を全件走査して parts を集約
    all_parts = []
    try:
        cands = getattr(res, "candidates", None) or []
        for cand in cands:
            content = getattr(cand, "content", None)
            if content is None:
                continue
            parts = getattr(content, "parts", None) or []
            all_parts.extend(list(parts))
    except Exception:
        pass
    return all_parts


def _build_strict_image_prompt(user_prompt: str) -> str:
    """
    画像生成専用。
    ユーザー指示を最優先で固定し、勝手な脚色・構図変更・要素追加を抑える。
    """
    up = (user_prompt or "").strip()
    return (
        "以下は画像生成の最終指示です。"
        "ユーザー指示を最優先し、勝手な解釈拡張・要素追加・世界観変更・構図変更を極力しないこと。\n"
        "明示された要素は必ず反映し、明示されていない要素は勝手に足さないこと。\n"
        "文字入れ指定が無ければ文字は入れないこと。\n"
        "複数対象が指定された場合は欠落させないこと。\n"
        "出力は画像生成のみを目的とし、説明文は不要。\n\n"
        f"【ユーザー最終指示】\n{up}"
    )

# ── 画像生成プロンプトキャッシュ（同一プロンプトは再生成しない）──
_IMAGE_CACHE: dict = {}
_IMAGE_CACHE_MAX = 30  # メモリ節約のため上限を設ける

def _image_cache_key(prompt: str, input_parts: Optional[list]) -> str:
    """プロンプト＋添付パーツのハッシュキーを生成"""
    raw = prompt or ""
    if input_parts:
        for p in input_parts:
            try:
                blob = getattr(p, "inline_data", None)
                if blob:
                    _d = getattr(blob, "data", b"") or b""
                    raw += hashlib.md5(_d[:512] if isinstance(_d, (bytes, bytearray)) else _d.encode()[:512]).hexdigest()
            except Exception:
                pass
    return hashlib.md5(raw.encode("utf-8", errors="replace")).hexdigest()

def generate_chat_images(
    prompt: str,
    history=None,
    input_parts: Optional[list] = None,
) -> Tuple[str, List[dict]]:
    if client is None:
        return (
            "エラー: GEMINI_API_KEY が設定されていません。Cloud Run の Secret/環境変数(GEMINI_API_KEY)を確認してください。",
            [],
        )

    # ── キャッシュヒット確認（同一プロンプトは再生成しない）──
    _cache_key = _image_cache_key(prompt, input_parts)
    if _cache_key in _IMAGE_CACHE:
        return ("画像を生成しました（キャッシュ）。", _IMAGE_CACHE[_cache_key])

    errs: dict = {}

    # 直近成功モデルを最優先（毎回の総当たりを減らして高速化）
    model_candidates = list(pick_image_model_candidates())
    last_good = st.session_state.get("_last_good_image_model")
    if last_good and last_good in model_candidates:
        model_candidates = [last_good] + [m for m in model_candidates if m != last_good]

    strict_prompt = _build_strict_image_prompt(prompt)
    user_parts = [types.Part(text=strict_prompt)]
    if input_parts:
        user_parts.extend(input_parts)
    contents = [types.Content(role="user", parts=user_parts)]

    # ["IMAGE"] のみだとモデルがテキスト部分を返せず image_not_returned になるケースがある。
    # ["TEXT", "IMAGE"] にすることでテキスト+画像の両方を受け取れるようにする。
    cfg = None
    try:
        cfg = types.GenerateContentConfig(
            response_modalities=["TEXT", "IMAGE"],
            temperature=0.2,
        )
    except Exception:
        try:
            cfg = types.GenerateContentConfig(response_modalities=["TEXT", "IMAGE"])
        except Exception:
            cfg = None

    for idx, m in enumerate(model_candidates):
        try:
            if cfg is not None:
                res = client.models.generate_content(model=m, contents=contents, config=cfg)
            else:
                res = client.models.generate_content(model=m, contents=contents)

            # ── デバッグログ：取りこぼし原因切り分け用 ──
            _all_parts   = _response_parts_any(res)
            _raw_cands   = getattr(res, "candidates", None) or []
            _img_count   = 0
            _txt_count   = 0
            for _p in _all_parts:
                _b = getattr(_p, "inline_data", None)
                if _b and (getattr(_b, "mime_type", "") or "").startswith("image/"):
                    _img_count += 1
                elif getattr(_p, "text", None):
                    _txt_count += 1
            print(
                f"[IMG_DEBUG] model={m} "
                f"candidates={len(_raw_cands)} "
                f"all_parts={len(_all_parts)} "
                f"image_parts={_img_count} "
                f"text_parts={_txt_count}"
            )

            generated_images: list = []
            text_parts: list = []

            # ── mime_typeのみを判定軸にしてpart全件を走査 ──
            for part in _all_parts:
                blob = getattr(part, "inline_data", None)

                # inline_data が無い → テキストpart
                if blob is None:
                    ptxt = getattr(part, "text", None)
                    if ptxt:
                        text_parts.append(str(ptxt))
                    continue

                # mime_type が image/ で始まるものだけ画像として扱う
                _mime = (getattr(blob, "mime_type", "") or "").strip()
                if not _mime.startswith("image/"):
                    continue

                # data の型ゆれを吸収（bytes / base64 str / その他）
                _data = getattr(blob, "data", None)
                if isinstance(_data, str):
                    try:
                        _data = base64.b64decode(_data)
                    except Exception:
                        _data = None
                elif isinstance(_data, (bytes, bytearray)):
                    _data = bytes(_data)
                else:
                    _data = None  # 不明な型は破棄

                if _data:
                    # Firestore 400 エラー防止のため、ここで base64 str に統一して返す
                    generated_images.append(
                        {
                            "mime_type": _mime or "image/png",
                            "data": base64.b64encode(_data).decode("utf-8"),
                        }
                    )

            if generated_images:
                st.session_state["_last_good_image_model"] = m
                # ── キャッシュ保存（上限を超えたら古いものを削除）──
                if len(_IMAGE_CACHE) >= _IMAGE_CACHE_MAX:
                    try:
                        _IMAGE_CACHE.pop(next(iter(_IMAGE_CACHE)))
                    except Exception:
                        pass
                _IMAGE_CACHE[_cache_key] = generated_images
                return ("画像を生成しました。", generated_images)

            # 画像なし：原因をログに残す
            if text_parts:
                errs[m] = f"image_not_returned (text_only): {str(text_parts[0])[:200]}"
            else:
                errs[m] = "image_not_returned"

        except Exception as e:
            errs[m] = str(e)

        # 高速化：先頭モデル失敗時だけ次へ
        if idx >= 1:
            break

    err_lines = "\n".join([f"* {k}: {v}" for k, v in list(errs.items())[:4]])
    return (
        "画像生成に失敗しました。\n"
        f"候補モデル: {model_candidates[:2]}\n"
        f"詳細エラー:\n{err_lines if err_lines else '(エラー情報なし)'}"
    ), []

@st.cache_data(ttl=3600, show_spinner=False)
def classify_main_category_once(text: str) -> str:
    """テキスト全量を解析し、大カテゴリ（policy/script/pricing/faq/case）を自動判定する。
    ※caseのサブ分類（success/fail/objection/price/trust/other）は別関数 classify_case_theme_once に任せる。
    ※ソース保存は変更しない。カテゴリ判定に使う抜粋文字数だけをサイズで可変にする。
    """
    VALID = ["policy", "script", "pricing", "faq", "case"]

    if not text or not text.strip():
        return "policy"

    n = len(text)

    # ------------------------------------------------------------
    # ★カテゴリ判定に使う文字数だけ可変（大規模ほど投入を抑え、誤判定を減らす）
    # ------------------------------------------------------------
    # total = LLMに渡す抜粋総量（頭打ち）
    if n >= 1_000_000:
        total = 2600
    elif n >= 500_000:
        total = 3000
    elif n >= 200_000:
        total = 3600
    elif n >= 80_000:
        total = 4200
    elif n >= 30_000:
        total = 4800
    else:
        total = 5500

    head_len = int(total * 0.50)
    mid_len  = int(total * 0.35)
    tail_len = total - head_len - mid_len

    head = text[:head_len]

    mid_center = n // 2
    mid_start = max(0, mid_center - (mid_len // 2))
    mid = text[mid_start:mid_start + mid_len]

    tail = text[-tail_len:] if n > (head_len + mid_len + tail_len) else ""

    snippet = "\n---\n".join(filter(None, [head, mid, tail]))

    prompt = f"""以下のテキスト内容（抜粋）を分析し、最も適したカテゴリを1つだけ選んでください。
出力は指定のカテゴリ名（英小文字）のみ。説明・記号は禁止。

【選択肢（この5つ以外は禁止）】
policy
script
pricing
faq
case

【テキスト抜粋】
{snippet}
"""

    try:
        res = call_llm(prompt, history=[], sys="カテゴリ名のみを英小文字で出力せよ。")
        res_clean = (res or "").strip().lower()

        # 完全一致を最優先
        if res_clean in VALID:
            return res_clean

        # 1語だけ混ざったケースを救済（複数ヒットは不採用）
        hits = [c for c in VALID if c in res_clean]
        if len(hits) == 1:
            return hits[0]

        return "policy"
    except Exception:
        return "policy"
    
def classify_case_theme_once(content: str) -> str:
    """
    case のテーマを1回だけ判別（保存時用）。
    戻り値は success/fail/objection/price/trust/other のいずれか。
    """
    txt = (content or "").strip()
    if not txt:
        return "other"
    snippet = txt[:4000]
    prompt = (
        "以下の文章はコンサル用の『事例（case）』です。"
        "次のラベルのうち最も適切なものを1語だけで返してください。\n"
        "labels: success, fail, objection, price, trust, other\n\n"
        f"TEXT:\n{snippet}\n\n"
        "出力はラベル1語のみ。余計な説明は禁止。"
    )
    out = call_llm(prompt, history=[], sys="")  # 分類だけ。指示は最小。
    lab = (out or "").strip().lower()
    for k in ("success", "fail", "objection", "price", "trust", "other"):
        if k in lab:
            return k
    return "other"

def generate_faq_knowledge(
    tenant_id: str,
    top_n_topics: int = 5,
    log_limit: int = 3000,
    faq_category: str = "faq",
) -> dict:
    """
    usage_logs の prompt を分析し、頻出トピックから FAQ ナレッジを自動生成して保存する。

    フロー:
      1. tenant の usage_logs を取得
      2. LLM で上位 N トピックをクラスタリング（プロンプト一覧を渡してまとめてもらう）
      3. トピックごとに LLM で Q&A（FAQ本文）を生成
      4. sources / tenant_source_links / source_chunks に保存
    戻り値: {ok, topics_found, saved, errors, topic_titles}
    """
    if not client:
        return {"ok": False, "reason": "LLMクライアント未初期化（GEMINI_API_KEY未設定）"}

    tenant_id = tenant_id or DEFAULT_TENANT
    top_n_topics = max(1, min(10, int(top_n_topics or 5)))
    rag_cfg = load_rag_settings(tenant_id)
    chunk_chars = int(rag_cfg.get("chunk_chars", 1200))
    chunk_overlap = int(rag_cfg.get("chunk_overlap", 200))

    # ① usage_logs からプロンプト一覧を取得
    df_logs = load_usage_logs_for_tenant(tenant_id, limit=log_limit)
    if df_logs is None or df_logs.empty or "prompt" not in df_logs.columns:
        return {"ok": False, "reason": "ログが0件です。"}

    prompts = (
        df_logs["prompt"]
        .dropna()
        .astype(str)
        .str.strip()
        .loc[lambda s: s.str.len() > 5]
        .tolist()
    )
    if not prompts:
        return {"ok": False, "reason": "有効なプロンプトが0件です。"}

    # 多すぎる場合はランダムサンプリング（LLMのコンテキスト制限）
    import random
    sample_size = min(len(prompts), 300)
    sample = random.sample(prompts, sample_size) if len(prompts) > sample_size else prompts
    prompts_text = "\n".join([f"- {p[:120]}" for p in sample])

    # ② LLM でトピッククラスタリング
    cluster_sys = (
        "あなたは優秀なトピック分析器。余計な前置き・後書き禁止。"
        "出力はJSONのみ。```json などのコードブロック記法も禁止。"
    )
    cluster_prompt = (
        f"以下は、コンサルティングAIへの質問一覧です（業種: {tenant_id}）。\n"
        f"これらを分析し、最も頻出・重要な上位{top_n_topics}トピックを特定してください。\n\n"
        "出力形式（JSONのみ）:\n"
        "[\n"
        "  {\"topic\": \"トピック名（20文字以内）\", \"summary\": \"このトピックの典型的な質問パターン（50文字以内）\", \"keywords\": [\"キーワード1\", \"キーワード2\"]},\n"
        "  ...\n"
        "]\n\n"
        f"質問一覧:\n{prompts_text}"
    )

    try:
        cluster_out = call_llm(cluster_prompt, history=[], sys=cluster_sys).strip()
        import json, re as _re
        m = _re.search(r"\[.*\]", cluster_out, flags=_re.DOTALL)
        topics = json.loads(m.group(0) if m else cluster_out)
        if not isinstance(topics, list):
            raise ValueError("list expected")
        topics = topics[:top_n_topics]
    except Exception as e:

        _raw = locals().get("cluster_out", "")
        return {"ok": False, "reason": f"トピック抽出失敗: {e}", "raw": _raw}

    # ③ トピックごとに FAQ 生成 → 保存
    faq_sys = (
        "あなたは戦略コンサルタントAI「ASCEND」のナレッジ作成者。"
        "与えられたトピックに関して、実務で役立つFAQを作成せよ。"
        "回答は具体的・断定的に。慰め・抽象論禁止。"
    )
    saved = 0
    errors = 0
    topic_titles = []

    for t in topics:
        topic_name = (t.get("topic") or "").strip()
        topic_summary = (t.get("summary") or "").strip()
        keywords = t.get("keywords") or []
        if not topic_name:
            continue

        faq_prompt = (
            f"業種: {tenant_id}\n"
            f"トピック: {topic_name}\n"
            f"典型的な質問パターン: {topic_summary}\n"
            f"関連キーワード: {', '.join(keywords)}\n\n"
            "上記トピックについて、以下の構成で実務的なFAQナレッジを作成せよ。\n"
            "【よくある質問（Q）】\n"
            "  Q1: （具体的な質問）\n"
            "  A1: （明確な回答：結論→根拠→打ち手→注意点）\n"
            "  Q2: ...\n"
            "  A2: ...\n"
            "  （3〜5問）\n\n"
            "【このトピックの核心】\n"
            "  （なぜこれが重要か・失敗パターン・成功条件）\n\n"
            "【即時アクション】\n"
            "  （明日からできる具体的行動3つ）"
        )

        try:
            faq_content = call_llm(faq_prompt, history=[], sys=faq_sys).strip()
        except Exception as e:
            errors += 1
            continue

        if not faq_content or len(faq_content) < 100:
            errors += 1
            continue

        # ★ 中央化：doc_idは「タイトル＋本文」由来（テナント非依存＝実質の重複排除）
        import hashlib as _hl
        raw = f"{(topic_name or '').strip()}::{(faq_content or '').strip()}".encode("utf-8")
        doc_id = "doc__" + _hl.sha256(raw).hexdigest()[:24]

        title = f"【FAQ自動生成】{topic_name}"

        try:
            # A. sources に保存
            sources_col().document(doc_id).set(
                {
                    "source_id": doc_id,
                    "title": title,
                    "content": faq_content,
                    "source_type": "faq",
                    "category": faq_category,
                    "created_at": firestore.SERVER_TIMESTAMP,
                    "updated_at": firestore.SERVER_TIMESTAMP,
                },
                merge=True,
            )

            # B. tenant_source_links に保存
            link_id = tenant_source_link_doc_id(tenant_id, doc_id)
            tenant_source_links_col().document(link_id).set(
                {
                    "tenant_id": tenant_id,
                    "source_id": doc_id,
                    "category": faq_category,
                    "enabled": True,
                    "updated_at": firestore.SERVER_TIMESTAMP,
                },
                merge=True,
            )

            # C. ベクトルチャンク生成・保存
            upsert_doc_chunks(
                tenant_id=tenant_id,
                doc_id=doc_id,
                title=title,
                category=faq_category,
                source_type="faq",
                content_text=faq_content,
                chunk_chars=chunk_chars,
                overlap=chunk_overlap,
            )

            saved += 1
            topic_titles.append(topic_name)

        except Exception as e:
            errors += 1

    return {
        "ok": True,
        "topics_found": len(topics),
        "saved": saved,
        "errors": errors,
        "topic_titles": topic_titles,
    }


def make_report_prompt(context_str: str) -> str:
    return f"""
以下は、あるユーザー（または組織）のチャットログ、行動履歴、およびナレッジの抜粋です。
これらを分析し、以下の5つの観点で「戦略レポート」を作成してください。

【観点】
A. 現状の課題とボトルネック（何に詰まっているか）
B. ユーザーの思考パターン・バイアス（判断の癖）
C. 潜在的な機会とリスク（見落としている可能性）
D. 推奨される次のアクション（具体的かつ優先度順）
E. コンサルタントとしての総評（辛口でよい）

【制約】
- 抽象的な表現は避け、ログにある具体的な事実を引用して根拠とすること。
- 箇条書きを多用し、可読性を高めること。
- 感情的な慰めは不要。冷徹な分析を求める。

【情報ソース】
{context_str}
"""
# -----------------------------
# Weekly Reports（週次レポート蓄積）
# -----------------------------

def _weekly_reports_col():
    fs_guard()
    return db.collection("weekly_reports")

def save_weekly_report(
    tenant_id: str,
    target_uid: str,
    report_md: str,
    week_label: str,
    report_type: str = "manual",
) -> Optional[str]:
    """
    生成したレポートを weekly_reports コレクションに保存。
    week_label: "2025-W03" 形式（手動生成時は "manual_<日時>" も可）
    report_type: "manual" | "weekly"
    戻り値: doc_id（失敗時None）
    """
    fs_guard()
    try:
        doc_ref = _weekly_reports_col().document()
        doc_ref.set({
            "tenant_id": tenant_id,
            "target_uid": target_uid,
            "report_md": report_md,
            "week_label": week_label,
            "report_type": report_type,
            "created_at": firestore.SERVER_TIMESTAMP,
        })
        return doc_ref.id
    except Exception as _e:
        print(f"[save_weekly_report ERROR] {_e}")
        return None

def load_weekly_reports(
    tenant_id: str,
    target_uid: str = "",
    limit: int = 20,
) -> list:
    """
    weekly_reports を新しい順で返す。
    target_uid が空の場合はテナント全体を返す。
    """
    fs_guard()
    try:
        q = _weekly_reports_col().where("tenant_id", "==", tenant_id)
        if target_uid:
            q = q.where("target_uid", "==", target_uid)
        docs = list(q.limit(limit).stream())
        result = [{'doc_id': d.id, **(d.to_dict() or {})} for d in docs]
        result.sort(key=lambda x: x.get('created_at') or '', reverse=True)
        return result
    except Exception as _e:
        print(f"[load_weekly_reports ERROR] {_e}")
        return []

def build_weekly_context(
    tenant_id: str,
    target_uid: str,
    week_start: "datetime.datetime",
    week_end: "datetime.datetime",
    chat_limit: int = 200,
) -> str:
    """
    指定週のログ・チャット履歴をテキストに変換してレポート用コンテキストを返す。
    """
    fs_guard()
    parts = []

    # usage_logs を期間フィルタ
    try:
        q = (
            db.collection("usage_logs")
            .where("tenant_id", "==", tenant_id)
            .where("user_id", "==", target_uid)
            .where("is_admin_test", "==", False)
            .order_by("timestamp", direction=firestore.Query.DESCENDING)
            .limit(500)
        )
        docs = list(q.stream())
        rows = []
        for d in docs:
            x = d.to_dict() or {}
            ts = x.get("timestamp")
            if ts:
                try:
                    dt = ts if isinstance(ts, datetime.datetime) else datetime.datetime.fromisoformat(str(ts))
                    # aware→JST naive に正規化してから比較（week_start/week_end は JST naive）
                    if dt.tzinfo is not None:
                        import datetime as _dtmod
                        dt = dt.astimezone(_dtmod.timezone(_dtmod.timedelta(hours=9))).replace(tzinfo=None)
                    if not (week_start <= dt <= week_end):
                        continue
                except Exception:
                    pass
            p = str(x.get("prompt", "")).strip()
            a = str(x.get("response", "")).strip()
            ts_str = str(ts)[:16] if ts else ""
            if p:
                rows.append(f"[{ts_str}] Q: {p}\nA: {a}" if a else f"[{ts_str}] {p}")
        if rows:
            parts.append("【週間 usage_logs】\n" + "\n\n".join(rows))
    except Exception:
        pass

    # チャット履歴（期間フィルタなし・limit で代用）
    try:
        msgs = load_chat_messages("user", tenant_id, target_uid, limit=chat_limit)
        if msgs:
            lines = [f"{m['role']}: {m.get('content','')}" for m in msgs if m.get("content")]
            parts.append("【チャット履歴】\n" + "\n".join(lines))
    except Exception:
        pass

    return "\n\n".join(parts) if parts else ""


def generate_query_plan(user_prompt: str, tenant_id: str, level: str) -> dict:
    """入力から最適な検索・要約計画(Query Plan)をJSONで生成する層"""
    if not client: return {}
    sys_prompt = "あなたは優秀な検索プランナー。ユーザーの入力から最適な検索・要約計画をJSONで出力せよ。余計なテキストは出力せず、JSONのみを出力すること。"
    schema = """
{
  "intent": "相談/意思決定/分析/要約/作成",
  "domain": "業種ID",
  "why": "なぜ今それを聞くのか（1行）",
  "success_criteria": ["成功条件1"],
  "constraints": {
    "time_range": "今月/直近30日/指定",
    "scope": "対象",
    "must_not": ["NG1"]
  },
  "retrieval": {
    "categories": {"logs": 10, "rules": 6, "knowledge": 8, "chat": 6, "investment": 0},
    "top_k_total": 30,
    "recency_bias": "high/med/low",
    "dedupe": true
  },
  "summary_lens": {
    "preset": "expert",
    "weights": {"A": 0.4, "B": 0.3, "C": 0.3},
    "chars": 900
  },
  "output_style": {
    "format": "結論→根拠→打ち手→KPI",
    "tone": "断定"
  }
}
【カテゴリ補足】
- "investment": 株式・投資シグナル（GOAL_BOTTOM/WATCH_BIG_SELL）に関する質問は必ず investment>=8 を指定すること
- 銘柄コード・株価・底打ち・売り込み・反発に関するキーワードが含まれる場合も investment>=8
"""
    prompt = f"【業種】{tenant_id}\n【相談者の格】{level}\n【入力】{user_prompt}\n\n上記の入力に基づき、以下のJSONスキーマに従って検索計画を生成せよ:\n{schema}"
    
    try:
        # ── 構造更新・Query Plan 生成 → Pro（検索計画の精度が全RAG品質を支配する）
        out = call_llm_pro(prompt, history=[], sys=sys_prompt).strip()
        import re
        m = re.search(r"\{.*\}", out, flags=re.DOTALL)
        j_str = m.group(0) if m else out
        import json
        plan = json.loads(j_str)
        # 例外ルール: 必須フィールド欠落 → Flash で再試行（保険）
        if not plan.get("retrieval") or not plan.get("intent"):
            out2 = call_llm(prompt, history=[], sys=sys_prompt).strip()
            m2 = re.search(r"\{.*\}", out2, flags=re.DOTALL)
            plan2 = json.loads(m2.group(0) if m2 else out2)
            if plan2.get("retrieval"):
                return plan2
        return plan
    except Exception:
        return {}

# ============================================================
# TABLECHAT Phase1 - 表判定・変換・セッション保持・表示
# 既存 RAG / rerank / teacher / trainer には一切触れない独立実装
# ============================================================

def _tc_is_markdown_table(lines):
    """Markdown テーブル判定"""
    pipe_lines = [l for l in lines if "|" in l]
    if len(pipe_lines) < 2:
        return False
    sep_lines = [l for l in pipe_lines if re.match(r"^\|[\s\-:|]+\|", l.strip())]
    if sep_lines:
        return True
    return len(pipe_lines) >= 3 and all(l.strip().startswith("|") for l in pipe_lines)

def _tc_is_csv_like(lines, delim, min_cols=2):
    """全行が同じ列数（delim で分割）なら True"""
    if len(lines) < 2:
        return False
    counts = [l.count(delim) for l in lines if l.strip()]
    if not counts:
        return False
    modal = max(set(counts), key=counts.count)
    if modal < min_cols - 1:
        return False
    return sum(1 for c in counts if c == modal) / len(counts) >= 0.8

def _tc_is_space_aligned(lines, min_cols=2):
    """複数スペース区切り固定幅テーブル判定"""
    if len(lines) < 2:
        return False
    splitted = [re.split(r"  +|\t", l.strip()) for l in lines if l.strip()]
    col_counts = [len(s) for s in splitted]
    if not col_counts:
        return False
    modal = max(set(col_counts), key=col_counts.count)
    return modal >= min_cols and sum(1 for c in col_counts if c == modal) / len(col_counts) >= 0.75

def tc_is_table_input(text):
    """
    入力テキストが表形式かどうかを判定する。
    Returns: (is_table: bool, detected_format: str)
    detected_format: "markdown" | "csv" | "tsv" | "space" | "none"
    """
    if not text or not text.strip():
        return False, "none"
    lines = [l for l in text.strip().splitlines() if l.strip()]
    if len(lines) < 2:
        return False, "none"
    if _tc_is_markdown_table(lines):
        return True, "markdown"
    if _tc_is_csv_like(lines, "\t"):
        return True, "tsv"
    if _tc_is_csv_like(lines, ","):
        counts = [l.count(",") for l in lines if l.strip()]
        modal = max(set(counts), key=counts.count)
        if modal >= 1 and (len(lines) >= 3 or modal >= 3):
            return True, "csv"
    if _tc_is_space_aligned(lines):
        return True, "space"
    return False, "none"

def tc_parse_table(text, fmt="auto"):
    """テキストを DataFrame に変換。失敗時は None を返す"""
    import io as _io
    if not text or not text.strip():
        return None
    if fmt == "auto":
        detected, fmt = tc_is_table_input(text)
        if not detected:
            return None
    lines = [l for l in text.strip().splitlines() if l.strip()]
    try:
        if fmt == "markdown":
            rows = []
            for line in lines:
                line = line.strip().strip("|")
                cells = [c.strip() for c in line.split("|")]
                if all(re.match(r"^[-:=\s]+$", c) for c in cells if c):
                    continue
                rows.append(cells)
            if not rows:
                return None
            max_cols = max(len(r) for r in rows)
            padded = [r + [""] * (max_cols - len(r)) for r in rows]
            header = padded[0]
            data   = padded[1:]
            for i, h in enumerate(header):
                if not h:
                    header[i] = f"col_{i}"
            return pd.DataFrame(data, columns=header)
        elif fmt == "tsv":
            return pd.read_csv(_io.StringIO(text.strip()), sep="\t")
        elif fmt == "csv":
            return pd.read_csv(_io.StringIO(text.strip()))
        elif fmt == "space":
            split_lines = [re.split(r"  +|\t", l.strip()) for l in lines if l.strip()]
            max_cols = max(len(r) for r in split_lines)
            padded = [r + [""] * (max_cols - len(r)) for r in split_lines]
            header = padded[0]
            data   = padded[1:]
            for i, h in enumerate(header):
                if not h:
                    header[i] = f"col_{i}"
            return pd.DataFrame(data, columns=header)
    except Exception:
        pass
    for sep in ["\t", ",", r"\s+"]:
        try:
            df_try = pd.read_csv(_io.StringIO(text.strip()), sep=sep, engine="python")
            if df_try.shape[1] >= 2:
                return df_try
        except Exception:
            continue
    return None

def tc_set_session_table(uid, df, raw_text="", fmt=""):
    """
    セッションに表データを保存する。
    KBソース化・教師化・Trainer対象化は行わない。
    """
    import datetime as _dt
    st.session_state["_tc_df"]        = df
    st.session_state["_tc_raw_text"]  = raw_text
    st.session_state["_tc_fmt"]       = fmt
    st.session_state["_tc_timestamp"] = _dt.datetime.utcnow().isoformat()
    st.session_state["_tc_uid"]       = uid

def tc_get_session_table(uid=""):
    """セッションから表データを取得。なければ None"""
    df = st.session_state.get("_tc_df")
    if df is None or not isinstance(df, pd.DataFrame):
        return None
    if uid:
        stored_uid = st.session_state.get("_tc_uid", "")
        if stored_uid and stored_uid != uid:
            return None
    return df

def tc_has_session_table(uid=""):
    """セッションに有効な表データがあるか"""
    return tc_get_session_table(uid) is not None

def tc_clear_session_table():
    """表データをセッションから削除する"""
    for key in ["_tc_df", "_tc_raw_text", "_tc_fmt", "_tc_timestamp", "_tc_uid"]:
        st.session_state.pop(key, None)

def tc_render_summary(df):
    """DataFrame の基本情報を自然文で返す"""
    if df is None or df.empty:
        return "表データが空です。"
    rows, cols = df.shape
    col_names = "、".join(str(c) for c in df.columns[:10])
    if len(df.columns) > 10:
        col_names += f" など（全{cols}列）"
    numeric_cols = df.select_dtypes(include="number").columns.tolist()
    numeric_info = ""
    if numeric_cols:
        parts = []
        for c in numeric_cols[:5]:
            try:
                parts.append(f"{c}（合計: {df[c].sum():,.2f} / 平均: {df[c].mean():,.2f}）")
            except Exception:
                continue
        if parts:
            numeric_info = "\n\n数値列サマリー:\n" + "\n".join(f"- {s}" for s in parts)
    return (
        f"✅ **表を受け取りました**\n\n"
        f"- 行数: **{rows}行** / 列数: **{cols}列**\n"
        f"- 列名: {col_names}"
        f"{numeric_info}\n\n"
        f"この表に対して集計・フィルタ・分析などの操作が可能です。"
    )

def _df_to_markdown_table(df: pd.DataFrame, max_rows: int = 60) -> str:
    """DataFrameをMarkdown表形式に変換する（tabulate不要）。
    render_smart_content がMarkdown表を検出してst.dataframeで再描画できるようにする。
    """
    try:
        _df = df.head(max_rows)
        headers = [str(c) for c in _df.columns]
        sep = [":---"] * len(headers)
        lines = []
        lines.append("| " + " | ".join(headers) + " |")
        lines.append("| " + " | ".join(sep) + " |")
        for _, row in _df.iterrows():
            cells = [str(v) if v is not None else "" for v in row]
            lines.append("| " + " | ".join(cells) + " |")
        return "\n".join(lines)
    except Exception:
        return ""

def _tc_try_numeric(value):
    """文字列を数値に変換できれば変換、できなければ元の値を返す"""
    if isinstance(value, (int, float)):
        return value
    try:
        v = str(value).strip().replace(",", "")
        if "." in v:
            return float(v)
        return int(v)
    except (ValueError, TypeError):
        return value

def tablechat_phase1_route(text, uid, tenant_id):
    """
    Phase1 メインルーター。
    Returns:
        True  → 表チャットが処理を完了（ASCEND 通常パイプライン不要）
        False → 表でない or エラー → ASCEND 通常チャットへ fallback
    """
    try:
        # Step1: 表判定
        detected, fmt = tc_is_table_input(text)
        if not detected:
            return False

        # Step2: DataFrame 変換
        df = tc_parse_table(text, fmt=fmt)
        if df is None or df.empty:
            return False

        # 型推定: 数値に変換できる列は数値化
        for col in df.columns:
            try:
                df[col] = df[col].apply(_tc_try_numeric)
            except Exception:
                pass

        # Step3: セッション保持（KB・Trainer対象外）
        tc_set_session_table(uid, df, raw_text=text, fmt=fmt)

        # Step4: ユーザー入力を表示
        with st.chat_message("user"):
            st.markdown(
                f"📊 **表データを入力しました**（{len(df)}行 × {len(df.columns)}列 / フォーマット: `{fmt}`）"
            )
            with st.expander("入力テキストを確認", expanded=False):
                st.code(text[:2000], language="")

        # Step5: 解析結果を表示（要約 + 表）
        summary = tc_render_summary(df)
        with st.chat_message("assistant"):
            st.markdown(summary)
            st.dataframe(df, use_container_width=True, hide_index=True)

        return True  # 処理完了 → ASCEND パイプラインをスキップ

    except Exception as _e:
        try:
            import os as _os
            if _os.environ.get("TABLECHAT_DEBUG", "").lower() in ("1", "true"):
                st.warning(f"[TableChat] fallback: {_e}")
        except Exception:
            pass
        return False


# ============================================================
# TABLECHAT Phase2 - コマンドルーター・計算・フィルタ・派生・コンサル
# ============================================================

# ── 2-1. コマンドルーター ──────────────────────────────────────────
def tc_command_router(text: str, uid: str, tenant_id: str) -> bool:
    """
    保持済み表に対するコマンドを解釈して実行する。
    Returns: True → 処理完了 / False → 通常パイプへ
    コマンド一覧:
        /sum   <列名>
        /avg   <列名>
        /median <列名>
        /min   <列名>
        /max   <列名>
        /rank  <列名> [asc|desc]
        /diff  <列名>
        /growth <列名>
        /filter <列名> <演算子> <値>   例: /filter 売上 >= 100
        /sort   <列名> [asc|desc]
        /select <列1,列2,...>
        /top    <N> <列名>
        /derive <新列名>=<式>           例: /derive 客単価=売上/客数
        /consult                       異常検知・比較・提案
        /reset                         表セッションクリア
        /show                          現在の表を再表示
    """
    if not text or not text.strip().startswith("/"):
        return False
    df = tc_get_session_table(uid)
    if df is None:
        return False

    raw = text.strip()
    cmd_line = raw.lstrip("/")
    parts = cmd_line.split(None, 1)
    cmd = parts[0].lower()
    args = parts[1].strip() if len(parts) > 1 else ""

    # /reset
    if cmd == "reset":
        tc_clear_session_table()
        _tc_router_reply(uid, raw, "🗑️ 表セッションをリセットしました。")
        return True

    # /show
    if cmd == "show":
        _tc_router_reply(uid, raw, tc_render_summary(df), df=df)
        return True

    # /consult
    if cmd == "consult":
        result = tc_consult_analysis(df)
        _tc_router_reply(uid, raw, result)
        return True

    # /sum /avg /median /min /max
    if cmd in ("sum", "avg", "mean", "median", "min", "max"):
        result = tc_calc_engine(df, cmd, args)
        _tc_router_reply(uid, raw, result)
        return True

    # /rank <列名> [asc|desc]
    if cmd == "rank":
        result = tc_rank_engine(df, args)
        _tc_router_reply(uid, raw, result)
        return True

    # /diff <列名>
    if cmd == "diff":
        result, new_df = tc_diff_engine(df, args)
        if new_df is not None:
            tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /growth <列名>
    if cmd == "growth":
        result, new_df = tc_growth_engine(df, args)
        if new_df is not None:
            tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /filter <列名> <演算子> <値>
    if cmd == "filter":
        result, new_df = tc_filter_engine(df, args)
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /sort <列名> [asc|desc]
    if cmd == "sort":
        result, new_df = tc_sort_engine(df, args)
        if new_df is not None:
            tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /select <列1,列2,...>
    if cmd == "select":
        result, new_df = tc_select_engine(df, args)
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /top <N> <列名>
    if cmd == "top":
        result, new_df = tc_top_engine(df, args)
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # /derive <新列名>=<式>
    if cmd == "derive":
        result, new_df = tc_derive_engine(df, args)
        if new_df is not None:
            tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
        _tc_router_reply(uid, raw, result, df=new_df)
        return True

    # 未知コマンド → 使い方案内
    help_text = (
        "❓ **使用できるコマンド一覧**\n\n"
        "| コマンド | 説明 | 例 |\n"
        "|---|---|---|\n"
        "| `/sum 列名` | 合計 | `/sum 売上` |\n"
        "| `/avg 列名` | 平均 | `/avg 客数` |\n"
        "| `/median 列名` | 中央値 | `/median 単価` |\n"
        "| `/min 列名` | 最小値 | `/min 売上` |\n"
        "| `/max 列名` | 最大値 | `/max 売上` |\n"
        "| `/rank 列名 [asc\\|desc]` | 順位付け | `/rank 売上 desc` |\n"
        "| `/diff 列名` | 前行差分 | `/diff 売上` |\n"
        "| `/growth 列名` | 前行比増減率% | `/growth 売上` |\n"
        "| `/filter 列名 演算子 値` | 条件抽出 | `/filter 売上 >= 100` |\n"
        "| `/sort 列名 [asc\\|desc]` | 並び替え | `/sort 売上 desc` |\n"
        "| `/select 列1,列2,...` | 列抽出 | `/select 月,売上,客数` |\n"
        "| `/top N 列名` | 上位N件 | `/top 5 売上` |\n"
        "| `/derive 新列=式` | 派生列 | `/derive 客単価=売上/客数` |\n"
        "| `/consult` | AI分析・異常検知・提案 | `/consult` |\n"
        "| `/show` | 現在の表を再表示 | `/show` |\n"
        "| `/reset` | 表セッションをリセット | `/reset` |\n"
    )
    _tc_router_reply(uid, raw, help_text)
    return True


def _tc_router_reply(uid: str, user_input: str, message: str, df=None):
    """コマンド結果をチャットUIに表示し、セッションメッセージに追記"""
    with st.chat_message("user"):
        st.markdown(f"`{user_input}`")
    with st.chat_message("assistant"):
        st.markdown(message)
        if df is not None and isinstance(df, pd.DataFrame) and not df.empty:
            st.dataframe(df, use_container_width=True, hide_index=True)
    try:
        save_chat_message("user", st.session_state.get(SS_SHARE_TENANT, ""), uid, "user", user_input)
        save_chat_message("assistant", st.session_state.get(SS_SHARE_TENANT, ""), uid, "assistant", message)
    except Exception:
        pass


# ── 2-2. 列指定の計算エンジン ────────────────────────────────────────
def tc_calc_engine(df: pd.DataFrame, op: str, col_name: str) -> str:
    """
    /sum /avg /median /min /max を実行して結果文字列を返す
    """
    col_name = col_name.strip()
    if not col_name:
        return "❌ 列名を指定してください。例: `/sum 売上`"

    # 部分一致で列を探す
    matched = _tc_find_col(df, col_name)
    if matched is None:
        cols = "、".join(str(c) for c in df.columns)
        return f"❌ 列 `{col_name}` が見つかりません。\n利用可能な列: {cols}"

    series = pd.to_numeric(df[matched], errors="coerce").dropna()
    if series.empty:
        return f"❌ 列 `{matched}` に数値データがありません。"

    op_lower = op.lower()
    if op_lower == "sum":
        val = series.sum()
        label = "合計"
    elif op_lower in ("avg", "mean"):
        val = series.mean()
        label = "平均"
    elif op_lower == "median":
        val = series.median()
        label = "中央値"
    elif op_lower == "min":
        val = series.min()
        label = "最小値"
    elif op_lower == "max":
        val = series.max()
        label = "最大値"
    else:
        return f"❌ 未知の演算: {op}"

    return (
        f"📊 **{matched}** の{label}\n\n"
        f"**{val:,.4f}**（有効データ数: {len(series):,} / 全{len(df):,}行）"
    )


def _tc_find_col(df: pd.DataFrame, col_name: str):
    """完全一致→前方一致→部分一致で列名を検索。見つからなければ None"""
    if col_name in df.columns:
        return col_name
    for c in df.columns:
        if str(c).startswith(col_name):
            return c
    for c in df.columns:
        if col_name in str(c):
            return c
    # 大文字小文字無視
    col_lower = col_name.lower()
    for c in df.columns:
        if col_lower in str(c).lower():
            return c
    return None


# ── 2-3. ランキングエンジン ──────────────────────────────────────────
def tc_rank_engine(df: pd.DataFrame, args: str) -> str:
    """
    /rank <列名> [asc|desc]
    列に対してランク列を追加して返す
    """
    parts = args.strip().split()
    col_name = parts[0] if parts else ""
    order = parts[1].lower() if len(parts) > 1 else "desc"
    if not col_name:
        return "❌ 列名を指定してください。例: `/rank 売上 desc`"
    matched = _tc_find_col(df, col_name)
    if matched is None:
        return f"❌ 列 `{col_name}` が見つかりません。"
    ascending = (order == "asc")
    series = pd.to_numeric(df[matched], errors="coerce")
    rank_col = f"{matched}_順位"
    df2 = df.copy()
    df2[rank_col] = series.rank(ascending=ascending, method="min").astype("Int64")
    df2 = df2.sort_values(rank_col)
    top5 = df2[[matched, rank_col]].head(5).to_string(index=False)
    order_label = "昇順" if ascending else "降順"
    return (
        f"🏆 **{matched}** のランキング（{order_label}）\n\n"
        f"```\n{top5}\n```\n\n"
        f"列 `{rank_col}` を追加しました。`/show` で全体表示できます。"
    )


# ── 2-4. 差分エンジン ────────────────────────────────────────────────
def tc_diff_engine(df: pd.DataFrame, col_name: str):
    """
    /diff <列名>  → 前行との差分列を追加
    Returns: (message: str, new_df: pd.DataFrame | None)
    """
    col_name = col_name.strip()
    matched = _tc_find_col(df, col_name)
    if matched is None:
        return f"❌ 列 `{col_name}` が見つかりません。", None
    series = pd.to_numeric(df[matched], errors="coerce")
    df2 = df.copy()
    diff_col = f"{matched}_差分"
    df2[diff_col] = series.diff()
    preview = df2[[matched, diff_col]].head(5).to_string(index=False)
    return (
        f"📉 **{matched}** の前行差分\n\n"
        f"```\n{preview}\n```\n\n"
        f"列 `{diff_col}` を追加しました。"
    ), df2


# ── 2-5. 増減率エンジン ──────────────────────────────────────────────
def tc_growth_engine(df: pd.DataFrame, col_name: str):
    """
    /growth <列名>  → 前行比増減率(%)列を追加
    Returns: (message: str, new_df: pd.DataFrame | None)
    """
    col_name = col_name.strip()
    matched = _tc_find_col(df, col_name)
    if matched is None:
        return f"❌ 列 `{col_name}` が見つかりません。", None
    series = pd.to_numeric(df[matched], errors="coerce")
    df2 = df.copy()
    growth_col = f"{matched}_増減率(%)"
    df2[growth_col] = series.pct_change() * 100
    df2[growth_col] = df2[growth_col].round(2)
    preview = df2[[matched, growth_col]].head(6).to_string(index=False)
    avg_growth = df2[growth_col].mean()
    return (
        f"📈 **{matched}** の前月比増減率\n\n"
        f"```\n{preview}\n```\n\n"
        f"平均増減率: **{avg_growth:+.2f}%**\n"
        f"列 `{growth_col}` を追加しました。"
    ), df2


# ── 2-6. フィルタエンジン ────────────────────────────────────────────
def tc_filter_engine(df: pd.DataFrame, args: str):
    """
    /filter <列名> <演算子> <値>
    演算子: >= <= > < == != contains startswith
    Returns: (message: str, filtered_df: pd.DataFrame | None)
    """
    # パース: "売上 >= 100" or "商品名 contains ラーメン"
    m = re.match(r"^(.+?)\s+(>=|<=|>|<|==|!=|contains|startswith)\s+(.+)$", args.strip())
    if not m:
        return (
            "❌ フィルター形式が正しくありません。\n"
            "例: `/filter 売上 >= 100` または `/filter 商品名 contains ラーメン`"
        ), None

    col_raw, op, val_raw = m.group(1).strip(), m.group(2).strip(), m.group(3).strip()
    matched = _tc_find_col(df, col_raw)
    if matched is None:
        cols = "、".join(str(c) for c in df.columns)
        return f"❌ 列 `{col_raw}` が見つかりません。\n利用可能: {cols}", None

    try:
        if op in ("contains", "startswith"):
            s = df[matched].astype(str)
            if op == "contains":
                mask = s.str.contains(val_raw, na=False, regex=False)
            else:
                mask = s.str.startswith(val_raw, na=False)
        else:
            # 数値比較
            numeric_series = pd.to_numeric(df[matched], errors="coerce")
            try:
                val_num = float(val_raw.replace(",", ""))
            except ValueError:
                return f"❌ 値 `{val_raw}` を数値に変換できません。文字列フィルターには `contains` を使用してください。", None
            if op == ">=":
                mask = numeric_series >= val_num
            elif op == "<=":
                mask = numeric_series <= val_num
            elif op == ">":
                mask = numeric_series > val_num
            elif op == "<":
                mask = numeric_series < val_num
            elif op == "==":
                mask = numeric_series == val_num
            elif op == "!=":
                mask = numeric_series != val_num
            else:
                return f"❌ 未知の演算子: `{op}`", None

        filtered = df[mask].reset_index(drop=True)
        if filtered.empty:
            return f"⚠️ 条件 `{matched} {op} {val_raw}` に一致する行がありませんでした。", None

        return (
            f"🔍 **フィルター結果**: `{matched} {op} {val_raw}`\n\n"
            f"**{len(filtered):,}行** / 元{len(df):,}行（{len(filtered)/len(df)*100:.1f}%）\n\n"
            f"※この結果は一時表示です。保持したい場合は `/sort` や `/derive` を続けて実行してください。"
        ), filtered

    except Exception as e:
        return f"❌ フィルターエラー: {e}", None


# ── 2-7. ソートエンジン ──────────────────────────────────────────────
def tc_sort_engine(df: pd.DataFrame, args: str):
    """
    /sort <列名> [asc|desc]
    Returns: (message: str, sorted_df: pd.DataFrame)
    """
    parts = args.strip().split()
    col_name = parts[0] if parts else ""
    order = parts[1].lower() if len(parts) > 1 else "desc"
    if not col_name:
        return "❌ 列名を指定してください。例: `/sort 売上 desc`", None
    matched = _tc_find_col(df, col_name)
    if matched is None:
        return f"❌ 列 `{col_name}` が見つかりません。", None
    ascending = (order == "asc")
    try:
        numeric_series = pd.to_numeric(df[matched], errors="coerce")
        if numeric_series.notna().sum() > len(df) * 0.5:
            df2 = df.copy()
            df2["__sort_key__"] = numeric_series
            df2 = df2.sort_values("__sort_key__", ascending=ascending).drop(columns=["__sort_key__"]).reset_index(drop=True)
        else:
            df2 = df.sort_values(matched, ascending=ascending).reset_index(drop=True)
        order_label = "昇順" if ascending else "降順"
        return (
            f"🔀 **{matched}** で{order_label}にソートしました（{len(df2):,}行）。"
        ), df2
    except Exception as e:
        return f"❌ ソートエラー: {e}", None


# ── 2-8. 列選択エンジン ──────────────────────────────────────────────
def tc_select_engine(df: pd.DataFrame, args: str):
    """
    /select <列1,列2,...>
    Returns: (message: str, selected_df: pd.DataFrame | None)
    """
    col_names = [c.strip() for c in args.split(",") if c.strip()]
    if not col_names:
        return "❌ 列名をカンマ区切りで指定してください。例: `/select 月,売上,客数`", None
    matched_cols = []
    not_found = []
    for cn in col_names:
        m = _tc_find_col(df, cn)
        if m:
            matched_cols.append(m)
        else:
            not_found.append(cn)
    if not matched_cols:
        cols = "、".join(str(c) for c in df.columns)
        return f"❌ 指定列が1つも見つかりません。\n利用可能: {cols}", None
    selected = df[matched_cols].copy()
    warn = f"\n\n⚠️ 見つからなかった列: {', '.join(not_found)}" if not_found else ""
    return (
        f"📋 **列選択**: {' / '.join(matched_cols)}（{len(selected):,}行 × {len(matched_cols)}列）{warn}"
    ), selected


# ── 2-9. 上位N件エンジン ─────────────────────────────────────────────
def tc_top_engine(df: pd.DataFrame, args: str):
    """
    /top <N> <列名>
    Returns: (message: str, top_df: pd.DataFrame | None)
    """
    parts = args.strip().split(None, 1)
    if len(parts) < 2:
        return "❌ 形式: `/top N 列名`　例: `/top 5 売上`", None
    try:
        n = int(parts[0])
    except ValueError:
        return f"❌ N は整数で指定してください: `{parts[0]}`", None
    col_name = parts[1].strip()
    matched = _tc_find_col(df, col_name)
    if matched is None:
        return f"❌ 列 `{col_name}` が見つかりません。", None
    numeric_series = pd.to_numeric(df[matched], errors="coerce")
    df2 = df.copy()
    df2["__sort_key__"] = numeric_series
    top_df = df2.sort_values("__sort_key__", ascending=False).head(n).drop(columns=["__sort_key__"]).reset_index(drop=True)
    return (
        f"🏅 **{matched}** 上位{n}件"
    ), top_df


# ── 2-10. 派生列生成エンジン ─────────────────────────────────────────
# 対応式:
#   四則演算:  客単価=売上/客数  粗利=売上-原価
#   組み込み:  構成比=売上/sum(売上)*100  前月比=売上/lag(売上)*100
#   ROAS=売上/広告費*100  CPA=広告費/件数  粗利率=(売上-原価)/売上*100

_TC_DERIVE_PRESETS = {
    "構成比": lambda df, col: pd.to_numeric(df[col], errors="coerce") / pd.to_numeric(df[col], errors="coerce").sum() * 100,
    "前月比": lambda df, col: pd.to_numeric(df[col], errors="coerce") / pd.to_numeric(df[col], errors="coerce").shift(1) * 100,
}

def tc_derive_engine(df: pd.DataFrame, expr: str):
    """
    /derive <新列名>=<式>
    式例:
      客単価=売上/客数
      粗利率=(売上-原価)/売上*100
      売上構成比=構成比(売上)
      前月比=前月比(売上)
      ROAS=売上/広告費*100
      CPA=広告費/CV数
    Returns: (message: str, new_df: pd.DataFrame | None)
    """
    if "=" not in expr:
        return "❌ 形式: `/derive 新列名=式`　例: `/derive 客単価=売上/客数`", None

    eq_idx = expr.index("=")
    new_col = expr[:eq_idx].strip()
    formula = expr[eq_idx + 1:].strip()

    if not new_col:
        return "❌ 新列名を指定してください。", None

    df2 = df.copy()

    # 組み込みプリセット: 構成比(列名) / 前月比(列名)
    m_preset = re.match(r"^(構成比|前月比)\((.+)\)$", formula)
    if m_preset:
        preset_name = m_preset.group(1)
        target_col_raw = m_preset.group(2).strip()
        target_col = _tc_find_col(df2, target_col_raw)
        if target_col is None:
            return f"❌ 列 `{target_col_raw}` が見つかりません。", None
        fn = _TC_DERIVE_PRESETS[preset_name]
        df2[new_col] = fn(df2, target_col).round(4)
        preview = df2[[target_col, new_col]].head(5).to_string(index=False)
        return (
            f"✨ 派生列 `{new_col}` を追加しました（{preset_name}）\n\n"
            f"```\n{preview}\n```"
        ), df2

    # 汎用四則演算: 列名を変数として評価
    # 列名を "_col_xxx" 形式にエスケープして eval
    try:
        safe_formula = formula
        col_map = {}
        # 列名を長い順に置換（短い列名が長い列名の一部にマッチしないよう）
        sorted_cols = sorted(df2.columns, key=lambda c: -len(str(c)))
        for i, col in enumerate(sorted_cols):
            safe_var = f"_c{i}_"
            col_str = str(col)
            if col_str in safe_formula:
                safe_formula = safe_formula.replace(col_str, safe_var)
                col_map[safe_var] = col

        # sum() / lag() の特殊関数対応
        def _sum_fn(arr):
            return pd.to_numeric(arr, errors="coerce").sum()
        def _lag_fn(arr):
            return pd.to_numeric(arr, errors="coerce").shift(1)

        local_vars = {"sum": _sum_fn, "lag": _lag_fn, "pd": pd}
        for safe_var, col in col_map.items():
            local_vars[safe_var] = pd.to_numeric(df2[col], errors="coerce")

        result_series = eval(safe_formula, {"__builtins__": {}}, local_vars)  # noqa
        if isinstance(result_series, (int, float)):
            df2[new_col] = result_series
        else:
            df2[new_col] = pd.Series(result_series, index=df2.index).round(4)

        preview = df2[list(col_map.values())[:3] + [new_col]].head(5).to_string(index=False)
        return (
            f"✨ 派生列 `{new_col}` を追加しました\n\n"
            f"式: `{formula}`\n\n"
            f"```\n{preview}\n```"
        ), df2

    except Exception as e:
        return (
            f"❌ 式の評価に失敗しました: `{formula}`\n\n"
            f"エラー: {e}\n\n"
            f"使用可能な列名: {', '.join(str(c) for c in df.columns)}"
        ), None


# ── 2-11. 数値コンサル分析層 ─────────────────────────────────────────
def tc_consult_analysis(df: pd.DataFrame) -> str:
    """
    /consult で実行する数値コンサル分析。
    1. 異常検知（±2σ外れ値）
    2. 比較分析（最大/最小/範囲/CV）
    3. 相関分析（数値列間）
    4. 原因候補抽出
    5. 改善提案
    """
    if df is None or df.empty:
        return "❌ 分析対象の表がありません。"

    numeric_cols = df.select_dtypes(include="number").columns.tolist()
    if not numeric_cols:
        # 数値変換を試みる
        for c in df.columns:
            converted = pd.to_numeric(df[c], errors="coerce")
            if converted.notna().sum() > len(df) * 0.5:
                df = df.copy()
                df[c] = converted
        numeric_cols = df.select_dtypes(include="number").columns.tolist()

    if not numeric_cols:
        return "⚠️ 数値列が見つからないため定量分析ができません。列名と値を確認してください。"

    lines = ["## 📊 数値コンサル分析レポート\n"]

    # ── 1. 基本統計サマリー ──
    lines.append("### 1. 基本統計")
    for col in numeric_cols[:8]:
        s = df[col].dropna()
        if s.empty:
            continue
        lines.append(
            f"- **{col}**: 合計={s.sum():,.2f} / 平均={s.mean():,.2f} / "
            f"中央値={s.median():,.2f} / 最小={s.min():,.2f} / 最大={s.max():,.2f}"
        )

    # ── 2. 異常値検知（±2σ）──
    lines.append("\n### 2. 異常値検知（±2σ ベースライン）")
    anomalies_found = False
    for col in numeric_cols[:8]:
        s = pd.to_numeric(df[col], errors="coerce").dropna()
        if len(s) < 4:
            continue
        mean, std = s.mean(), s.std()
        if std == 0:
            continue
        outlier_mask = (s - mean).abs() > 2 * std
        outlier_idx = s[outlier_mask].index.tolist()
        if outlier_idx:
            anomalies_found = True
            for idx in outlier_idx[:3]:
                val = df[col].iloc[idx] if idx < len(df) else "?"
                z = (float(val) - mean) / std if std else 0
                # 行ラベルを取得（1列目を使用）
                row_label = str(df.iloc[idx, 0]) if len(df.columns) > 0 else f"行{idx+1}"
                lines.append(
                    f"- ⚠️ **{col}** 行[{row_label}]: `{val}` "
                    f"（平均{mean:,.1f} から {z:+.1f}σ 乖離）"
                )
    if not anomalies_found:
        lines.append("- ✅ 顕著な外れ値は検出されませんでした。")

    # ── 3. 比較分析（変動係数）──
    lines.append("\n### 3. ばらつき・変動分析")
    volatile_cols = []
    for col in numeric_cols[:8]:
        s = pd.to_numeric(df[col], errors="coerce").dropna()
        if s.mean() == 0 or len(s) < 2:
            continue
        cv = s.std() / abs(s.mean()) * 100  # 変動係数(%)
        label = "🔴 高変動" if cv > 30 else "🟡 中変動" if cv > 15 else "🟢 安定"
        lines.append(f"- **{col}**: CV={cv:.1f}% {label}")
        if cv > 30:
            volatile_cols.append(col)

    # ── 4. 相関分析（数値列が2列以上の場合）──
    if len(numeric_cols) >= 2:
        lines.append("\n### 4. 相関分析（上位ペア）")
        try:
            numeric_df = df[numeric_cols[:8]].apply(pd.to_numeric, errors="coerce")
            corr_matrix = numeric_df.corr()
            pairs = []
            cols_list = corr_matrix.columns.tolist()
            for i in range(len(cols_list)):
                for j in range(i + 1, len(cols_list)):
                    r = corr_matrix.iloc[i, j]
                    if not pd.isna(r):
                        pairs.append((cols_list[i], cols_list[j], r))
            pairs.sort(key=lambda x: abs(x[2]), reverse=True)
            for c1, c2, r in pairs[:5]:
                direction = "正比例" if r > 0 else "逆比例"
                strength = "強い" if abs(r) > 0.7 else "中程度" if abs(r) > 0.4 else "弱い"
                lines.append(f"- **{c1}** × **{c2}**: r={r:.3f}（{strength}{direction}）")
        except Exception:
            lines.append("- 相関分析をスキップしました。")

    # ── 5. トレンド判定（行が時系列と仮定）──
    if len(df) >= 3:
        lines.append("\n### 5. トレンド判定")
        for col in numeric_cols[:5]:
            s = pd.to_numeric(df[col], errors="coerce").dropna()
            if len(s) < 3:
                continue
            # 線形回帰の傾き符号でトレンド判定
            try:
                x = list(range(len(s)))
                n = len(x)
                slope = (n * sum(xi * yi for xi, yi in zip(x, s)) - sum(x) * s.sum()) / \
                        (n * sum(xi**2 for xi in x) - sum(x)**2)
                pct_change_total = (s.iloc[-1] - s.iloc[0]) / abs(s.iloc[0]) * 100 if s.iloc[0] != 0 else 0
                trend_label = "📈 上昇傾向" if slope > 0 else "📉 下降傾向"
                lines.append(
                    f"- **{col}**: {trend_label} "
                    f"（期間変化率: {pct_change_total:+.1f}%）"
                )
            except Exception:
                continue

    # ── 6. 改善提案 ──
    lines.append("\n### 6. 改善提案・次の打ち手")
    suggestions = []

    if volatile_cols:
        suggestions.append(
            f"- 🎯 **高変動列 [{', '.join(volatile_cols[:3])}]** は安定化施策が優先課題。"
            f"原因分解に `/filter` コマンドでセグメント別確認を推奨。"
        )

    if anomalies_found:
        suggestions.append(
            "- 🔍 **外れ値** が検出されました。データ入力ミス・イベント要因・季節性の3仮説から検証してください。"
        )

    # 数値列に「売上」「客数」が含まれる場合
    sales_col = next((c for c in numeric_cols if "売上" in str(c) or "売" in str(c)), None)
    customer_col = next((c for c in numeric_cols if "客数" in str(c) or "顧客" in str(c) or "来客" in str(c)), None)
    if sales_col and customer_col:
        suggestions.append(
            f"- 💡 `/derive 客単価={sales_col}/{customer_col}` で客単価を算出し、"
            f"改善レバーが「単価UP」か「客数UP」かを特定することを推奨。"
        )

    cost_col = next((c for c in numeric_cols if "原価" in str(c) or "コスト" in str(c) or "費用" in str(c)), None)
    if sales_col and cost_col:
        suggestions.append(
            f"- 💡 `/derive 粗利率=({sales_col}-{cost_col})/{sales_col}*100` で粗利率を算出してください。"
        )

    ad_col = next((c for c in numeric_cols if "広告" in str(c) or "広告費" in str(c)), None)
    cv_col = next((c for c in numeric_cols if "CV" in str(c) or "件数" in str(c) or "獲得" in str(c)), None)
    if ad_col and cv_col:
        suggestions.append(
            f"- 💡 CPA分析: `/derive CPA={ad_col}/{cv_col}`"
        )
    if ad_col and sales_col:
        suggestions.append(
            f"- 💡 ROAS分析: `/derive ROAS={sales_col}/{ad_col}*100`"
        )

    if not suggestions:
        suggestions.append(
            "- 数値構造は安定しています。`/derive` で派生KPIを追加するか、"
            "`/filter` でセグメント別分析を行ってください。"
        )

    lines.extend(suggestions)
    lines.append(
        "\n---\n💬 **次のコマンド例**: "
        "`/rank 売上 desc` / `/filter 売上 >= 100` / `/derive 客単価=売上/客数` / `/growth 売上`"
    )

    return "\n".join(lines)


# ── 2-11b. 自然文AI操作ルーター ──────────────────────────────────────
# 「売上平均出して」「客数でフィルターして100以上」などスラッシュなしで動く

_TC_NL_INTENT_PATTERNS = [
    # (regex, intent, group_map)
    # --- 集計 ---
    (r"(.+?)(?:の|を)?\s*(?:合計|足し算|sum)", "sum", {"col": 1}),
    (r"(.+?)(?:の|を)?\s*(?:平均|アベレージ|avg|mean)", "avg", {"col": 1}),
    (r"(.+?)(?:の|を)?\s*(?:中央値|メジアン|median)", "median", {"col": 1}),
    (r"(.+?)(?:の|を)?\s*(?:最小(?:値)?|min)", "min", {"col": 1}),
    (r"(.+?)(?:の|を)?\s*(?:最大(?:値)?|max)", "max", {"col": 1}),
    # --- ランク ---
    (r"(.+?)(?:の|で)?\s*(?:ランキング|順位|rank|ランク)(?:\s*(昇順|降順|asc|desc))?", "rank", {"col": 1, "order": 2}),
    (r"(.+?)(?:の|で)?\s*(?:上位)\s*(\d+)件?", "top", {"col": 1, "n": 2}),
    (r"上位\s*(\d+)件?\s*(?:を|の)?\s*(.+?)(?:で|順)?", "top", {"n": 1, "col": 2}),
    # --- 差分・増減 ---
    (r"(.+?)(?:の|を)?\s*(?:差分|前(?:行|月|期)(?:差|比較)|diff)", "diff", {"col": 1}),
    (r"(.+?)(?:の|を)?\s*(?:増減率|前(?:行|月|期)比|成長率|growth)", "growth", {"col": 1}),
    # --- フィルタ ---
    (r"(.+?)(?:が|の)?\s*(>=|<=|>|<|==|!=|以上|以下|超|未満|より大きい|より小さい|等しい|と等しい)\s*([^\s]+)", "filter", {"col": 1, "op": 2, "val": 3}),
    (r"(.+?)\s*(?:が|で|を)\s*(.+?)\s*(?:含む|含んでいる|contains)", "filter_contains", {"col": 1, "val": 2}),
    # --- ソート ---
    (r"(.+?)(?:で|を|の)?\s*(?:並び替え|ソート|sort)(?:\s*(昇順|降順|大きい順|小さい順|asc|desc))?", "sort", {"col": 1, "order": 2}),
    (r"(?:大きい順|降順|多い順)\s*(?:に|で)?\s*(.+?)(?:を|で|の)?\s*(?:並べ|ソート|sort)?", "sort_desc", {"col": 1}),
    (r"(?:小さい順|昇順|少ない順)\s*(?:に|で)?\s*(.+?)(?:を|で|の)?\s*(?:並べ|ソート|sort)?", "sort_asc", {"col": 1}),
    # --- 列選択 ---
    (r"(.+?)(?:列|カラム)?\s*(?:だけ|のみ|を?抽出|を?選択|select)", "select", {"cols": 1}),
    # --- 派生列 ---
    (r"(.+?)\s*[=＝]\s*(.+?)(?:を?計算|を?作|を?追加|derive)?$", "derive", {"new_col": 1, "formula": 2}),
    (r"(.+?)(?:を|の)?\s*(?:計算|作成|追加)(?:して|する|せよ)?\s*[=＝]\s*(.+)", "derive", {"new_col": 1, "formula": 2}),
    # --- コンサル ---
    (r"(?:分析|コンサル|consult|診断|異常|提案|改善|問題点)", "consult", {}),
    # --- リセット ---
    (r"(?:リセット|クリア|reset|clear)(?:して|する)?", "reset", {}),
    # --- 表示 ---
    (r"(?:表示|見せ|show|表を?出|今の表)", "show", {}),
]

_TC_OP_WORDS = {
    "以上": ">=", "以下": "<=", "超": ">", "未満": "<",
    "より大きい": ">", "より小さい": "<", "等しい": "==", "と等しい": "==",
    ">=": ">=", "<=": "<=", ">": ">", "<": "<", "==": "==", "!=": "!=",
}
_TC_ORDER_WORDS = {
    "降順": "desc", "大きい順": "desc", "多い順": "desc", "desc": "desc",
    "昇順": "asc", "小さい順": "asc", "少ない順": "asc", "asc": "asc",
}


def tc_nl_router(text: str, uid: str, tenant_id: str) -> bool:
    """
    自然文の表操作を解釈して実行するルーター。
    Step1: 正規表現パターンで高速マッチ
    Step2: マッチしない場合 LLM でインテント抽出
    Step3: 抽出したインテント → 既存エンジンへ配線
    Returns: True → 処理完了 / False → 通常パイプへ
    """
    df = tc_get_session_table(uid)
    if df is None:
        return False

    text_stripped = text.strip()

    # Step1: 正規表現マッチ
    intent_result = _tc_nl_regex_parse(text_stripped, df)

    # Step2: 正規表現でマッチしなかった場合 → LLM インテント解釈
    if intent_result is None:
        intent_result = _tc_nl_llm_parse(text_stripped, df)

    if intent_result is None:
        return False

    intent = intent_result.get("intent", "")
    if not intent:
        return False

    # Step3: インテント → エンジン配線
    return _tc_nl_dispatch(intent_result, df, uid, tenant_id, text_stripped)


def _tc_nl_regex_parse(text: str, df: pd.DataFrame) -> dict:
    """正規表現で自然文からインテントを抽出する"""
    col_names = [str(c) for c in df.columns]

    for pattern, intent, group_map in _TC_NL_INTENT_PATTERNS:
        m = re.search(pattern, text, re.IGNORECASE)
        if not m:
            continue

        result = {"intent": intent}

        # グループ抽出
        for key, grp_idx in group_map.items():
            try:
                result[key] = (m.group(grp_idx) or "").strip()
            except Exception:
                result[key] = ""

        # 列名の正規化（部分一致で実列名に変換）
        for key in ("col", "cols"):
            if key in result and result[key]:
                matched_col = _tc_find_col(df, result[key])
                if matched_col:
                    result[key] = matched_col
                else:
                    # 複数列対応（カンマ/スラッシュ/「と」区切り）
                    raw_cols = re.split(r"[,、/・とand]", result[key])
                    found = [_tc_find_col(df, rc.strip()) for rc in raw_cols if rc.strip()]
                    found = [f for f in found if f]
                    if found:
                        result[key] = ",".join(found)
                    else:
                        # 列名が見つからなければこのパターンはスキップ
                        result = None
                        break
        if result is None:
            continue

        # operator の正規化
        if "op" in result and result["op"]:
            result["op"] = _TC_OP_WORDS.get(result["op"], result["op"])

        # order の正規化
        if "order" in result:
            result["order"] = _TC_ORDER_WORDS.get(result.get("order", ""), "desc")

        # sort_desc / sort_asc を sort に統一
        if intent == "sort_desc":
            result["intent"] = "sort"
            result["order"] = "desc"
        elif intent == "sort_asc":
            result["intent"] = "sort"
            result["order"] = "asc"

        return result

    return None


def _tc_nl_llm_parse(text: str, df: pd.DataFrame) -> dict:
    """
    LLM を使って自然文からインテントと引数を抽出する。
    返値: {"intent": str, "col": str, ...} or None
    """
    col_list = ", ".join(f'"{c}"' for c in df.columns[:20])
    rows_preview = df.head(3).to_string(index=False)

    sys_prompt = (
        "あなたは表操作AIです。ユーザーの自然文から操作インテントを抽出してJSONのみ返せ。\n"
        "インテント一覧: sum, avg, median, min, max, rank, top, diff, growth, "
        "filter, sort, select, derive, consult, show, reset\n"
        "出力フォーマット（JSONのみ。説明不要）:\n"
        '{"intent":"<インテント>","col":"<列名>","op":"<>=<=><!=等>","val":"<値>",'
        '"order":"<asc|desc>","n":"<整数>","new_col":"<新列名>","formula":"<式>",'
        '"cols":"<列1,列2,...>"}\n'
        "不要なキーは省略。インテントが不明なら {\"intent\":\"unknown\"} を返せ。"
    )
    user_prompt = (
        f"表の列名: [{col_list}]\n"
        f"表のサンプル（先頭3行）:\n{rows_preview}\n\n"
        f"ユーザーの指示: {text}"
    )

    try:
        raw = call_llm(user_prompt, history=[], sys=sys_prompt)
        if not raw:
            return None
        # JSONを抽出
        m = re.search(r"\{.*\}", raw, re.DOTALL)
        if not m:
            return None
        parsed = __import__("json").loads(m.group(0))
        intent = parsed.get("intent", "unknown")
        if intent == "unknown" or not intent:
            return None
        # 列名を実列名に正規化
        for key in ("col", "cols"):
            if key in parsed and parsed[key]:
                matched = _tc_find_col(df, parsed[key])
                if matched:
                    parsed[key] = matched
        return parsed
    except Exception:
        return None


def _tc_nl_dispatch(intent_result: dict, df: pd.DataFrame, uid: str, tenant_id: str, original_text: str) -> bool:
    """
    インテント辞書 → 既存エンジン関数へ配線して結果をチャット表示
    Returns: True → 処理完了 / False → ディスパッチ失敗
    """
    intent = intent_result.get("intent", "")
    col    = intent_result.get("col", "")
    order  = intent_result.get("order", "desc")
    op     = intent_result.get("op", "")
    val    = intent_result.get("val", "")
    n_str  = intent_result.get("n", "5")
    new_col = intent_result.get("new_col", "")
    formula = intent_result.get("formula", "")
    cols   = intent_result.get("cols", "")

    try:
        if intent in ("sum", "avg", "mean", "median", "min", "max"):
            result = tc_calc_engine(df, intent, col)
            _tc_router_reply(uid, original_text, result)

        elif intent == "rank":
            result = tc_rank_engine(df, f"{col} {order}")
            _tc_router_reply(uid, original_text, result)

        elif intent == "top":
            try:
                n = int(n_str) if n_str else 5
            except ValueError:
                n = 5
            result, new_df = tc_top_engine(df, f"{n} {col}")
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "diff":
            result, new_df = tc_diff_engine(df, col)
            if new_df is not None:
                tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "growth":
            result, new_df = tc_growth_engine(df, col)
            if new_df is not None:
                tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "filter":
            if not op:
                op = ">="
            filter_args = f"{col} {op} {val}"
            result, new_df = tc_filter_engine(df, filter_args)
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "filter_contains":
            filter_args = f"{col} contains {val}"
            result, new_df = tc_filter_engine(df, filter_args)
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "sort":
            sort_args = f"{col} {order}"
            result, new_df = tc_sort_engine(df, sort_args)
            if new_df is not None:
                tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "select":
            select_cols = cols if cols else col
            result, new_df = tc_select_engine(df, select_cols)
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "derive":
            if not new_col or not formula:
                return False
            derive_args = f"{new_col}={formula}"
            result, new_df = tc_derive_engine(df, derive_args)
            if new_df is not None:
                tc_set_session_table(uid, new_df, fmt=st.session_state.get("_tc_fmt", ""))
            _tc_router_reply(uid, original_text, result, df=new_df)

        elif intent == "consult":
            result = tc_consult_analysis(df)
            _tc_router_reply(uid, original_text, result)

        elif intent == "show":
            _tc_router_reply(uid, original_text, tc_render_summary(df), df=df)

        elif intent == "reset":
            tc_clear_session_table()
            tc_delete_table_session(uid)
            _tc_router_reply(uid, original_text, "🗑️ 表セッションをリセットしました。")

        else:
            return False

        # 操作後に永続化
        _tc_df_after = tc_get_session_table(uid)
        if _tc_df_after is not None:
            tc_save_table_session(uid, tenant_id, _tc_df_after, fmt=st.session_state.get("_tc_fmt", ""))

        return True

    except Exception as _e:
        try:
            if os.environ.get("TABLECHAT_DEBUG", "").lower() in ("1", "true"):
                st.warning(f"[TableChat NL dispatch] {_e}")
        except Exception:
            pass
        return False


def _tc_nl_is_table_operation(text: str, df: pd.DataFrame) -> bool:
    """
    テキストが表操作の自然文かどうかを軽量判定する。
    LLM呼び出し前のゲートとして機能し、無関係なテキストで
    tc_nl_router が起動しないようにする。
    """
    # 操作キーワードリスト
    _OP_KEYWORDS = [
        "合計", "足し", "sum", "平均", "avg", "mean", "中央値", "median",
        "最小", "最大", "min", "max",
        "ランキング", "順位", "rank", "ランク",
        "上位", "top",
        "差分", "前月比", "前行", "前期", "増減率", "growth", "diff",
        "フィルタ", "フィルター", "絞り込み", "抽出", "filter",
        "並び替え", "ソート", "sort", "並べ",
        "大きい順", "小さい順", "降順", "昇順",
        "列", "カラム", "select", "選択", "だけ出",
        "計算", "作成", "追加", "derive",
        "分析", "コンサル", "consult", "診断", "異常", "改善", "提案",
        "リセット", "クリア", "reset",
        "表示", "見せ", "show",
    ]
    text_lower = text.lower()

    # キーワード一致
    for kw in _OP_KEYWORDS:
        if kw in text_lower:
            return True

    # 列名が含まれているかチェック（列名＋動詞の組み合わせ）
    col_names = [str(c) for c in df.columns]
    for col in col_names:
        if col in text and any(
            verb in text for verb in ["出して", "計算", "見せ", "教えて", "調べ", "表示", "比較", "分析"]
        ):
            return True

    return False


# ── 2-12. 添付スプレッドシート → TableChat 直結導線 ─────────────────
def tc_try_load_attachment(p_files, uid: str) -> bool:
    """
    添付ファイル（CSV/Excel/TSV）を DataFrame に変換し TableChat セッションに保持。
    Returns: True → TableChat 処理完了 / False → スキップ
    """
    import io as _io
    if not p_files:
        return False

    for f in p_files:
        fname = (getattr(f, "name", "") or "").lower()
        ftype = (getattr(f, "type", "") or "").lower()

        is_spreadsheet = (
            fname.endswith(".csv") or fname.endswith(".tsv")
            or fname.endswith(".xlsx") or fname.endswith(".xls")
            or "spreadsheet" in ftype or "excel" in ftype
            or "csv" in ftype
        )
        if not is_spreadsheet:
            continue

        try:
            raw_bytes = f.read() if hasattr(f, "read") else bytes(getattr(f, "getvalue", lambda: b"")())
            if not raw_bytes:
                continue

            if fname.endswith(".xlsx") or fname.endswith(".xls") or "excel" in ftype:
                # まず header=0 で試み、Unnamed列が半数超なら2行ヘッダーとして再読み込み
                df = pd.read_excel(_io.BytesIO(raw_bytes))
                _unnamed_ratio = sum(1 for c in df.columns if str(c).startswith("Unnamed")) / max(len(df.columns), 1)
                if _unnamed_ratio > 0.4:
                    try:
                        df2 = pd.read_excel(_io.BytesIO(raw_bytes), header=[0, 1])
                        # MultiIndex列を "親列_子列" で結合（Unnamed部分は親列名だけ使う）
                        new_cols = []
                        for col in df2.columns:
                            top = str(col[0]).strip()
                            sub = str(col[1]).strip()
                            top_clean = "" if top.startswith("Unnamed") else top
                            sub_clean = "" if sub.startswith("Unnamed") else sub
                            if top_clean and sub_clean:
                                new_cols.append(f"{top_clean}_{sub_clean}")
                            elif top_clean:
                                new_cols.append(top_clean)
                            elif sub_clean:
                                new_cols.append(sub_clean)
                            else:
                                new_cols.append(f"col_{len(new_cols)}")
                        df2.columns = new_cols
                        df = df2
                    except Exception:
                        pass
                # 残存Unnamed列を削除（完全にUnnamedのみの列は不要）
                df = df[[c for c in df.columns if not str(c).startswith("Unnamed")]]
                fmt = "excel"
            elif fname.endswith(".tsv"):
                df = pd.read_csv(_io.StringIO(raw_bytes.decode("utf-8", errors="replace")), sep="\t")
                fmt = "tsv"
            else:
                # CSV: エンコード自動検出
                for enc in ("utf-8", "shift_jis", "cp932", "utf-8-sig"):
                    try:
                        df = pd.read_csv(_io.StringIO(raw_bytes.decode(enc)), sep=None, engine="python")
                        fmt = "csv"
                        break
                    except Exception:
                        df = None
                        fmt = ""
                if df is None:
                    continue

            if df is None or df.empty:
                continue

            # 数値化
            for col in df.columns:
                df[col] = df[col].apply(_tc_try_numeric)

            tc_set_session_table(uid, df, raw_text=fname, fmt=fmt)

            summary = tc_render_summary(df)
            with st.chat_message("user"):
                st.markdown(f"📎 **添付ファイル** `{getattr(f, 'name', fname)}` を表として読み込みました（{len(df)}行 × {len(df.columns)}列）")
            with st.chat_message("assistant"):
                st.markdown(summary)
                st.dataframe(df, use_container_width=True, hide_index=True)

            return True

        except Exception as _fe:
            try:
                if os.environ.get("TABLECHAT_DEBUG", "").lower() in ("1", "true"):
                    st.warning(f"[TableChat attachment] {_fe}")
            except Exception:
                pass
            continue

    return False


# ── 2-13. 永続表セッション保存（Firestore table_sessions）────────────
def tc_save_table_session(uid: str, tenant_id: str, df: pd.DataFrame, fmt: str = ""):
    """
    現在の表セッションを Firestore の table_sessions コレクションに保存。
    doc_id = uid（ユーザー単位で上書き保存）
    """
    try:
        db = firestore.Client()
        record = {
            "uid": uid,
            "tenant_id": tenant_id,
            "fmt": fmt,
            "saved_at": firestore.SERVER_TIMESTAMP,
            "rows": len(df),
            "cols": len(df.columns),
            "columns": [str(c) for c in df.columns],
            "data_json": df.to_json(force_ascii=False, orient="split"),
        }
        db.collection("table_sessions").document(uid).set(record)
    except Exception as _e:
        try:
            if os.environ.get("TABLECHAT_DEBUG", "").lower() in ("1", "true"):
                st.warning(f"[TableChat] Firestore save failed: {_e}")
        except Exception:
            pass


def tc_load_table_session(uid: str, tenant_id: str = "") -> bool:
    """
    Firestore から table_sessions を復元してセッションに再保持。
    Returns: True → 復元成功 / False → データなし or エラー
    """
    try:
        db = firestore.Client()
        doc = db.collection("table_sessions").document(uid).get()
        if not doc.exists:
            return False
        data = doc.to_dict() or {}
        if tenant_id and data.get("tenant_id", "") != tenant_id:
            return False
        data_json = data.get("data_json", "")
        if not data_json:
            return False
        import io as _io
        df = pd.read_json(_io.StringIO(data_json), orient="split")
        # 数値列を正しく復元（JSONからの読み戻しで文字列化するのを防ぐ）
        for _col in df.columns:
            df[_col] = df[_col].apply(_tc_try_numeric)
        fmt = data.get("fmt", "")
        tc_set_session_table(uid, df, raw_text="(restored)", fmt=fmt)
        return True
    except Exception:
        return False


def tc_delete_table_session(uid: str):
    """Firestore から table_sessions を削除"""
    try:
        db = firestore.Client()
        db.collection("table_sessions").document(uid).delete()
    except Exception:
        pass


# ============================================================
# /TABLECHAT Phase2
# ============================================================

# ============================================================
# /TABLECHAT Phase1
# ============================================================
# -----------------------------
# Share token detection
# -----------------------------
# 必ず先に初期化（NameError防止）
_shared_mode = False
_raw_share = ""
_url_share = ""

# ★ 共有URLは「URLパラメータのshare」を唯一の入口として扱う（cookie share は干渉要因なので使わない）
try:
    _url_share = _qp_get_first("share", "").strip()
except Exception:
    _url_share = ""

_raw_share = _url_share

# share が無い場合は shared 状態を持ち越さない（通常ログインと干渉させない）
if not _raw_share:
    st.session_state.pop(SS_SHARED, None)
    st.session_state.pop(SS_SHARE_TENANT, None)

if _raw_share:
    _cur_auth = st.session_state.get(SS_AUTH, {})
    _cur_role = _cur_auth.get("role", "")

    if _cur_role == ROLE_ADMIN:
        # 管理者セッション中は共有URLを無効化（混線防止）
        _raw_share = ""
    else:
        try:
            info = validate_share_token(_raw_share)
        except Exception:
            info = None

        if info:
            _share_uid = (info.get("uid") or "").strip()
            _share_tenant = (info.get("tenant_id") or info.get("tenant") or "").strip()

            if _share_uid:
                _shared_mode = True
                st.session_state.pop(SS_SHARE_ENDED, None)
                st.session_state[SS_SHARED] = True
                if _share_tenant:
                    st.session_state[SS_SHARE_TENANT] = _share_tenant

                # ★ 共有URLは通常auth cookieを一切変更しない（メモリ上だけで認証）
                set_auth_session(ROLE_USER, _share_uid)
        else:
            # 無効・期限切れtoken → 共有状態だけクリアしてログインへ
            st.session_state.pop(SS_SHARED, None)
            st.session_state.pop(SS_SHARE_TENANT, None)
