            # 選択ラベルからIDに逆引き
            # index()は先頭ヒットのみ返すため、selectboxのindexから直接IDを引く
            _sb_sel_idx = _chat_labels.index(_selected_label) if _selected_label in _chat_labels else 0
            _selected_id = _chat_options[_sb_sel_idx] if _sb_sel_idx < len(_chat_options) else "main"
            if _selected_id != st.session_state.get(SS_CHAT_ID):
                st.session_state[SS_CHAT_ID] = _selected_id
