                                st.write(f"カテゴリ: {op.get('category','')}")
                                st.write(f"許可プラン: {', '.join(op.get('allowed_plans',[]))}")
                                st.write(f"承認必須: {op.get('required_approval',True)}")
                                st.write(f"action_types: {', '.join(op.get('action_types',[]))}")
